.fork-gal-runtime-rows { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 6px 8px; max-height: 40vh; margin: 4px 0 0; padding: 8px 10px; overflow-y: auto; list-style: none; border-radius: min(var(--gal-ui-radius), 10px); background: var(--gal-ui-surface-2); box-shadow: inset 0 0 0 1px var(--gal-ui-line); color: var(--gal-ui-ink); font-size: 12px; line-height: 1.5; cursor: auto; user-select: text; -webkit-user-select: text; }
