/* Theme picker (card stage settings) */
.fork-stage-themes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.fork-bubble-settings .fork-stage-theme { display: grid; grid-template-columns: auto 1fr; grid-template-rows: auto auto; column-gap: 10px; align-items: center; margin: 0; padding: 8px 10px; border: 1.5px solid var(--fork-hairline); border-radius: 12px; background: transparent; color: var(--fork-ink); text-align: left; cursor: pointer; }
.fork-bubble-settings .fork-stage-theme[aria-checked="true"] { border-color: var(--fork-accent); background: color-mix(in srgb, var(--fork-accent) 8%, var(--fk-current-bgSolid, Canvas)); }
.fork-stage-theme b { font: 600 12.5px/1.3 var(--fork-font-ui); }
.fork-stage-theme small { grid-column: 2; color: var(--fork-ink-3); font-size: 11px; }
/* Swatches: one set of flat, same-size boxes in the theme's text-box colour with its cue glyph centred
   (classic ▼, gothic gold ◆, magical ♥); no borders, rings or gradients, so none reads as a frame in a frame. */
.fork-stage-theme-swatch { grid-row: 1 / 3; display: grid; place-items: center; flex: none; box-sizing: border-box; width: 30px; height: 20px; padding: 0; border-radius: 5px; corner-shape: round; background: #1b1726; box-shadow: none; }
.fork-stage-theme-swatch i { display: block; width: 8px; height: 6px; clip-path: polygon(0 0, 100% 0, 50% 100%); background: #f5f2fa; }
.fork-stage-theme[data-theme="gothic"] .fork-stage-theme-swatch { background: #1a1228; }
.fork-stage-theme[data-theme="gothic"] .fork-stage-theme-swatch i { width: 7px; height: 10px; clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); background: #e3c77e; }
.fork-stage-theme[data-theme="magical"] .fork-stage-theme-swatch { background: #f59ac2; }
/* 显像管 swatch: a scanned tube with a phosphor block cursor. */
.fork-stage-theme[data-theme="crt"] .fork-stage-theme-swatch { background: repeating-linear-gradient(180deg, #0c2216 0 2px, #06110c 2px 3px); box-shadow: inset 0 0 0 1px #1d5a33; }
.fork-stage-theme[data-theme="crt"] .fork-stage-theme-swatch i { width: 5px; height: 10px; clip-path: none; background: #4dff88; box-shadow: 0 0 4px #4dff88; }
/* 千禧晴空 swatch: the sky-white glass with its glossy blue next-cue triangle. */
.fork-stage-theme[data-theme="aero"] .fork-stage-theme-swatch { background: #dcefff; }
.fork-stage-theme[data-theme="aero"] .fork-stage-theme-swatch i { width: 10px; height: 8px; clip-path: polygon(0 0, 100% 0, 50% 100%); background: linear-gradient(180deg, #8fd8ff 0%, #3aa2ea 30%, #1172c8 58%, #0a5fae 100%); }
.fork-stage-theme[data-theme="magical"] .fork-stage-theme-swatch i { width: 10px; height: 9px; clip-path: path("M5 9 C5 9 0 5.9 0 2.8 C0 1.15 1.25 0 2.65 0 C3.65 0 4.5 .6 5 1.4 C5.5 .6 6.35 0 7.35 0 C8.75 0 10 1.15 10 2.8 C10 5.9 5 9 5 9 Z"); background: #fff; }
/* Section subtitle: a few words saying what the library is for */
.fork-section-sub { flex: 1 1 auto; min-width: 0; overflow: hidden; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); white-space: nowrap; text-overflow: ellipsis; }
.fork-bubble-section-head > .fork-section-sub + .fork-voice-health { margin-left: 0; }
.fork-stage-card .fork-bubble-section-head > strong { align-items: center; }
/* Stage mode rows use the shared .fork-set-row / .fork-set-label / .fork-set-control layout (对话气泡 settings below). */
.fork-stage-control { min-width: 0; }
.fork-stage-themes { display: flex; gap: 8px; grid-template-columns: none; }
.fork-bubble-settings .fork-stage-theme { display: inline-flex; grid-template-columns: none; align-items: center; gap: 8px; padding: 4px 12px 4px 5px; border-radius: 999px; }
.fork-stage-theme .fork-stage-theme-swatch { grid-row: auto; }
.fork-bubble-settings .fork-stage-bg-pick { position: relative; display: flex; align-items: flex-end; justify-content: space-between; width: 180px; max-width: 100%; aspect-ratio: 16 / 7; margin: 0; padding: 0; overflow: hidden; border: 1.5px solid var(--fork-hairline); border-radius: 10px; background: linear-gradient(135deg, #3b2d57, #120e1c) center / cover no-repeat; color: #fff; cursor: pointer; }
.fork-bubble-settings .fork-stage-bg-pick:hover, .fork-bubble-settings .fork-stage-bg-pick[aria-expanded="true"] { border-color: var(--fork-accent); }
.fork-stage-bg-pick span { flex: 1; padding: 12px 8px 5px; background: var(--fk-current-mediaScrim, none); font: 500 12px/1.3 var(--fork-font-ui); text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fork-stage-bg-pick .fork-icon { position: absolute; top: 6px; right: 6px; padding: 2px; border-radius: 50%; background: var(--fk-current-mediaChip, #16141c); }
.fork-stage-bg-grid { margin-left: calc(var(--fork-set-label-w, 8.6em) + 10px); grid-template-columns: repeat(auto-fill, minmax(118px, 1fr)); }
.fork-stage-switch { display: flex; align-items: center; justify-content: space-between; gap: 10px; color: var(--fork-ink-3); font-size: 12px; cursor: pointer; }
.fork-stage-range { display: grid; gap: 6px; }
.fork-bubble-settings .fork-stage-range-summary { display: inline-flex; align-items: center; gap: 4px; width: fit-content; margin: 0; padding: 2px 6px; border: 0; border-radius: 6px; background: transparent; color: var(--fork-accent); font: 500 12px/1.4 var(--fork-font-ui); cursor: pointer; }
.fork-bubble-settings .fork-stage-range-summary:hover { background: var(--fork-hover); }
.fork-bubble-settings .fork-bg-tag:is([aria-selected], [aria-pressed]):not(.is-on) { border-color: var(--fork-hairline); background: transparent; color: var(--fork-ink-2); }
.fork-bubble-settings .fork-bg-tag.is-on { border-color: transparent; background: var(--fork-accent-fill); color: var(--fork-on-accent); }
.fork-bubble-settings .dsh-tavern-btn.fork-bg-paint { display: inline-flex; align-items: center; gap: 5px; border-color: color-mix(in srgb, var(--fork-accent) 45%, var(--fork-hairline)); color: var(--fork-accent); }
.fork-bg-painting { display: grid; justify-items: center; gap: 8px; color: var(--fork-ink-2); }
/* Magnifier on picture thumbnails */
.fork-bg-cell { position: relative; min-width: 0; }
.fork-bg-cell > .fork-bg-thumb, .fork-bg-cell > .fork-bg-editor-image { width: 100%; }
.fork-bg-editor > .fork-bg-cell { align-self: start; }
.fork-stage-control > .fork-bg-cell { width: fit-content; max-width: 100%; }
.fork-bubble-settings .fork-bg-zoom { position: absolute; top: 6px; right: 6px; z-index: 1; display: grid; place-items: center; width: 24px; height: 24px; margin: 0; padding: 0; border: 0; border-radius: 50%; background: var(--fk-current-mediaChip, #16141c); color: var(--fk-current-mediaFg, #fff); cursor: zoom-in; transition: background .15s; }
.fork-bubble-settings .fork-bg-cell:hover .fork-bg-zoom, .fork-bubble-settings .fork-bg-zoom:focus-visible { background: #2a2733; }
.fork-bubble-settings .fork-bg-zoom:hover { background: #000; }
.fork-stage-control > .fork-bg-cell .fork-bg-zoom { right: 30px; }
.fork-bubble-settings .fork-bg-thumb[aria-checked="true"]::after { right: auto; left: 6px; }
/* Outfits row on a roster card */
.fork-outfits { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.fork-outfits-title { display: inline-flex; align-items: center; gap: 4px; margin-right: 2px; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); }
.fork-outfit { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 4px 0 10px; border: 1px solid color-mix(in srgb, var(--bubble-color) 35%, var(--fork-hairline)); border-radius: 999px; background: color-mix(in srgb, var(--bubble-color) 8%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink); font-size: var(--fork-fs-meta); }
.fork-outfit.is-default { padding-right: 8px; border-color: color-mix(in srgb, var(--bubble-color) 60%, transparent); }
.fork-outfit small { color: var(--fork-ink-3); font-size: 10.5px; }
.fork-bubble-settings .fork-outfit button { display: grid; place-items: center; width: 18px; height: 18px; margin: 0; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--fork-ink-3); font-size: var(--fork-fs-body); line-height: 1; cursor: pointer; }
.fork-bubble-settings .fork-outfit button:hover { background: var(--fork-hover); color: var(--dsh-tavern-accent-error); }
.fork-outfit-add { position: relative; display: inline-flex; align-items: center; gap: 3px; height: 24px; padding: 0 10px 0 8px; border: 1px dashed var(--fork-hairline); border-radius: 999px; color: var(--fork-accent); font-size: var(--fork-fs-meta); cursor: pointer; }
.fork-outfit-add::after { content: "添加"; }
.fork-bubble-settings .fork-outfit-add select { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; opacity: 0; cursor: pointer; }
.fork-outfit-add:hover { border-color: var(--fork-accent); }
/* Long picker menus: filter box + scrolling list with group headings */
.fork-voice-menu { width: 260px; }
.fork-voice-menu-list { display: grid; gap: 2px; max-height: min(360px, 55vh); overflow-y: auto; overscroll-behavior: contain; }
:is(.fork-bubble-settings, .fork-popover) .fork-voice-menu-search { box-sizing: border-box; width: 100%; height: 30px; margin: 0 0 4px; padding: 0 10px; border: 1px solid var(--fork-hairline); border-radius: 8px; background-color: Canvas; background-image: linear-gradient(var(--dsw-specific-input-major, transparent), var(--dsw-specific-input-major, transparent)), linear-gradient(var(--fork-surface), var(--fork-surface)); color: var(--fork-ink); font: 12.5px/1 var(--fork-font-ui); }
.fork-voice-menu-group { position: sticky; top: 0; z-index: 1; padding: 6px 8px 3px; background: linear-gradient(var(--dsw-specific-menu, var(--fork-surface-2)), var(--dsw-specific-menu, var(--fork-surface-2))), Canvas; color: var(--fork-ink-3); font: 600 11px/1.2 var(--fork-font-ui); }
/* Static portraits */
.fork-static-editor { display: grid; gap: 8px; padding-top: 10px; border-top: 1px dashed var(--fork-hairline); }
.fork-static-grid { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); gap: 6px; }
.fork-static-slot { position: relative; display: grid; justify-items: center; gap: 3px; min-width: 0; color: color-mix(in srgb, var(--mood-color) 80%, var(--fork-ink)); font: 500 11px/1.2 var(--fork-font-ui); }
.fork-bubble-settings .fork-static-pick { display: grid; place-items: center; width: 100%; aspect-ratio: 3 / 4; margin: 0; padding: 0; overflow: hidden; border: 1.5px dashed color-mix(in srgb, var(--mood-color) 50%, transparent); border-radius: 8px; background: repeating-conic-gradient(var(--fk-current-hover, var(--fork-hover, Canvas)) 0 25%, var(--fk-current-bgSolid, Canvas) 0 50%) 0 0 / 10px 10px; color: var(--mood-color); cursor: pointer; }
.fork-static-slot.has .fork-static-pick { border-style: solid; }
.fork-static-pick img { width: 100%; height: 100%; object-fit: contain; }
.fork-static-slot .fork-bg-zoom { top: 3px; right: 3px; width: 20px; height: 20px; }
.fork-bubble-settings .fork-static-clear { position: absolute; top: 3px; left: 3px; display: grid; place-items: center; width: 18px; height: 18px; margin: 0; padding: 0; border: 0; border-radius: 50%; background: var(--fk-current-mediaChip, #16141c); color: #fff; font-size: var(--fork-fs-meta); line-height: 1; cursor: pointer; }
.fork-voice-option-badge.is-large img { width: 100%; height: 100%; object-fit: cover; object-position: top; }
@media (max-width: 520px) { .fork-static-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); } }
/* The card's own floating widgets (e.g. its BGM ball) stay usable above the stage. Keyed on the
   body-level stage mount (a sibling), not an <html> attribute: toggling that would restyle every div. */
body > div:has(> .bgm-host):is(:has(~ .fork-gal-mount), .fork-gal-mount ~ div) { z-index: 2147483001 !important; }
/* Stage music control (top-left, next to the place name) */
.fork-gal-topleft { display: flex; align-items: center; gap: 12px; min-width: 0; }
.fork-gal-music { display: inline-flex; align-items: center; gap: 6px; box-sizing: border-box; height: 30px; padding: 0 10px 0 4px; border-radius: 999px; background: none; box-shadow: none; filter: var(--gal-ui-hud-glow); color: var(--gal-ui-hud-ink); font: 500 12px/1 var(--fork-font-ui); }
.fork-gal-stage .fork-gal-music-toggle { display: grid; place-items: center; width: 24px; height: 24px; margin: 0; padding: 0; border: 0; border-radius: 50%; background: transparent; color: inherit; cursor: pointer; }
.fork-gal-stage .fork-gal-music-toggle:hover { background: var(--gal-ui-hud-hover); }
.fork-gal-music:not(.is-muted) .fork-gal-music-toggle .fork-icon { animation: fork-gal-note 2.4s ease-in-out infinite; }
@keyframes fork-gal-note { 50% { transform: translateY(-1px) rotate(-8deg); } }
.fork-gal-music-name { max-width: 16em; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; letter-spacing: .04em; }
.fork-gal-music input[type="range"] { width: 0; visibility: hidden; transition: width .2s, visibility 0s .2s; accent-color: var(--gal-ui-accent); }
.fork-gal-music:hover input[type="range"], .fork-gal-music:focus-within input[type="range"] { width: 90px; visibility: visible; transition: width .2s; }
.fork-gal-music.is-muted { color: var(--gal-ui-hud-ink-idle); }
/* Music library */
.fork-music-list { display: grid; gap: 2px; max-height: 320px; overflow-y: auto; }
.fork-music-row { display: flex; align-items: center; gap: 4px; min-width: 0; padding: 2px 4px; border-radius: 8px; }
.fork-music-row:hover, .fork-music-row.is-playing { background: var(--fork-hover); }
.fork-music-row.is-playing .fork-bubble-icon-button { color: var(--fork-accent); }
.fork-bubble-settings .fork-music-main { display: flex; flex: 1; align-items: baseline; gap: 8px; min-width: 0; margin: 0; padding: 4px 2px; border: 0; background: transparent; color: var(--fork-ink); text-align: left; cursor: pointer; }
.fork-music-main b { flex: none; font: 600 12.5px/1.3 var(--fork-font-ui); }
.fork-music-main small { overflow: hidden; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); white-space: nowrap; text-overflow: ellipsis; }
.fork-music-editor { display: grid; gap: 6px; padding: 10px; border: 1px solid var(--fork-hairline); border-radius: 12px; background: var(--fork-surface); }
.fork-music-editor input { box-sizing: border-box; width: 100%; height: 30px; padding: 0 8px; border: 1px solid var(--fork-hairline); border-radius: 7px; background: var(--dsw-specific-input-major, transparent); color: var(--fork-ink); font: 12.5px/1.4 var(--fork-font-ui); }
.fork-music-source { display: flex; align-items: center; gap: 6px; }
.fork-music-file { display: inline-flex; flex: 1; align-items: center; gap: 6px; min-width: 0; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); white-space: nowrap; text-overflow: ellipsis; }
/* ---------- Motion (user decision) ----------
   DSH Tavern keeps its animations even when Windows asks for reduced motion: every fork
   "reduced motion" block above is scoped to (update: none), which never matches a screen.
   The host's thinking shimmer is re-enabled the same way. */
@keyframes fork-turn-status-shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }
@media (prefers-reduced-motion: reduce) {
  body.dsh-tavern-shell-active [role="status"][class*="_turnStatus"] { background-size: 250% 100%; background-position: 100% 0; animation: fork-turn-status-shimmer 1.8s linear infinite; }
}
/* ---------- Floating layers stay readable on translucent skins ----------
   Dream skins make --dsw-specific-menu translucent (e.g. rose: 60% alpha) for a glass look,
   but only a few host panels get a backdrop blur, so menus and tooltips showed the text
   behind them. Paint the menu tint over an opaque base (Canvas follows the colour scheme)
   and blur whatever is behind. The stage's own menus (choices, the system menu, the widget menus, the danmaku menu) are opaque in the stage tokens. */
:is([role="menu"]:not(.fork-gal-choices, .fork-gal-menu-panel, .fork-widget-context, .fork-widget-menu-list, .fork-gal-danmaku-menu), [role="listbox"]:not(.fork-voice-slots), [role="tooltip"], [data-radix-popper-content-wrapper] > *, .dsh-tavern-more-menu, .dsh-tavern-prompt-panel, .dsh-tavern-group-menu) {
  background-image: linear-gradient(var(--dsw-specific-menu, transparent), var(--dsw-specific-menu, transparent)), linear-gradient(Canvas, Canvas);
}
body[data-ds-dark-theme] :is([role="menu"]:not(.fork-gal-choices, .fork-gal-menu-panel, .fork-widget-context, .fork-widget-menu-list, .fork-gal-danmaku-menu), [role="listbox"]:not(.fork-voice-slots), [role="tooltip"], [data-radix-popper-content-wrapper] > *, .dsh-tavern-more-menu, .dsh-tavern-prompt-panel, .dsh-tavern-group-menu) { color-scheme: dark; }
/* Folding: section chevrons, folded roster cards, portrait groups */
.fork-bubble-settings .fork-section-fold, .fork-bubble-settings .fork-card-fold { display: inline-grid; place-items: center; width: 22px; height: 22px; margin: 0 -2px 0 -4px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--fork-ink-3); cursor: pointer; }
.fork-bubble-settings .fork-card-fold { width: 28px; height: 28px; margin: 0; }
.fork-section-fold .fork-icon, .fork-card-fold .fork-icon, .fork-portrait-group-head > .fork-icon { transition: transform .15s; }
.fork-section-fold[aria-expanded="false"] .fork-icon, .fork-card-fold[aria-expanded="false"] .fork-icon, .fork-portrait-group-head[aria-expanded="false"] > .fork-icon { transform: rotate(-90deg); }
.fork-bubble-settings .fork-section-fold:hover, .fork-bubble-settings .fork-card-fold:hover { background: var(--fork-hover); color: var(--fork-ink); }
.fork-bubble-card.is-folded { padding-bottom: 10px; }
.fork-portrait-groups { display: grid; gap: 6px; }
.fork-portrait-group { border: 1px solid var(--fork-hairline); border-radius: 12px; background: var(--fork-surface); }
.fork-portrait-group > .fork-voice-entries { padding: 0 8px 8px; }
.fork-bubble-settings .fork-portrait-group-head { display: flex; align-items: center; gap: 8px; width: 100%; margin: 0; padding: 8px 10px; border: 0; border-radius: 12px; background: transparent; color: var(--fork-ink); text-align: left; cursor: pointer; }
.fork-bubble-settings .fork-portrait-group-head:hover { background: var(--fork-hover); }
.fork-portrait-group-head b { flex: none; font: 600 13px/1.2 var(--fork-font-ui); }
.fork-portrait-group-head em { flex: none; padding: 1px 7px; border-radius: 999px; background: color-mix(in srgb, var(--fork-accent) 14%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-accent); font: 500 10.5px/1.5 var(--fork-font-ui); font-style: normal; }
.fork-portrait-strip { display: flex; flex: 1; justify-content: flex-end; min-width: 0; overflow: hidden; }
.fork-portrait-strip img, .fork-portrait-strip i { flex: none; width: 30px; height: 30px; margin-left: -6px; border-radius: 50%; object-fit: cover; object-position: top; background: var(--fork-hover); box-shadow: 0 0 0 2px var(--fork-surface); }
.fork-voice-option-badge.is-portrait { border-radius: 12px; background: color-mix(in srgb, var(--fork-accent) 10%, var(--fork-surface)); box-shadow: 0 0 0 1px var(--fork-hairline); }
.fork-voice-option-badge.is-portrait img { object-position: top; }
/* Foldable sections: whole header toggles; folded sections show only the header */
.fork-bubble-section-head.is-foldable { cursor: pointer; border-radius: 8px; margin: -4px -6px; padding: 4px 6px; }
.fork-bubble-section-head.is-foldable:hover { background: var(--fork-hover); }
.fork-bubble-section-head.is-foldable:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.fork-fold-chevron { display: inline-grid; flex: none; place-items: center; width: 16px; color: var(--fork-ink-3); transition: transform .15s; }
.fork-bubble-section-head[aria-expanded="false"] .fork-fold-chevron { transform: rotate(-90deg); }
.fork-bubble-section.is-folded > :not(.fork-bubble-section-head) { display: none !important; }
.fork-bubble-section.is-folded { padding-bottom: 2px; }
/* ---------- Stage staging DSL ---------- */
.fork-stage-intensity .fork-bg-tag { min-width: 3.4em; text-align: center; }
/* ---------- The face window (fork) ---------- */
/* Face window: the speaker's head and shoulders rise out of the left end of the box. */
.fork-gal-box { --face-w: clamp(116px, 12vw, 184px); --face-rise: 0px; --face-gap: clamp(12px, 1.4vw, 22px); }
/* Only lines that show a face make room for it; narration and faceless speakers use the full width. */
.fork-gal-box.is-facing { padding-left: calc(var(--face-w) + var(--face-gap)); }
.fork-gal-box.is-facing .fork-gal-meta { left: calc(var(--face-w) + var(--face-gap)); }
.fork-gal-face { position: absolute; left: 6px; top: 6px; bottom: 6px; z-index: 1; width: var(--face-w); height: auto; overflow: hidden; border-bottom-left-radius: 4px; pointer-events: none;
  -webkit-mask-image: linear-gradient(to right, transparent, #000 9%, #000 91%, transparent); mask-image: linear-gradient(to right, transparent, #000 9%, #000 91%, transparent); }
.fork-gal-face::before { content: ""; position: absolute; inset: 0; background: radial-gradient(80% 90% at 50% 100%, color-mix(in srgb, var(--bubble-color) 34%, transparent), transparent 72%); opacity: 0; transition: opacity .45s ease; }
.fork-gal-face.is-on::before { opacity: 1; }
.fork-gal-face-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; object-position: 50% 100%; animation: fork-gal-face-in .45s cubic-bezier(.2,.7,.3,1) both; }
@keyframes fork-gal-face-in { from { opacity: 0; transform: translateY(8%); } }
.fork-gal-stage[data-theme="magical"] .fork-gal-face { left: 11px; top: 11px; bottom: 11px; height: auto; border-radius: 19px 0 0 19px; }
@media (max-width: 640px) { .fork-gal-box { --face-w: 88px; } }
.fork-stage-card .fork-stage-select { width: auto; min-width: min(180px, 100%); max-width: 100%; height: 30px; padding: 0 28px 0 10px; border: 1px solid var(--fork-hairline); border-radius: var(--fork-radius); background: var(--fork-raised, var(--fork-surface)); color: var(--fork-ink); font: inherit; font-size: 12.5px; }
/* ---------- 本卡素材 (card asset pack) ---------- */
.fork-bubble-scope[data-scope="pack"] { margin-top: 8px; padding: 10px 12px 12px; border: 1px solid var(--fork-hairline); border-radius: 14px; background: color-mix(in srgb, var(--fork-accent) 4%, var(--fk-current-bgSolid, Canvas)); }
.fork-bubble-scope[data-scope="pack"] > .fork-bubble-section { padding-top: 0; border-top: 0; }
.fork-pack-head { display: grid; gap: 8px; min-width: 0; }
.fork-pack-head-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-width: 0; }
