  --gal-base-font: "Noto Sans SC", "Source Han Sans SC", "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei", sans-serif;
  /* empty-stage palette shared by the renderer and opening thumbnails. */
  --gal-empty-accent: #9572cc;
  --gal-empty-surface: #1d1630;
  --gal-empty-deep: #0e0b16;
  /* 「文字演出」 flat card palette and faces (textcard.css); story content, not UI chrome.
     The renderer swaps in the face TEXTCARD_FACE picks (--tc-mincho; default: the library's full Noto Serif SC) once registered. */
  --gal-tc-ink: #171517; --gal-tc-paper: #f4eee1; --gal-tc-vermilion: #b52e31; --gal-tc-gold: #d3ae45;
  --gal-tc-mincho: "Noto Serif SC", "Source Han Serif SC", "Songti SC", serif;
  --gal-tc-mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
  --gal-tc-italic: Georgia, "Times New Roman", serif;
  --gal-ui-surface: var(--fk-s-stage-panel-bgSolid);
  --gal-ui-surface-2: var(--fk-s-stage-panel-bgSolid);
  --gal-ui-ink: var(--gal-base-ink);
  --gal-ui-ink-2: var(--fk-s-stage-panel-fgMuted);
  --gal-ui-accent: var(--fk-s-stage-panel-accent);
  --gal-ui-accent-ink: var(--fk-s-stage-panel-onAccent);
  /* Story-specified widget colours mix with readable ink on both pale and dark surfaces. */
  --gal-ui-widget-pink: color-mix(in srgb, var(--gal-base-ink) 60%, deeppink);
  --gal-ui-widget-info: color-mix(in srgb, var(--gal-base-ink) 70%, steelblue);
  --gal-ui-widget-warning: color-mix(in srgb, var(--gal-base-ink) 70%, darkorange);
  /* the dice throw (dice-throw.js): the tens die in the panel paint with accent numbers, the ones die in
     the accent paint; the critical burst's gold; the hidden roll's 骰盅 is a physical prop - black-red lacquer with grain,
     brass bands, a talisman of aged paper and cinnabar - with its contact shadow and dust. */
  --gal-dice-a: var(--gal-ui-surface); --gal-dice-a-ink: var(--gal-ui-accent);
  --gal-dice-b: var(--gal-ui-accent); --gal-dice-b-ink: var(--gal-ui-accent-ink);
  --gal-dice-gold: #f2c75c;
  --gal-dice-lacquer: #3a0f0b; --gal-dice-lacquer-grain: #8a3220; --gal-dice-brass: #c9993f;
  --gal-dice-paper: #eadcb8; --gal-dice-paper-edge: #c9b07a; --gal-dice-cinnabar: #b3261e;
  --gal-dice-shadow: #0b0608; --gal-dice-dust: #e8dcc0;
  --gal-ui-line: var(--fk-s-stage-panel-line);
  --gal-ui-track: color-mix(in srgb, var(--gal-base-ink) 12%, transparent);
  --gal-ui-thumb: color-mix(in srgb, var(--gal-base-accent) 45%, transparent);
  --gal-ui-radius: var(--gal-base-radius);
  --gal-ui-font: var(--gal-base-font);
  --gal-ui-title-font: var(--gal-base-font);
  --gal-ui-meta-size: var(--fork-fs-meta);
  /* the stage choice menu's type size (ribbons, field, wait chip). */
  /* --fk-text-scale = the current skin's text percent (the stage root, unset at 100%). */
  --gal-ui-choice-size: calc(clamp(15px, calc(.5vw + .65vh), 19px) * var(--fk-text-scale, 1));
  /* the round 重新生成 badge on the 自由输入 row (stage choices; 44px on phones and touch). */
  --gal-ui-choice-tool: max(44px, calc(var(--gal-ui-choice-size) * 1.9));
  /* the choice ribbons' feathered ends. A two-stop linear ramp
     had a visible knee where it met the solid middle (and at the scene end) and a hard band on dark fills. The ramp now
     follows smoothstep (3t^2 - 2t^3, flat at both ends) in 12 steps a side, and its length follows the ribbon - 20% less
     36px, never under 30px or over 116px (about 39px on a phone, 116px on a desktop) - so the ease reads the same at
