    rgb(0 0 0) var(--gal-ui-ribbon-fade) calc(100% - var(--gal-ui-ribbon-fade)),
    rgb(0 0 0 / .9803) calc(100% - var(--gal-ui-ribbon-fade) * .9167), rgb(0 0 0 / .9259) calc(100% - var(--gal-ui-ribbon-fade) * .8333), rgb(0 0 0 / .8438) calc(100% - var(--gal-ui-ribbon-fade) * .75), rgb(0 0 0 / .7407) calc(100% - var(--gal-ui-ribbon-fade) * .6667), rgb(0 0 0 / .6238) calc(100% - var(--gal-ui-ribbon-fade) * .5833), rgb(0 0 0 / .5) calc(100% - var(--gal-ui-ribbon-fade) * .5), rgb(0 0 0 / .3762) calc(100% - var(--gal-ui-ribbon-fade) * .4167), rgb(0 0 0 / .2593) calc(100% - var(--gal-ui-ribbon-fade) * .3333), rgb(0 0 0 / .1563) calc(100% - var(--gal-ui-ribbon-fade) * .25), rgb(0 0 0 / .0741) calc(100% - var(--gal-ui-ribbon-fade) * .1667), rgb(0 0 0 / .0197) calc(100% - var(--gal-ui-ribbon-fade) * .0833), rgb(0 0 0 / 0) 100%);
  --gal-film-font: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
  --gal-ui-shadow: 0 8px 28px color-mix(in srgb, var(--gal-base-bg) 35%, transparent);
  /* Row states are solid table paints (hover/selected keep the ink at 4.5:1); the scene dimmer behind full sheets. */
  --gal-ui-hover: var(--fk-s-stage-panel-hover);
  --gal-ui-active: var(--fk-s-stage-panel-selected);
  --gal-ui-dim: var(--fk-s-stage-panel-veil);
  --gal-ui-ink-disabled: var(--fk-s-stage-panel-fgDisabled);
  --gal-ui-focus: 2px solid var(--gal-ui-accent);
  --gal-ui-muted: var(--gal-ui-ink-2);
  --gal-ui-title-shadow: 0 0 18px color-mix(in srgb, var(--gal-base-accent) 25%, transparent);
  --gal-ui-text-shadow: 0 1px 2px color-mix(in srgb, var(--gal-base-bg) 55%, transparent);
  /* Choice cards: the opaque panel paint with a faint top light (both stops solid). */
  --gal-ui-veil: linear-gradient(180deg, color-mix(in srgb, var(--gal-ui-ink) 4%, var(--gal-ui-surface-2)), var(--gal-ui-surface-2));
  /* The neutral dark shown while a jump/entry waits for its page's staging (.fork-gal-scene-hold). It is the scene
