.fork-gal-side { position: absolute; left: calc(-1 * var(--cl-face-out, 20px)); bottom: calc(-1 * var(--cl-bottom, 16px)); z-index: 1; width: var(--cl-face, 220px); height: var(--cl-face, 220px); pointer-events: none; }
