.fork-gal-stage[data-theme="classic"] .fork-gal-box { --gal-box-normal-height: var(--cl-box-h); --gal-box-normal-bottom: var(--cl-bottom); }
.fork-gal-stage[data-theme="magical"] .fork-gal-box { --gal-box-safe-rise: 4px; }
.fork-gal-stage[data-theme]:not(.is-film) .fork-gal-box { height: var(--gal-box-normal-height); min-height: 0; bottom: var(--gal-box-normal-bottom); }
.fork-gal-stage[data-theme]:not(.is-film) .fork-gal-box .fork-gal-text { height: calc(3 * 1lh); min-height: 0; overflow-y: auto; overscroll-behavior: contain;
  /* the scroll box clips on every side, so it reaches --fk-text-bleed past the
     text column on both sides (padding, cancelled by a negative margin: the column and its wrap stay put) and a theme's
     text-shadow glow is never cut at the column's edge. A theme's own indent adds to it (classic below). */
  --fk-text-bleed: 1em; padding-inline: var(--fk-text-bleed); margin-inline: calc(-1 * var(--fk-text-bleed)); }
/* CONFIG 文字大小: the text area stays the skin's three lines of its own size (1lh is the scaled line), so a card of
   floor(3 / scale) scaled lines fills it and is never scrolled or clipped. */
.fork-gal-stage[data-theme][data-fk-text-scale]:not(.is-film) .fork-gal-box .fork-gal-text { height: calc(3 * 1lh / var(--fk-text-scale, 1)); }
.fork-gal-stage.is-film[data-theme] .fork-gal-box { height: var(--film-bar); }
/* Dialogs over the game (card picker, opening preparation): skins may make the surface colour translucent;
   paint it over an opaque base so what is behind never shows through. */
.dsh-tavern-card-picker, .dsh-tavern-card-picker .dsh-tavern-greeting-preview {
  background-image: linear-gradient(var(--fork-surface), var(--fork-surface)), linear-gradient(Canvas, Canvas);
}
