.fork-bg-thumb .fork-asset-badge { position: absolute; top: 6px; left: 6px; width: auto; padding: 0 6px; border: 0; background: var(--fk-current-mediaChip, #16141c); color: rgb(255 255 255 / .9); font-size: 10px; text-align: center; }
