.fork-avatar-chip-name { max-width: 100%; overflow: hidden; font-size: var(--fork-fs-meta); line-height: 1.3; white-space: nowrap; text-overflow: ellipsis; }
.fork-avatar-dot { position: absolute; top: 0; right: 0; width: 9px; height: 9px; border-radius: 50%; background: #e0704f; box-shadow: 0 0 0 2px var(--fork-surface); }
.fork-avatar-chip.is-offstage .fork-bubble-avatar { filter: var(--fk-current-dim, grayscale(1)); filter: grayscale(.6); }
.fork-avatar-chip.is-offstage .fork-avatar-chip-name { color: var(--fork-ink-3); }
.fork-avatar-badge { position: absolute; bottom: -3px; left: 50%; padding: 0 4px; transform: translateX(-50%); border-radius: 999px; background: var(--fork-ink-2); color: var(--fork-surface); font: 600 8.5px/1.5 var(--fork-font-ui); font-style: normal; white-space: nowrap; }
/* 舞台 rows (advanced) */
.fork-stage-summary { display: flex; align-items: center; gap: 8px; min-width: 0; }
.fork-stage-summary-text { flex: 1 1 auto; min-width: 0; overflow: hidden; color: var(--fork-ink-3); font-size: 12px; white-space: nowrap; text-overflow: ellipsis; }
.fork-stage-origin { flex: none; padding: 1px 8px; border-radius: 999px; background: var(--fork-hover); color: var(--fork-ink-2); font: 500 11px/1.6 var(--fork-font-ui); }
.fork-stage-origin[data-origin="card"] { background: var(--fork-accent-soft); color: var(--fork-accent); }
.fork-bubble-settings .fork-bubble-link > .fork-icon { margin-right: 3px; }

/* ---------- The settings modal (modal.js) ---------- */
.fork-modal-backdrop { position: fixed; inset: 0; z-index: 2140; display: flex; align-items: center; justify-content: center; padding: 2vh 2vw; background: var(--fk-s-modal-veil); animation: fork-modal-fade .16s ease-out; }
/* Backdrops fade their veil in (background-color only): fading the backdrop element would fade the dialog inside it. */
@keyframes fork-modal-fade { from { background-color: transparent; } }
/* Opaque on every skin: the surface tint is painted over an opaque base (see the card picker fix). */
.fork-modal { display: flex; flex-direction: column; box-sizing: border-box; width: min(80vw, 1200px); height: 80vh; min-height: min(420px, 96vh); max-width: 96vw; max-height: 96vh; overflow: hidden; border: 1px solid var(--fork-hairline); border-radius: 18px;
  background-color: Canvas; background-image: linear-gradient(var(--fork-surface), var(--fork-surface)), linear-gradient(Canvas, Canvas);
  color: var(--fork-ink); box-shadow: 0 24px 70px rgb(0 0 0 / .38), 0 2px 8px rgb(0 0 0 / .12); font: 13px/1.5 var(--fork-font-ui); outline: none; animation: fork-modal-in .2s var(--fork-ease); }
body[data-ds-dark-theme] .fork-modal { color-scheme: dark; }
@keyframes fork-modal-in { from { transform: translateY(8px) scale(.985); } }
.fork-modal-head { display: flex; flex: none; align-items: center; gap: 8px; min-width: 0; padding: 12px 14px 12px 18px; border-bottom: 1px solid var(--fork-hairline); }
.fork-modal-icon { display: grid; flex: none; place-items: center; width: 30px; height: 30px; border-radius: 9px; background: var(--fork-accent-soft); color: var(--fork-accent); }
.fork-modal-head > strong { flex: none; font-size: 15px; font-weight: 650; }
.fork-modal-subtitle { min-width: 0; overflow: hidden; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); white-space: nowrap; text-overflow: ellipsis; }
.fork-modal-tools { display: flex; flex: 1 1 auto; align-items: center; justify-content: flex-end; gap: 8px; min-width: 0; }
.fork-modal-close { display: grid; flex: none; place-items: center; width: 32px; height: 32px; margin: 0; padding: 0; border: 0; border-radius: 9px; background: transparent; color: var(--fork-ink-3); cursor: pointer; }
.fork-modal-close:hover { background: var(--fork-hover); color: var(--fork-ink); }
.fork-modal-close:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.fork-modal-main { display: flex; flex: 1 1 auto; min-height: 0; }
.fork-modal-nav { display: flex; flex: none; flex-direction: column; gap: 8px; box-sizing: border-box; width: 220px; padding: 12px 10px; overflow-y: auto; border-right: 1px solid var(--fork-hairline); background: color-mix(in srgb, var(--fork-ink) 3%, var(--fk-current-bgSolid, Canvas)); }
.fork-modal-nav-tools { display: flex; align-items: center; gap: 4px; padding: 0 2px 4px; }
.fork-modal-nav .fork-bubble-icon-button { display: inline-grid; flex: none; place-items: center; width: 28px; height: 28px; margin: 0; padding: 0; border: 0; border-radius: 7px; background: transparent; color: var(--fork-ink-2); cursor: pointer; }
.fork-modal-nav .fork-bubble-icon-button:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.fork-modal-nav-list { display: grid; gap: 2px; }
.fork-modal-nav-item { display: flex; align-items: center; gap: 9px; width: 100%; min-height: 36px; margin: 0; padding: 4px 8px; border: 0; border-radius: 9px; background: transparent; color: var(--fork-ink-2); font: 500 13px/1.3 var(--fork-font-ui); text-align: left; cursor: pointer; }
.fork-modal-nav-item:hover { background: var(--fork-hover); color: var(--fork-ink); }
.fork-modal-nav-item.is-current { background: var(--fork-accent-soft); color: var(--fork-accent); font-weight: 600; }
.fork-modal-nav-item:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: -2px; }
.fork-modal-nav-item > .fork-icon { flex: none; }
.fork-modal-nav-item.is-dim .fork-modal-nav-avatar { filter: var(--fk-current-dim, grayscale(1)); filter: grayscale(.6); }
.fork-modal-nav-label { flex: 1 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.fork-modal-nav-badge { flex: none; max-width: 7em; overflow: hidden; padding: 0 6px; border-radius: 999px; background: var(--fork-hover); color: var(--fork-ink-3); font: 500 10.5px/1.6 var(--fork-font-ui); white-space: nowrap; text-overflow: ellipsis; }
.fork-modal-nav-sep { margin: 8px 8px 2px; color: var(--fork-ink-3); font: 600 10.5px/1.4 var(--fork-font-ui); letter-spacing: .08em; }
.fork-modal-nav-avatar { position: relative; flex: none; }
.fork-modal-nav-avatar .fork-bubble-avatar { width: 26px; height: 26px; border-radius: 50%; font-size: 11px; }
.fork-modal-nav-avatar.has-dot::after { content: ""; position: absolute; top: -1px; right: -1px; width: 8px; height: 8px; border-radius: 50%; background: #e0704f; box-shadow: 0 0 0 2px var(--fork-surface); }
.fork-modal-body.fork-bubble-settings { flex: 1 1 auto; min-width: 0; min-height: 0; padding: 16px 22px 28px; overflow-y: auto; overscroll-behavior: contain; }
.fork-modal-body > .fork-bubble-section, .fork-modal-body .fork-modal-section { padding: 0; border: 0; }
.fork-modal-section + .fork-modal-section { margin-top: 10px; padding-top: 12px !important; border-top: 1px solid var(--fork-hairline) !important; }
.fork-modal-section > .fork-bubble-section-head > strong { align-items: center; font-size: 13.5px; }
.fork-modal-section > .fork-bubble-section-head > strong > .fork-icon { color: var(--fork-accent); }
.fork-modal-section { display: grid; gap: 10px; }
.fork-format-modal { width: min(80vw, 900px); }
.fork-format-modal .fork-bubble-preview pre { max-height: none; margin: 0; white-space: pre-wrap; font: 12px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
@media (max-width: 720px) {
  .fork-modal { width: 96vw; height: 92vh; }
}
/* Characters modal: the editor */
.fork-character-editor { display: grid; gap: 14px; min-width: 0; }
.fork-character-id { display: flex; align-items: flex-start; gap: 14px; min-width: 0; padding-bottom: 12px; border-bottom: 1px solid var(--fork-hairline); }
.fork-character-id .fork-bubble-avatar { width: 72px; height: 72px; font-size: 22px; }
.fork-character-fields { display: grid; flex: 1 1 auto; gap: 6px; min-width: 0; }
.fork-character-editor input:not([type]) { box-sizing: border-box; min-width: 0; margin: 0; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--fork-ink); font: inherit; }
.fork-character-editor input:not([type]):hover { border-color: var(--fork-hairline); }
.fork-character-editor input:not([type]):focus { border-color: var(--fork-accent); background: var(--dsw-specific-input-major, transparent); outline: none; }
.fork-character-editor .fork-bubble-name-input { flex: 0 1 12em; height: 32px; padding: 0 6px; font-size: 16px; font-weight: 650; }
.fork-character-editor .fork-bubble-alias input { flex: 1; height: 26px; padding: 0 4px; color: var(--fork-ink-3); font: inherit; }
.fork-character-editor .fork-bubble-note-input { height: 30px; padding: 0 8px; border-color: var(--fork-hairline) !important; font-size: var(--fork-fs-meta); }
.fork-offstage { display: flex; align-items: center; gap: 6px; }
.fork-offstage label { display: inline-flex; align-items: center; gap: 6px; color: var(--fork-ink); font-size: var(--fork-fs-meta); cursor: pointer; }
.fork-offstage input { width: 15px; height: 15px; margin: 0; accent-color: var(--fork-accent); }
.fork-character-editor .fork-bubble-moods { max-width: 640px; }
/* Assets modal: modules × sources grid */
.fork-source-quick { margin-bottom: 4px; }
.fork-source-grid { width: 100%; border-collapse: collapse; font-size: var(--fork-fs-body); }
.fork-source-grid th, .fork-source-grid td { padding: 7px 10px; border-bottom: 1px solid var(--fork-hairline); text-align: center; white-space: nowrap; }
.fork-source-grid tbody tr:last-child > * { border-bottom: 0; }
.fork-source-grid thead th { position: sticky; top: 0; background-color: Canvas; background-image: linear-gradient(var(--fork-surface), var(--fork-surface)); color: var(--fork-ink-2); font-weight: 600; }
.fork-source-grid thead th small { display: block; color: #b8761a; font-size: 10px; font-weight: 500; }
.fork-source-grid th[scope="row"], .fork-source-grid thead th:first-child { text-align: left; color: var(--fork-ink); }
.fork-source-grid .is-card { color: var(--fork-accent); }
.fork-source-grid tr.is-off th[scope="row"] { color: var(--fork-ink-3); }
.fork-bubble-settings .fork-source-toggle { display: inline-flex; align-items: center; justify-content: center; gap: 3px; min-width: 40px; height: 26px; margin: 0; padding: 0 7px; border: 1px solid var(--fork-hairline); border-radius: 8px; background: transparent; color: var(--fork-ink-3); cursor: pointer; }
.fork-bubble-settings .fork-source-toggle:hover { border-color: color-mix(in srgb, var(--fork-accent) 40%, transparent); color: var(--fork-accent); }
.fork-bubble-settings .fork-source-toggle.is-on { border-color: transparent; background: var(--fork-accent-fill); color: var(--fork-on-accent); }
.fork-bubble-settings .fork-source-toggle:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.fork-source-toggle small { font: 500 10.5px/1 var(--fork-font-ui); color: inherit; }
.fork-source-count { color: var(--fork-ink-3); font-size: var(--fork-fs-meta); text-align: right !important; }
.fork-source-count.is-warning { color: #d9942a; }
.fork-source-count.is-muted { color: var(--fk-current-fgMuted, var(--fork-ink-2, CanvasText)); }
/* Director modal */
.fork-director-rules { display: grid; gap: 8px; }
.fork-director-rules-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.fork-director-template { display: inline-flex; align-items: center; gap: 5px; color: var(--fork-accent); }
.fork-director-template select { height: 28px; }
.fork-modal-body .fork-director-rules-text { box-sizing: border-box; width: 100%; min-height: 0; padding: 10px 12px; border: 1px solid var(--fork-hairline); border-radius: 10px; background: var(--dsw-specific-input-major, transparent); color: var(--fork-ink); font: 12.5px/1.65 var(--dsw-font-mono, ui-monospace, monospace); resize: vertical; }
.fork-director-form { display: grid; gap: 14px; max-width: 760px; }
.fork-director-form-heading { display: flex; align-items: center; gap: 6px; margin: 6px 0 -4px; padding-top: 12px; border-top: 1px solid var(--fork-hairline); color: var(--fork-ink); font: 600 12.5px/1.4 var(--fork-font-ui); }
.fork-director-field { display: grid; grid-template-columns: 7em minmax(0, 1fr); align-items: center; column-gap: 14px; row-gap: 3px; }
.fork-director-field-label { color: var(--fork-ink); font: 500 13px/1.4 var(--fork-font-ui); }
.fork-director-field-control { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; min-width: 0; }
.fork-director-field-control input[type="number"] { width: 6em; box-sizing: border-box; padding: 5px 8px; border: 1px solid var(--fork-hairline); border-radius: 8px; background: var(--dsw-specific-input-major, transparent); color: var(--fork-ink); font: 500 13px/1.4 var(--fork-font-ui); font-variant-numeric: tabular-nums; }
.fork-director-field-control em { color: var(--fork-ink-3); font: 400 11.5px/1.4 var(--fork-font-ui); font-style: normal; }
.fork-director-field-hint { grid-column: 2; margin: 0; color: var(--fork-ink-3); font: 400 11.5px/1.55 var(--fork-font-ui); }
/* Native select popups follow the page scheme, not the dark modal: give options the modal's colors. */
.fork-modal select option, .fork-modal select optgroup, select.fork-stage-select option, select.fork-stage-select optgroup { background-color: var(--dsw-alias-bg-layer-1, var(--fork-surface)); color: var(--fork-ink); }
.fork-modal select optgroup { color: var(--fork-ink-3); }
/* Worldbook-style lamps in 本轮输入 → 素材清单. */
.fork-lamp { display: inline-block; flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--lamp, var(--fork-ink-3)); box-shadow: 0 0 0 2px color-mix(in srgb, var(--lamp, transparent) 22%, transparent); }
/* blue / green / off are the standard lamp tokens; amber is the warning colour. */
.fork-lamp[data-lamp="blue"], [data-reason="blue"], [data-count="blue"] { --lamp: var(--fork-lamp-blue); }
.fork-lamp[data-lamp="green"], [data-reason="green"], [data-count="green"] { --lamp: var(--fork-lamp-green); }
.fork-lamp[data-lamp="amber"], [data-reason="amber"], [data-count="amber"] { --lamp: var(--fork-warn); }
.fork-lamp[data-lamp="violet"], [data-reason="violet"], [data-count="violet"] { --lamp: #9a7cf0; }
.fork-lamp[data-lamp="off"], [data-reason="off"], [data-count="off"] { --lamp: var(--fork-lamp-off); }
.fork-lamp[data-lamp="off"] { background: transparent; box-shadow: inset 0 0 0 1.5px var(--lamp); }
.fork-catalogue-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; padding: 8px 12px; border: 1px solid var(--fork-hairline); border-radius: 10px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.fork-catalogue-legend > span:not(.fork-catalogue-summary) { display: inline-flex; align-items: center; gap: 6px; }
.fork-catalogue-legend b { color: var(--fork-ink); font-weight: 600; }
.fork-catalogue-legend small { color: var(--fork-ink-3); font-size: var(--fork-fs-meta); }
.fork-catalogue-legend .fork-catalogue-summary { flex-basis: 100%; color: var(--fork-ink-3); }
/* 导演收到了什么: the asset list, then the prompt sections, as two quiet sub-headings in one view. */
.fork-director-input-block { display: grid; gap: 8px; margin-top: 14px; }
.fork-director-input-block + .fork-director-input-block { padding-top: 14px; border-top: 1px solid var(--fork-hairline); }
.fork-director-input-heading { display: flex; align-items: center; gap: 6px; margin: 0; color: var(--fork-ink); font: 600 13px/1.4 var(--fork-font-ui); }
.fork-director-input-block .fork-catalogue-summary { margin: 0; }

/* ==== stage overlays: config + mixer ==== */
/* gal-config.js (full-screen CONFIG) and gal-mixer.js (top-bar mixer): styled only through the stage UI
   tokens (--gal-ui-*, see the token block); no per-theme selectors in these rules. */
.fork-gal-stage.is-config :is(.fork-gal-box, .fork-gal-choices, .fork-gal-topbar) { visibility: hidden; pointer-events: none; }
/* Top bar: the current track and the mixer's speaker icon, on the same opaque HUD plates as the place name. */
.fork-gal-track { display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 18em; color: var(--gal-ui-hud-ink); font: 500 12px/1.3 var(--fork-font-ui); letter-spacing: .04em; transition: color .25s; }
.fork-gal-track > span { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.fork-gal-track .fork-icon { flex: none; color: var(--gal-ui-accent); }
.fork-gal-stage .fork-gal-mixer-toggle { position: relative; display: grid; place-items: center; box-sizing: border-box; width: 30px; height: 30px; margin: 0; padding: 0; border: 0; border-radius: 50%; background: none; box-shadow: none; color: var(--gal-ui-hud-ink); cursor: pointer; transition: background .15s, color .15s; }
/* Hover / open / focus and the muted state: the shared top-chrome rules ("the top chrome has no plates"). */
.fork-gal-config-gem { flex: none; display: block; width: var(--gal-ui-gem-width); height: var(--gal-ui-gem-height); clip-path: var(--gal-ui-gem); background: var(--gal-ui-gem-fill); }
/* ---------- BGM player (bgm-player.js) ----------
   One component, two placements. Its rules read only --bgm-*: the stage maps them from the stage theme (--gal-ui-*:
   palette, fonts, gem, frame halo), chat from the host theme (--fork-*; the gem becomes the section accent bar).
   Legibility: --bgm-surface is always opaque (the panel floats over the scene or the transcript, so nothing may show
   through), and --bgm-on-accent is the play glyph on the accent fill (>= 4.5:1), --bgm-play-hover a fill that keeps it. */
.fork-gal-stage .fork-bgm-panel {
  --bgm-surface: var(--gal-ui-surface-2); --bgm-ink: var(--gal-ui-ink); --bgm-ink-2: var(--gal-ui-ink-2); --bgm-title: var(--gal-ui-accent); --bgm-accent: var(--gal-ui-accent);
  --bgm-on-accent: var(--gal-ui-accent-ink); --bgm-play-hover: color-mix(in srgb, var(--gal-ui-accent) 85%, var(--gal-ui-ink));
  --bgm-line: var(--gal-ui-line); --bgm-hover: var(--gal-ui-hover); --bgm-active: var(--gal-ui-active); --bgm-track: var(--gal-ui-track); --bgm-thumb: var(--gal-ui-thumb);
  --bgm-radius: min(var(--gal-ui-radius), 18px); --bgm-font: var(--gal-ui-font); --bgm-title-font: var(--gal-ui-title-font); --bgm-focus: var(--gal-ui-focus); --bgm-ink-off: var(--gal-ui-ink-disabled);
  --bgm-shadow: var(--gal-ui-ornament-halo), var(--gal-ui-shadow), inset 0 0 0 1px var(--gal-ui-line); --bgm-divider: var(--gal-ui-divider-width) var(--gal-ui-divider) var(--gal-ui-line);
  --bgm-gem: var(--gal-ui-gem); --bgm-gem-width: var(--gal-ui-gem-width); --bgm-gem-height: var(--gal-ui-gem-height); --bgm-gem-fill: var(--gal-ui-gem-fill); --bgm-gem-display: var(--gal-ui-gem-display); --bgm-error: var(--gal-ui-widget-warning);
  position: absolute; top: calc(100% + 10px); left: 0; z-index: 3; width: min(340px, calc(100vw - 24px)); max-height: min(440px, 56vh); }
/* Chat: host surfaces may be glass (a frosted skin's bg tokens are ~20% alpha), so every paint comes from the validated
   surface table (popover level, resolved from the host on body): opaque panel, solid row states, an on-accent play glyph
   and an accent hover that keeps it at 4.5:1. */
.fork-bgm.is-chat {
  --bgm-surface: var(--fk-s-popover-bgSolid); --bgm-ink: var(--fk-s-popover-fg); --bgm-ink-2: var(--fk-s-popover-fgMuted); --bgm-ink-off: var(--fk-s-popover-fgDisabled); --bgm-title: var(--fk-s-popover-fg); --bgm-accent: var(--fk-s-popover-accent);
  --bgm-on-accent: var(--fk-s-popover-onAccent); --bgm-play-hover: var(--fk-s-popover-accentHover);
  --bgm-line: var(--fk-s-popover-line); --bgm-hover: var(--fk-s-popover-hover); --bgm-active: var(--fk-s-popover-selected); --bgm-track: var(--fk-s-popover-line); --bgm-thumb: var(--fk-s-popover-selected);
  --bgm-radius: var(--fork-radius-lg); --bgm-font: var(--fork-font-ui); --bgm-title-font: var(--fork-font-ui); --bgm-focus: 2px solid var(--fk-s-popover-accent);
  --bgm-shadow: var(--fk-s-popover-shadow), 0 0 0 1px var(--fk-s-popover-line); --bgm-divider: 1px solid var(--fk-s-popover-line);
  --bgm-gem: inset(0 round 2px); --bgm-gem-width: 3px; --bgm-gem-height: 12px; --bgm-gem-fill: var(--fork-accent); --bgm-error: var(--dsh-tavern-accent-error); }
.fork-bgm-panel.is-chat { position: fixed; z-index: 1000; }
.fork-bgm-panel { box-sizing: border-box; display: flex; flex-direction: column; gap: 10px; padding: 12px 14px; border-radius: var(--bgm-radius); background: var(--bgm-surface); color: var(--bgm-ink);
  box-shadow: var(--bgm-shadow); font: 400 13px/1.4 var(--bgm-font); text-shadow: none; cursor: default; animation: fork-bgm-in .16s ease-out; }
/* Entrance slides only: an opacity fade held at its first frame (a throttled or hidden window) left the panel see-through. */
@keyframes fork-bgm-in { from { transform: translateY(-4px); } }
.fork-bgm-head { display: flex; align-items: center; gap: 9px; min-width: 0; padding: 0 2px 9px; border-bottom: var(--bgm-divider); }
.fork-bgm-gem { flex: none; display: var(--bgm-gem-display, block); width: var(--bgm-gem-width); height: var(--bgm-gem-height); clip-path: var(--bgm-gem); background: var(--bgm-gem-fill); }
.fork-bgm-title { flex: 1; min-width: 0; overflow: hidden; color: var(--bgm-title); font: 600 13.5px/1.3 var(--bgm-title-font); letter-spacing: .08em; white-space: nowrap; text-overflow: ellipsis; }
/* 导演选曲: icon + name + switch; the switch leads the DOM (it owns the label) and sits at the end by order. */
.fork-bgm-follow { display: inline-flex; flex: none; align-items: center; gap: 5px; color: var(--bgm-ink-2); font-size: 12px; cursor: pointer; }
