  transition: background .15s, color .15s; animation: fork-gal-menu-item .3s cubic-bezier(.2, .8, .3, 1) both; animation-delay: 60ms; }
.fork-gal-menu-list > :nth-child(2) { animation-delay: 85ms; }
.fork-gal-menu-list > :nth-child(3) { animation-delay: 110ms; }
.fork-gal-menu-list > :nth-child(4) { animation-delay: 135ms; }
.fork-gal-menu-list > :nth-child(n+5) { animation-delay: 160ms; }
@keyframes fork-gal-menu-item { from { transform: translateY(6px); } }
.fork-gal-menu-item b { font-size: clamp(17px, 1.3vw, 20px); font-weight: 600; line-height: 1.2; letter-spacing: .2em; white-space: nowrap; }
.fork-gal-menu-sub { grid-column: 3; min-width: 0; overflow: hidden; color: var(--gal-ui-ink-2); font: 600 10.5px/1 var(--gal-ui-font); letter-spacing: .34em; white-space: nowrap; text-overflow: clip; }
.fork-gal-menu-note { grid-column: 4; padding: 3px 9px; border-radius: 999px; box-shadow: inset 0 0 0 1px var(--gal-ui-line); color: var(--gal-ui-ink-2); font: 600 11.5px/1.2 var(--gal-ui-font); letter-spacing: .08em; white-space: nowrap; }
.fork-gal-menu-item .fork-gal-menu-gem { transform: translateX(-4px) scale(0); transition: transform .15s; }
.fork-gal-menu-item::after { content: ""; position: absolute; top: 24%; bottom: 24%; left: 0; width: 3px; border-radius: 0 3px 3px 0; background: var(--gal-ui-accent); transform: scaleY(0); pointer-events: none; transition: transform .15s; }
.fork-gal-stage .fork-gal-menu-item.is-active { background: var(--gal-ui-active); color: var(--gal-ui-accent); }
.fork-gal-menu-item.is-active .fork-gal-menu-gem { transform: none; }
.fork-gal-menu-item.is-active::after { transform: none; }
.fork-gal-menu-item.is-active .fork-gal-menu-note { color: var(--gal-ui-accent); box-shadow: inset 0 0 0 1px var(--gal-ui-muted); }
.fork-gal-stage .fork-gal-menu-item:active { background: var(--gal-ui-hover); }
.fork-gal-stage .fork-gal-menu-item:focus { outline: none; }
.fork-gal-stage .fork-gal-menu-item:focus-visible { outline: var(--gal-ui-focus); outline-offset: -2px; }
.fork-gal-menu-sep { height: 0; margin: 7px 12px; border-top: var(--gal-ui-divider-width) var(--gal-ui-divider) var(--gal-ui-line); }
@media (max-width: 640px) { .fork-gal-menu-sub { display: none; } .fork-gal-menu-frame::before, .fork-gal-menu-frame::after { display: none; } }
@media (prefers-reduced-motion: reduce) and (update: none) { .fork-gal-menu, .fork-gal-menu-panel, .fork-gal-menu-item, .fork-gal-menu-ornament::before, .fork-gal-menu-ornament::after, .fork-gal-menu-frame::before, .fork-gal-menu-frame::after { animation: none; } }
/* one low-frequency regeneration dialog, using the same menu surface. */
.fork-gal-menu-panel[hidden] { display: none; }
.fork-gal-stage .fork-gal-menu-item[aria-disabled="true"] { color: var(--gal-ui-ink-disabled); cursor: not-allowed; }
.fork-gal-stage .fork-gal-menu-item[aria-disabled="true"] .fork-gal-menu-sub { color: var(--gal-ui-ink-disabled); }
/* one surface, nothing framed inside it. Title + (?) → a flat segmented target
   (the shared stage segmented skin, .fork-gal-config-seg) → the guidance as a compact filled field (no
   underline on text inputs; two lines tall, growing with its text; the caret and an accent ring when focused) → a
   quiet 取消 beside the one solid 确定 (R16). */
.fork-gal-regenerate { width: min(92vw, 560px); overflow: auto; gap: 0; color: var(--gal-ui-ink); font-family: var(--gal-ui-font); }
.fork-gal-regenerate h2 { display: flex; align-items: center; gap: 4px; margin: 0 0 18px; color: var(--gal-ui-accent); font-family: var(--gal-ui-title-font); font-size: 22px; line-height: 1.2; letter-spacing: .08em; }
.fork-gal-regenerate p { margin: 0; color: var(--gal-ui-ink-2); font-size: 13px; }
/* the target is the stage Segmented, full width;
   the four short names (正文 / MVU / 舞台指导 / 选项) share the spare width and never wrap, down to 375. */
.fork-gal-regenerate .fork-gal-regenerate-targets { display: flex; box-sizing: border-box; width: 100%; }
.fork-gal-stage .fork-gal-regenerate .fork-gal-regenerate-targets button { flex: 1 1 auto; min-width: 0; min-height: 40px; height: auto; padding: 6px 8px; font-size: inherit; letter-spacing: .04em; line-height: 1.25; white-space: nowrap; }
.fork-gal-regenerate-guidance { display: grid; gap: 8px; margin-top: 24px; color: var(--gal-ui-ink-2); font-size: 13px; }
.fork-gal-stage .fork-gal-regenerate textarea { box-sizing: border-box; width: 100%; min-height: calc(2 * 1.6em + 20px); max-height: 40vh; resize: none; margin: 0; padding: 10px 14px; -webkit-appearance: none; appearance: none;
  border: 0; border-radius: calc(var(--gal-ui-radius) * .8 + 3px); background: color-mix(in srgb, var(--gal-ui-ink) 7%, var(--gal-ui-surface-2)); box-shadow: none; outline: none; color: var(--gal-ui-ink); caret-color: var(--gal-ui-accent);
  font: 500 var(--gal-ui-reading-size)/1.6 var(--gal-ui-font); transition: background-color .15s, box-shadow .15s; }
/* the stage skin of the shared inline edit look, never an underline. An empty
   multi-line box keeps a faint fill at rest so the caret has a place; the R23 hover tint and the accent ring while typing. */
.fork-gal-stage .fork-gal-regenerate textarea:hover:not(:disabled):not(:focus) { background: var(--gal-ui-hover); }
.fork-gal-stage .fork-gal-regenerate textarea:focus { background: var(--gal-ui-hover); box-shadow: inset 0 0 0 1px var(--gal-ui-accent); }
.fork-gal-regenerate-actions { display: flex; justify-content: flex-end; align-items: center; gap: 8px; margin-top: 24px; }
/* submitting - the row is the stage wait (one line, the button row's height), not 「执行中…」.
   The wait is its 停止 (StageWaitStop, "stage wait" above): no pill or hover plate, the tap target is the row's height. */
.fork-gal-regenerate-actions.is-waiting { justify-content: center; min-height: 40px; }
.fork-gal-regenerate-actions.is-waiting > .stage-wait { min-height: 40px; padding: 0 16px; }
.fork-gal-stage .fork-gal-regenerate-actions button:not(.stage-wait) { min-width: 5.5em; min-height: 40px; margin: 0; padding: 0 20px; border: 0; border-radius: 999px; background: transparent; box-shadow: none; color: var(--gal-ui-ink-2);
  font: 600 1em/1 var(--gal-ui-font); letter-spacing: .14em; cursor: pointer; transition: background .15s, color .15s; }
.fork-gal-stage .fork-gal-regenerate-actions button:not(.stage-wait):hover:not(:disabled) { background: var(--gal-ui-hover); color: var(--gal-ui-ink); }
.fork-gal-stage .fork-gal-regenerate-actions button[type="submit"] { background: var(--gal-ui-accent); color: var(--gal-ui-accent-ink); }
.fork-gal-stage .fork-gal-regenerate-actions button[type="submit"]:hover:not(:disabled) { background: color-mix(in srgb, var(--gal-ui-accent) 84%, var(--gal-ui-accent-ink)); color: var(--gal-ui-accent-ink); }
.fork-gal-stage .fork-gal-regenerate-actions button[type="submit"]:disabled { background: var(--gal-ui-hover); }
.fork-gal-regenerate-actions button:focus-visible { outline: var(--gal-ui-focus); outline-offset: 2px; }
.fork-gal-regenerate :disabled { color: var(--gal-ui-ink-disabled); cursor: not-allowed; }
@media (max-width: 640px) { .fork-gal-stage .fork-gal-regenerate-actions button { min-height: 44px; } }
/* 自动 / 跳过 rows (menuitemcheckbox) where the screen has no such control: on = accent. */
.fork-gal-stage .fork-gal-menu-item[aria-checked="true"] { color: var(--gal-ui-accent); }
/* ==== end stage system menu ==== */

/* ==== stage top bar reveal ==== */
/* the top bar is the stage entries' only home
   and hides while reading, in every skin (data-hud on the stage, gal-stage.js useGalHudReveal): shown = a mouse near the
   top / focus inside / an entry's popover; flash = the place / track label line only, for a few seconds after a change; always =
   the player's CONFIG 顶栏按钮 or the skin's hud.reveal. What stays: the menu control (folded skins), the history line, and an
   entry with a badge (its own button and dot). The open menu shows the bar over its dim (stage system menu above). Hidden by a
   full clip, never faded (ui-surfaces.md: no translucent text surfaces) and never removed: Tab still reaches the buttons and the
   focus reveals the bar; clicks fall through to the page. The 2 s linger keeps it from flickering. */
.fork-stage-entry { display: contents; }
.fork-gal-stage:not([data-hud]):not(.is-menu) .fork-gal-topbar :is(.fork-gal-hud-line, .fork-stage-entry:not([data-attention]) > *, .fork-gal-quit),
.fork-gal-stage[data-hud="flash"]:not(.is-menu) .fork-gal-topbar :is(.fork-stage-entry:not([data-attention]) > *, .fork-gal-quit) { clip-path: inset(50%); pointer-events: none; }
.fork-gal-stage[data-hud="flash"]:not(.is-menu) .fork-gal-topbar .fork-gal-hud-line .fork-stage-entry > * { clip-path: none; pointer-events: auto; }
/* ==== end stage top bar reveal ==== */
/* Character editor: 配音语言 beside the voice binding */
.fork-voice-lang-pick { display: inline-flex; align-items: center; gap: 6px; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); }
.fork-bubble-settings .fork-voice-lang-pick select { height: 28px; }
/* Voice library: Azure voice editor (fork-voice-azure.js) */
.fork-azure-editor { display: grid; gap: 8px; padding-top: 8px; border-top: 1px dashed var(--fork-hairline); }
.fork-azure-slider { display: grid; grid-template-columns: 3.4em minmax(0, 1fr) 3.6em; align-items: center; gap: 10px; color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.fork-azure-slider input[type="range"] { width: 100%; accent-color: var(--fork-accent); }
.fork-azure-slider b { color: var(--fork-ink); font: 600 12px/1 var(--fork-font-ui); text-align: right; font-variant-numeric: tabular-nums; }
.fork-azure-preview { display: flex; align-items: center; gap: 8px; min-width: 0; }
.fork-bubble-settings .fork-azure-preview input { flex: 1 1 auto; box-sizing: border-box; min-width: 0; height: 28px; padding: 0 8px; border: 1px solid var(--fork-hairline); border-radius: 7px; background: var(--dsw-specific-input-major, transparent); color: var(--fork-ink); font: 12.5px/1.4 var(--fork-font-ui); }
.fork-azure-preview .dsh-tavern-btn { display: inline-flex; align-items: center; gap: 4px; }

/* ---------- Floating panels (FloatingPanel in settings-ui.js) ----------
   Rendered into <body> with fixed viewport coordinates from the trigger: above modals and their nav,
   clamped to the viewport / the modal content area, never clipped by a scrolling parent. */
.fork-popover { position: fixed; right: auto; bottom: auto; z-index: 2200; box-sizing: border-box; max-width: min(440px, calc(100vw - 16px)); overflow: auto; overscroll-behavior: contain; color: var(--fork-ink); font: 13px/1.5 var(--fork-font-ui); text-align: left; }
.fork-popover:not([data-placed]) { visibility: hidden; }
body[data-ds-dark-theme] .fork-popover { color-scheme: dark; }
.fork-popover.fork-voice-menu { top: auto; width: max-content; min-width: min(260px, calc(100vw - 16px)); transform-origin: top left; }
.fork-popover.fork-voice-menu[data-placed="up"] { transform-origin: bottom left; animation-name: fork-voice-menu-in-up; }
.fork-popover.fork-voice-menu .fork-voice-menu-list { max-height: min(360px, 50vh); }
.fork-popover.fork-help-tip-body { z-index: 2210; max-width: min(300px, calc(100vw - 16px)); overflow: visible; pointer-events: none; animation: fork-voice-menu-in .12s ease-out; }

/* 高级 → 对白提示词 / 差分 */
.fork-set-state { display: inline-flex; align-items: center; height: 22px; padding: 0 9px; border-radius: 999px; background: var(--fork-hover); color: var(--fork-ink-2); font: 500 11.5px/1 var(--fork-font-ui); }
.fork-set-state.is-custom { background: var(--fork-accent-soft); color: var(--fork-accent); }
.fork-set-warn { display: inline-flex; align-items: center; color: #b8761a; font: 500 11.5px/1.3 var(--fork-font-ui); white-space: nowrap; }
.fork-emotion-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; min-width: 0; }
/* Builtin and card emotions are the same filled pill (see .ap-chip: surface-table chip ink, 4.5:1); only ＋ is outlined. */
.fork-emotion-chip { display: inline-flex; align-items: center; height: 22px; box-sizing: border-box; padding: 0 8px; border: 1px solid color-mix(in srgb, var(--mood-color, var(--fork-ink-3)) 45%, var(--fk-current-bgSolid, Canvas)); border-radius: 999px; background: color-mix(in srgb, var(--mood-color, var(--fork-ink-3)) 14%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--mood-color, var(--fork-ink-2)) var(--fk-current-chipInk, 62%), var(--fk-current-fg, var(--fork-ink))); font: 500 11.5px/1 var(--fork-font-ui); white-space: nowrap; }
.fork-bubble-settings .fork-emotion-chip.is-custom { margin: 0; cursor: pointer; }
.fork-bubble-settings .fork-emotion-chip.is-custom:hover { border-color: var(--mood-color, var(--fork-accent)); }
.fork-bubble-settings .fork-emotion-add { display: inline-grid; place-items: center; width: 22px; height: 22px; margin: 0; padding: 0; border: 1px dashed var(--fork-hairline); border-radius: 50%; background: transparent; color: var(--fork-ink-3); cursor: pointer; }
.fork-bubble-settings .fork-emotion-add:hover:not(:disabled) { border-color: var(--fork-accent); color: var(--fork-accent); }
.fork-bubble-settings .fork-emotion-add:disabled { filter: var(--fk-current-dim, grayscale(1)); cursor: default; }
.fork-bubble-settings :is(.fork-emotion-chip.is-custom, .fork-emotion-add):focus-visible { outline: 2px solid var(--mood-color, var(--fork-accent)); outline-offset: 1px; }
.fork-emotion-modal { width: min(440px, 94vw); height: auto; min-height: 0; }
.fork-emotion-modal .fork-modal-body { overflow: visible; }
.fork-emotion-form { display: grid; gap: 4px; --fork-set-label-w: 7.4em; }
.fork-emotion-form .fork-bubble-tools { margin-top: 8px; }
/* 「对白提示词」 modal: a flat list of sections, each one heading row (disclosure + label, 「?」 right after the label,
   tags, right-aligned actions) plus its content, separated by hairlines. No card frames; (inline-field
   sweep): no boxed fields either — 插入位置 is label + value rows, the text areas sit on an underline; only the full-text
   preview keeps a border. The modal itself is opaque. */
.fork-prompt-editor { display: grid; grid-template-columns: minmax(0, 1fr); min-width: 0; color: var(--fork-ink); }
.fork-prompt-part { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; min-width: 0; padding: 12px 0; }
.fork-prompt-editor > .fork-prompt-part:first-child { padding-top: 0; }
.fork-prompt-part + .fork-prompt-part { border-top: 1px solid var(--fork-hairline); }
.fork-prompt-editor > section.fork-prompt-part:last-of-type { border-bottom: 1px solid var(--fork-hairline); }
.fork-prompt-head { display: flex; flex-wrap: nowrap; align-items: center; gap: 6px; min-width: 0; min-height: 28px; }
.fork-prompt-part.is-foldable > .fork-prompt-head { cursor: pointer; }
.fork-prompt-title, .fork-prompt-toggle { flex: none; color: var(--fork-ink); font: 600 13px/1.4 var(--fork-font-ui); white-space: nowrap; }
.fork-prompt-toggle { display: inline-flex; align-items: center; gap: 7px; margin: 0 0 0 -3px; padding: 2px 0 2px 3px; border: 0; border-radius: 6px; background: transparent; cursor: pointer; }
.fork-prompt-toggle > b { font-weight: inherit; }
/* ▶ / ▼ disclosure (rotated triangle), like the native <details> marker it replaces. */
.fork-prompt-toggle::before { content: ""; flex: none; width: 0; height: 0; border-top: 4px solid transparent; border-bottom: 4px solid transparent; border-left: 6px solid var(--fork-ink-3); transition: transform .15s; }
.fork-prompt-toggle[aria-expanded="true"]::before { transform: rotate(90deg); }
.fork-prompt-head:hover .fork-prompt-toggle::before { border-left-color: var(--fork-ink); }
.fork-prompt-toggle:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.fork-prompt-head > .fork-help-tip { flex: none; }
.fork-prompt-tag { flex: 0 1 auto; min-width: 0; overflow: hidden; margin-left: 4px; padding: 0 8px; border-radius: 999px; corner-shape: round; background: var(--fork-accent-soft); color: var(--fork-ink-2); font: 500 11px/1.7 var(--fork-font-ui); white-space: nowrap; text-overflow: ellipsis; }
.fork-prompt-tag + .fork-prompt-tag { margin-left: 0; }
.fork-prompt-inactive { flex: none; background: var(--fork-hover); }
.fork-prompt-manual { flex: none; background: color-mix(in srgb, #e0704f 16%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink); }
.fork-prompt-head-actions { display: inline-flex; flex: none; align-items: center; gap: 4px; margin-left: auto; }
.fork-prompt-body { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; min-width: 0; }
.fork-prompt-body[hidden] { display: none; }
.fork-prompt-block-text { max-height: 50vh; margin: 0; padding: 0 0 0 16px; overflow: auto; color: var(--fork-ink-2); white-space: pre-wrap; overflow-wrap: anywhere; font: 12px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
.fork-prompt-custom-notice { display: flex; align-items: center; gap: 6px; margin-bottom: 12px; padding: 8px 10px 8px 12px; border-radius: 10px; background: var(--fork-accent-soft); color: var(--fork-ink); }
.fork-prompt-custom-notice > b { font-weight: 600; }
.fork-prompt-custom-notice > .fork-bubble-link { margin-left: auto; }
.fork-prompt-placement-fields > .fork-inline-field { --fork-inline-label-w: 5.5em; }
.fork-prompt-existing-depth .fork-inline-value { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.fork-bubble-settings :is(.fork-prompt-extra-input, .fork-prompt-template) { box-sizing: border-box; width: 100%; padding: 6px 8px; color: var(--fork-ink); resize: vertical; }
.fork-prompt-extra-input { font: 13px/1.6 var(--fork-font-ui); }
.fork-prompt-editor > .fork-bubble-note { margin: 10px 0 0; }
.fork-prompt-editor > .fork-prompt-full-toggle { justify-self: start; margin-top: 8px; }
.fork-prompt-editor > .fork-prompt-preview { margin-top: 6px; }
.fork-prompt-segment { display: block; padding: 8px 10px; background: color-mix(in srgb, #be9864 12%, var(--fork-surface, Canvas)); color: var(--fork-ink); }
.fork-prompt-segment[data-block="voice"], .fork-prompt-segment[data-block="characters"] { background: color-mix(in srgb, #549b8a 12%, var(--fork-surface, Canvas)); }
.fork-prompt-segment[data-block="emotions"], .fork-prompt-segment[data-block="extra"] { background: color-mix(in srgb, #c87f81 12%, var(--fork-surface, Canvas)); }
@media (max-width: 560px) { .fork-prompt-block-text { padding-left: 0; } }
.fork-bubble-settings .fork-prompt-template { min-height: 26vh; font: 12px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
.fork-prompt-preview { box-sizing: border-box; max-height: 60vh; margin: 0; padding: 0; overflow: auto; border: 1px solid var(--fork-hairline); border-radius: 10px; background: var(--fork-surface, Canvas); color: var(--fork-ink); white-space: pre-wrap; overflow-wrap: anywhere; font: 12px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
.fork-prompt-modal .fork-modal-body > .fork-bubble-tools { margin-top: 12px; }
/* Custom mood slots: a small dashed ring marks them (the colour stays neutral). */
.fork-bubble-mood-slot.is-custom .fork-bubble-mood-thumb, .fork-static-slot.is-custom .fork-static-pick { border-style: dashed; }
.fork-bubble-mood-slot.is-custom .fork-bubble-mood-label::after, .fork-voice-slot.is-custom .fork-voice-slot-label::after, .fork-static-slot.is-custom > span::after { content: "*"; margin-left: 1px; color: var(--fork-ink-3); }
.fork-character-editor .fork-bubble-moods { grid-template-columns: repeat(auto-fill, minmax(56px, 1fr)); }
.fork-character-note { display: flex; align-items: center; gap: 6px; min-width: 0; }
.fork-character-note .fork-bubble-note-input { flex: 1 1 auto; min-width: 0; }

/* 素材库 / 角色 (bubble-modals.js): the 「素材库」 icon button beside a row, empty states, 头像 */
:is(.fork-bubble-settings, .fork-modal-nav) .fork-set-open.is-icon { justify-content: center; width: 26px; padding: 0; }
.fork-modal-empty { display: grid; justify-items: center; gap: 10px; padding: 48px 16px; color: var(--fork-ink-2); text-align: center; }
.fork-modal-empty > strong { font-size: 13.5px; font-weight: 600; }
.fork-modal-empty-icon { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 16px; background-color: Canvas; background-image: linear-gradient(var(--fork-accent-soft), var(--fork-accent-soft)), linear-gradient(var(--fork-surface), var(--fork-surface)); color: var(--fork-accent); }
.fork-modal-empty .dsh-tavern-btn { display: inline-flex; align-items: center; gap: 5px; }
.fork-avatar-assets { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 8px; }
.fork-bubble-settings .fork-avatar-asset { display: grid; justify-items: center; gap: 4px; min-width: 0; margin: 0; padding: 10px 6px 8px; border: 1px solid var(--fork-hairline); border-radius: 12px; background-color: Canvas; background-image: linear-gradient(var(--fork-surface), var(--fork-surface)); color: var(--fork-ink); cursor: pointer; }
.fork-bubble-settings .fork-avatar-asset:hover { border-color: color-mix(in srgb, var(--fork-accent) 45%, var(--fork-hairline)); background-color: Canvas; background-image: linear-gradient(var(--fork-accent-soft), var(--fork-accent-soft)), linear-gradient(var(--fork-surface), var(--fork-surface)); }
.fork-bubble-settings .fork-avatar-asset:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.fork-avatar-asset-face { position: relative; display: grid; place-items: center; width: 52px; height: 52px; }
.fork-avatar-asset .fork-bubble-avatar { width: 52px; height: 52px; border-radius: 50%; font-size: 17px; box-shadow: 0 0 0 2px color-mix(in srgb, var(--bubble-color) 50%, transparent); }
.fork-avatar-asset > b { max-width: 100%; overflow: hidden; font-size: var(--fork-fs-body); font-weight: 600; white-space: nowrap; text-overflow: ellipsis; }
.fork-avatar-asset-count { color: var(--fork-ink-2); font: 500 11px/1.3 var(--fork-font-ui); font-variant-numeric: tabular-nums; }
