.fork-widget-slot[data-slot="corner-left"] { grid-column: 1; grid-row: 2; align-self: end; align-items: flex-start; max-height: 100%; }
.fork-widget-slot[data-slot="corner-right"] { grid-column: 3; grid-row: 2; align-self: end; align-items: flex-end; max-height: 100%; }
.fork-widget-slot[data-slot="center-card"] { grid-column: 2; grid-row: 2; align-self: center; max-height: 100%; }
.fork-widget { display: flex; flex-direction: column; position: relative; pointer-events: auto; min-width: 0; width: 100%; max-width: 280px; max-height: min(40vh, 100%); box-sizing: border-box; padding: 16px; overflow: hidden; border: 1px solid var(--gal-ui-line); border-radius: var(--gal-ui-radius); background: var(--gal-ui-surface); box-shadow: var(--gal-ui-ornament-halo), var(--gal-ui-shadow); color: var(--gal-ui-ink); animation: fork-widget-in .2s ease-out; }
