.fork-widget-heading span { display: block; font-size: .8em; color: var(--gal-ui-accent); }
.fork-widget button, .fork-widget-restore, .fork-widget-reader button { appearance: none; border: 0; padding: 6px 10px; margin: 0; border-radius: var(--gal-ui-radius); background: transparent; color: var(--gal-ui-ink); font: inherit; cursor: pointer; }
