.fork-source-switch .dsh-tavern-settings-track::after { top: 3px; left: 3px; width: 12px; height: 12px; }
.fork-source-switch .dsh-tavern-settings-switch input:checked + .dsh-tavern-settings-track::after { transform: translateX(12px); }
.fork-source-cell-count { min-width: 2ch; color: var(--fork-ink-3); font: 500 10.5px/1 var(--fork-font-ui); font-variant-numeric: tabular-nums; text-align: left; }
.fork-source-grid tr.is-card > th[scope="row"] { color: var(--fork-accent); }
.fork-source-grid tr.is-missing > th[scope="row"] { color: var(--fork-ink-3); }
.fork-source-grid th[scope="row"] small { margin-left: 6px; color: #b8761a; font-size: 10.5px; font-weight: 500; }
.fork-source-grid tr.fork-source-total > * { border-top: 1px solid var(--fork-hairline); color: var(--fork-ink-2); font-variant-numeric: tabular-nums; }
.fork-source-grid tr.fork-source-total > td { text-align: center !important; }
/* 本轮清单: items this card does not use. */
.fork-catalogue-item.is-hidden .fork-catalogue-name { color: var(--fork-ink-3); }
.fork-catalogue-reason[data-reason="hidden"] { background: var(--fork-hover); color: var(--fork-ink-3); }
/* ==== end asset catalogue ==== */
/* Lamp rows (after the older catalogue rules so these win). */
.fork-catalogue-count.is-lamp { display: inline-flex; align-items: center; gap: 5px; background: color-mix(in srgb, var(--lamp) 12%, var(--fork-surface)); color: var(--fork-ink-2); }
.fork-catalogue-lamp { display: inline-flex; flex: none; width: 12px; justify-content: center; }
.fork-catalogue-keywords { display: inline-flex; flex-wrap: wrap; gap: 4px; min-width: 0; }
.fork-catalogue-keyword { padding: 0 6px; border-radius: 4px; background: color-mix(in srgb, #3fae6a 14%, var(--fork-surface)); color: color-mix(in srgb, #3fae6a 70%, var(--fork-ink)); font: 500 11px/1.6 var(--fork-font-ui); white-space: nowrap; }
.fork-catalogue-reason[data-reason] { background: color-mix(in srgb, var(--lamp, var(--fork-ink-3)) 14%, var(--fork-surface)); color: color-mix(in srgb, var(--lamp, var(--fork-ink-3)) 75%, var(--fork-ink)); }
.fork-catalogue-module > summary .fork-catalogue-tokens { margin-left: auto; color: var(--fork-ink-3); font: 400 11.5px/1.4 var(--fork-font-ui); font-style: normal; font-variant-numeric: tabular-nums; white-space: nowrap; }
.fork-catalogue-raw { display: grid; gap: 4px; margin-top: 8px; }
.fork-catalogue-raw-section { border: 1px dashed var(--fork-hairline); border-radius: 8px; }
.fork-catalogue-raw-section > summary { display: flex; align-items: center; gap: 8px; padding: 5px 10px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); cursor: pointer; list-style: none; }
.fork-catalogue-raw-section > summary::-webkit-details-marker { display: none; }
.fork-catalogue-raw-section > summary::before { content: ""; flex: none; width: 5px; height: 5px; border-right: 1.5px solid var(--fork-ink-3); border-bottom: 1.5px solid var(--fork-ink-3); transform: rotate(-45deg); transition: transform .15s; }
.fork-catalogue-raw-section[open] > summary::before { transform: rotate(45deg); }
.fork-catalogue-raw-section > summary em { margin-left: auto; color: var(--fork-ink-3); font-style: normal; font-variant-numeric: tabular-nums; }
.fork-catalogue-raw-section pre { max-height: 40vh; margin: 0; padding: 8px 12px 10px; overflow: auto; border-top: 1px dashed var(--fork-hairline); white-space: pre-wrap; overflow-wrap: anywhere; font: 11.5px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
/* Asset-library catalogue (dsh-asset-library client) renders an <img> inside the thumb instead of a background image. */
.fork-bg-thumb > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; pointer-events: none; }
.fork-bg-thumb > span { position: relative; }

/* asset-pack workbench, shared by header and card settings. */
.fork-catalogue-item > code { min-width: 0; overflow-wrap: anywhere; font-size: var(--fork-fs-meta); }
.fork-settings-simple .ap-actions { gap: 8px; }

/* Panel language: one container, hairlines, accent-marked sections. */
.ap-ui {
  --ap-border: var(--fork-hairline, color-mix(in srgb, currentColor 14%, transparent));
  --ap-border-strong: var(--dsw-alias-border-l3, color-mix(in srgb, currentColor 22%, transparent));
  --ap-field: var(--dsw-alias-bg-layer-1, Canvas);
  --ap-ink-3: var(--fork-ink-3, GrayText);
  --ap-error: var(--dsw-alias-state-error-primary, #d93025);
  --ap-mono: ui-monospace, "Cascadia Code", Consolas, monospace;
  color: var(--fork-ink, CanvasText);
  background: linear-gradient(var(--fork-surface, transparent), var(--fork-surface, transparent)), Canvas;
  font: var(--fork-ui-size, 13px)/1.6 var(--fork-font-ui, sans-serif);
  padding: 22px 24px 0;
  box-sizing: border-box;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  min-width: 0;
  min-height: 100%;
  /* The host tab host is a fixed-height flex column; an explicit min-height drops the flex item's automatic minimum,
     so a shrinkable panel was squeezed to one viewport and its base paint stopped there while the rest of the page
     overflowed onto the host frame (owner screenshot, 2026-10). The panel is one surface for its full length. */
  flex-shrink: 0;
  container-type: inline-size;
}
.ap-ui *, .ap-ui *::before, .ap-ui *::after { box-sizing: border-box; }
.ap-ui h1, .ap-ui h2 { margin: 0; font-size: var(--fork-fs-title); font-weight: 600; line-height: 1.4; letter-spacing: .01em; }
.ap-ui h3 { margin: 0 0 8px; font-size: var(--fork-fs-body); font-weight: 600; }
.ap-ui p { margin: 6px 0 12px; }
.ap-ui small, .ap-impact, .ap-empty { color: var(--fork-ink-2, GrayText); }
.ap-empty { margin: 8px 0; color: var(--ap-ink-3); }
.ap-ui code { display: block; color: var(--ap-ink-3); font: 11.5px/1.5 var(--ap-mono); overflow-wrap: anywhere; }
.ap-ui pre { max-height: 320px; margin: 8px 0; padding: 10px 12px; overflow: auto; border-radius: 8px; background: var(--fork-hover); white-space: pre-wrap; overflow-wrap: anywhere; font: 11.5px/1.6 var(--ap-mono); }
.ap-ui :focus-visible { outline: 2px solid var(--fork-accent, Highlight); outline-offset: 2px; }

/* Header and mode switch. */
.ap-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 14px; }
.ap-head p { margin: 2px 0 0; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }
/* a workbench tab (舞台设置 / 舞台素材) is its own scroller. The host's tab body is a
   fixed-height flex column with overflow: hidden and scrolls nothing itself, so the page fills this box (.ap-ui min-height:
   100%, flex-shrink: 0) and anything taller scrolls here, by wheel, touch and keyboard. */
.fork-tab-scroll { display: flex; flex-direction: column; flex: 1 1 auto; box-sizing: border-box; width: 100%; height: 100%; min-height: 0; overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain; }
.ap-library > .ap-head { align-items: center; }
.ap-segmented { display: inline-flex; flex: none; padding: 2px; border-radius: 9px; background: var(--fork-hover); }
.ap-ui .ap-segmented button { min-width: 48px; min-height: 0; height: 26px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-ui .ap-segmented button:hover:not(:disabled) { background: transparent; color: var(--fork-ink); }
.ap-ui .ap-segmented button[aria-pressed=true] { background: Canvas; background: linear-gradient(var(--fork-surface), var(--fork-surface)), Canvas; color: var(--fork-ink); font-weight: 600; box-shadow: 0 1px 2px #0000001f, 0 0 0 .5px var(--ap-border); }
.ap-tabs { display: flex; flex-wrap: wrap; gap: 4px 22px; border-bottom: 1px solid var(--ap-border); }
.ap-ui .ap-tabs button { position: relative; min-height: 0; height: 36px; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.ap-ui .ap-tabs button:hover:not(:disabled) { background: transparent; color: var(--fork-ink); }
.ap-ui .ap-tabs button[aria-pressed=true] { background: transparent; color: var(--fork-ink); font-weight: 600; }
.ap-ui .ap-tabs button[aria-pressed=true]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; border-radius: 2px; background: var(--fork-accent); }
.ap-ui .ap-tabs button[data-count]::before { content: attr(data-count); order: 2; margin-left: 5px; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); font-weight: 400; font-variant-numeric: tabular-nums; }
.ap-ui .ap-tabs button { display: inline-flex; align-items: center; }
.ap-ui .ap-tabs button[data-count="0"] { color: var(--ap-ink-3); }

/* Sections: an accent mark like the stage's place label, hairline above. */
.ap-section, .ap-ui fieldset { min-width: 0; margin: 0; padding: 18px 0 6px; border: 0; border-top: 1px solid var(--ap-border); }
.ap-section:first-child, .ap-head + * > .ap-section:first-child { border-top: 0; }
.ap-section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.ap-section-head h3, .ap-ui legend { display: flex; align-items: center; gap: 8px; margin: 0; padding: 0; font-size: var(--fork-fs-body); font-weight: 600; letter-spacing: .04em; }
.ap-ui legend { float: left; width: 100%; margin-bottom: 8px; }
.ap-ui legend + * { clear: both; }
.ap-section-meta { color: var(--ap-ink-3); font-size: var(--fork-fs-meta); font-weight: 400; letter-spacing: 0; font-variant-numeric: tabular-nums; }
/* 舞台设置 heads are the CONFIG captions — a small letter-spaced caption on its own
   hairline, groups set apart by space; no accent bar and no hairline above a group. */
.ap-stage .ap-section { padding: 26px 0 4px; border-top: 0; }
.ap-stage .ap-section-head { min-height: 34px; margin-bottom: 4px; padding-bottom: 6px; border-bottom: 1px solid var(--ap-border); }
.ap-stage .ap-section-head h3, .ap-stage legend { gap: 8px; font-size: var(--fork-fs-body); letter-spacing: .24em; }
.ap-stage .ap-section-body > .ap-opening-picker:not(.is-compact) { max-width: 420px; }
.ap-loading { display: flex; align-items: center; gap: 8px; margin: 14px 0; color: var(--ap-ink-3); }

/* Controls. */
.ap-ui button, .ap-file-button {
  display: inline-flex; align-items: center; justify-content: center; gap: 4px; min-height: 30px; padding: 0 14px;
  border: .5px solid var(--ap-border-strong); border-radius: 15px; color: inherit; background: transparent; font: inherit; font-size: var(--fork-fs-body); white-space: nowrap; cursor: pointer;
  transition: background .15s, color .15s;
}
.ap-ui button:disabled { filter: var(--fk-current-dim, grayscale(1)); cursor: not-allowed; }
.ap-ui button.ap-primary { padding: 0 18px; border-color: transparent; background: var(--dsw-alias-button-primary-fill, CanvasText); color: var(--dsw-alias-label-primary-foreground, Canvas); font-weight: 500; }
.ap-ui button:hover:not(:disabled), .ap-file-button:hover { background: var(--fork-hover); }
.ap-ui button.ap-primary:hover:not(:disabled) { background: var(--dsw-alias-button-primary-hover, var(--dsw-alias-button-primary-fill, CanvasText)); }
.ap-ui button.ap-link { min-height: 26px; padding: 0 8px; border: 0; border-radius: 6px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-ui button.ap-link:hover:not(:disabled) { color: var(--fork-ink); }
.ap-ui button.ap-link.is-danger:hover:not(:disabled) { color: var(--ap-error); }
.ap-ui button.ap-back { min-height: 26px; margin: 0 0 4px -8px; padding: 0 8px; border: 0; border-radius: 6px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
/* the one sub-page header (SubpageHead) — ‹ · title · 「?」 … tools on one 40px
   row, the same on a desktop and a phone. The ‹ hangs in the gutter so the title keeps the content's left edge less the
   glyph; no breadcrumb line, no boxes. A pack opened from a 基础设置 「›」 starts its head with the same ‹. */
.ap-subhead { display: flex; align-items: center; gap: 4px; min-height: 40px; margin: 0 0 12px -8px; }
.ap-ui button.ap-icon-button.ap-subhead-back { flex: none; width: 32px; height: 32px; border-radius: 8px; background: none; color: var(--fork-ink-2); }
.ap-ui button.ap-icon-button.ap-subhead-back:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui button.ap-icon-button.ap-subhead-back:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.ap-subhead-back .ap-glyph { width: 18px; height: 18px; }
.ap-ui .ap-subhead > .ap-subhead-title { display: flex; align-items: center; gap: 4px; min-width: 0; margin: 0; color: var(--fork-ink); font-size: var(--fork-fs-title); font-weight: 600; line-height: 1.35; letter-spacing: .01em; outline: none; }
.ap-subhead-text { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-subhead-tools { display: inline-flex; align-items: center; gap: 6px; margin-left: auto; }
.ap-pack-head.has-back { padding-left: 10px; gap: 4px; }
@media (max-width: 720px) { .ap-ui button.ap-icon-button.ap-subhead-back { width: 36px; height: 36px; } .ap-subhead { margin-left: -10px; } }
/* no boxed inputs
   and no underlines — a text value in the panel reads as plain text; hover / focus / ✎ come from the one 「fork inline edit」
   block at the end of this file. Only the search boxes below keep a box. */
.ap-ui input:not([type=checkbox]):not([type=file]):not([type=color]), .ap-ui select, .ap-ui textarea {
  width: 100%; min-width: 0; max-width: 100%; min-height: 32px; padding: 5px 6px;
  border: 0; border-radius: 6px; background: transparent; box-shadow: none;
  font: inherit; font-size: var(--fork-fs-body); color: inherit; transition: background-color .15s, box-shadow .15s;
}
.ap-ui select:focus { outline: none; box-shadow: none; }
/* Search / filter boxes stay boxes (the pill-shaped .ap-search restyles them further below). */
.ap-ui :is(input[type=search], .ap-voice-search input, input.ap-voice-filter):not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { padding: 5px 10px; border: .5px solid var(--ap-border-strong); border-radius: 8px; background: var(--ap-field); }
.ap-ui :is(input[type=search], .ap-voice-search input, input.ap-voice-filter):not([data-ap-a]):not([data-ap-b]):not([data-ap-c]):focus { border-color: var(--fork-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--fork-accent) 16%, transparent); }
.ap-ui input::placeholder, .ap-ui textarea::placeholder { color: var(--ap-ink-3); }
/* a multi-line text (详情, prompts, director notes) is no box: text on the
   page (the shared inline edit look). */
.ap-ui textarea { resize: vertical; line-height: 1.55; padding: 6px 8px; }
.ap-ui textarea[spellcheck=false] { font: 12px/1.55 var(--ap-mono); }
.ap-ui input[type=color] { width: 44px; height: 26px; padding: 0; border: .5px solid var(--ap-border-strong); border-radius: 6px; background: none; cursor: pointer; }
.ap-ui input[type=color]::-webkit-color-swatch-wrapper { padding: 3px; }
.ap-ui input[type=color]::-webkit-color-swatch { border: 0; border-radius: 4px; }
/* Toggles are switches (host Switch geometry); acknowledgements in risk dialogs stay checkboxes. */
.ap-ui input[type=checkbox] { appearance: none; flex: none; position: relative; width: 36px; height: 20px; margin: 0; border-radius: 10px; background: var(--ap-border-strong); cursor: pointer; transition: background .15s; }
.ap-ui input[type=checkbox]::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px #0003; transition: transform .15s; }
.ap-ui input[type=checkbox]:checked { background: var(--fork-accent); }
.ap-ui input[type=checkbox]:checked::after { transform: translateX(16px); background: var(--dsw-alias-label-primary-foreground, #fff); }
.ap-ui input[type=checkbox]:disabled { filter: var(--fk-current-dim, grayscale(1)); cursor: default; }
.ap-file-button { position: relative; overflow: hidden; }
.ap-file-button:focus-within { outline: 2px solid var(--fork-accent); outline-offset: 2px; }
.ap-file-button input { position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; }
/* no grey helper text (panel-ui-design.md §一.5) — explanations live only behind this 「?」. */
.ap-help-anchor { position: relative; display: inline-flex; vertical-align: middle; margin-left: 6px; }
/* the inline fallback help layer must escape the title span's opacity stacking context. */
.ap-ui .ap-help-anchor:is(:hover, :focus-within, [data-open]) { z-index: 10011; opacity: 1; }
.ap-ui .ap-help-tip { opacity: 1; }
.ap-help-tip { display: none; position: absolute; z-index: 40; top: calc(100% + 6px); left: 50%; transform: translateX(-50%); width: max-content; max-width: min(260px, 70vw); padding: 7px 10px; border: .5px solid var(--ap-border-strong); border-radius: 8px;
  background: linear-gradient(var(--fork-surface, transparent), var(--fork-surface, transparent)), Canvas; box-shadow: 0 8px 24px #00000029; color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 400; line-height: 1.55; letter-spacing: 0; text-align: left; white-space: normal; pointer-events: none; }
.ap-help-anchor:hover .ap-help-tip, .ap-help:focus-visible + .ap-help-tip, .ap-help-anchor[data-open] .ap-help-tip { display: block; }
/* The shared HelpTip (injected in the client) inside ap panels: beat the generic .ap-ui button box. */
.ap-ui .fork-help-tip { margin-left: 6px; vertical-align: middle; }
.ap-switch-name .fork-help-tip, .ap-switch-name .ap-help-anchor, .ap-section-head h3 .fork-help-tip, .ap-section-head h3 .ap-help-anchor { margin-left: 0; }
/* anchored on the modal's own top layer, not <body> - a body:has anchor
   restyled the whole document on every DOM insertion anywhere (stage text, 弹幕, React commits). */
.ap-layer:has(> .ap-modal-scrim) ~ .fork-popover { z-index: 10011; }

/* Field rows: aligned label column, no boxes. */
.ap-control { display: block; min-width: 0; }
.ap-control:has(> input[type=checkbox]), .ap-control:has(> input[type=color]) { display: flex; align-items: center; min-height: 32px; }
.ap-actions { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 14px; }
.ap-actions > label:first-child:not(.ap-file-button) { margin-right: auto; }
.ap-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 16px 0 6px; }
.ap-create { display: flex; flex: 1; gap: 8px; min-width: min(280px, 100%); margin: 10px 0; }
.ap-toolbar .ap-create { margin: 0; }
.ap-create > input { flex: 1; }
.ap-create > button { flex-shrink: 0; }
.ap-note { margin: 4px 0; color: var(--fork-accent); font-size: var(--fork-fs-meta); }
.ap-alert { margin: 10px 0; padding: 2px 0 2px 10px; border-left: 2px solid var(--ap-error); color: var(--fork-ink-2); font-size: var(--fork-fs-meta); overflow-wrap: anywhere; }
.ap-alert.ap-hint-chip { width: fit-content; max-width: 100%; padding: 6px 10px; border: 1px solid var(--ap-error); border-radius: 12px; color: var(--ap-error); }
.ap-detail-pane > .ap-alert.ap-hint-chip, .ap-figure-main > .ap-alert.ap-hint-chip { position: sticky; top: 0; z-index: 2; background: var(--fk-current-bgSolid, Canvas); }
.ap-ui .ap-alert button { min-height: 24px; margin-left: 10px; padding: 0 8px; border: 0; color: var(--fork-accent); font-size: var(--fork-fs-meta); }

/* Lists: hairline rows. */
.ap-rows, .ap-cast { margin: 0; padding: 0; list-style: none; }
.ap-rows > li, .ap-cast > li { border-bottom: 1px solid var(--ap-border); }
.ap-rows > li:last-child, .ap-cast > li:last-child { border-bottom: 0; }
.ap-ui .ap-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; min-height: 44px; padding: 7px 0; border: 0; border-radius: 0; background: none; text-align: left; white-space: normal; }
.ap-ui button.ap-row { padding: 7px 8px; margin: 0 -8px; width: calc(100% + 16px); border-radius: 8px; }
.ap-ui .ap-row[aria-pressed=true] { background: var(--fork-accent-soft); }
.ap-bound { cursor: pointer; }
.ap-bound.is-missing .ap-row-main > span { color: var(--ap-error); }
.ap-row-main { display: grid; min-width: 0; }
.ap-row-main > span { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.ap-row-main small { color: var(--ap-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-row-main code, .ap-alias { display: inline; font-size: var(--fork-fs-meta); }
.ap-recall { flex: none; display: inline-flex; align-items: center; gap: 5px; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }
.ap-recall::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ap-recall[data-mode=constant] { color: var(--fork-lamp-blue); }
.ap-recall[data-mode=keyword] { color: var(--fork-lamp-green); }

/* Cast: avatar rows, one editor open. */
.ap-ui .ap-cast-row { display: flex; align-items: center; gap: 12px; width: calc(100% + 16px); min-height: 56px; margin: 0 -8px; padding: 8px; border: 0; border-radius: 10px; background: none; text-align: left; white-space: normal; }
.ap-ui .ap-cast-row .ap-row-main { flex: 1; }
.ap-ui .ap-cast-row .ap-row-main > span { font-size: var(--fork-fs-body); font-weight: 500; }
.ap-cast > li.is-open .ap-cast-row { background: var(--fork-accent-soft); }
.ap-chevron { flex: none; width: 7px; height: 7px; margin-right: 6px; border-right: 1.5px solid var(--ap-ink-3); border-bottom: 1.5px solid var(--ap-ink-3); transform: rotate(-45deg); transition: transform .15s; }
.ap-cast-row[aria-expanded=true] .ap-chevron { transform: rotate(45deg); }
.ap-cast-editor { padding: 4px 0 14px 48px; }
.ap-row-actions { display: flex; justify-content: flex-end; margin-top: 4px; }
.ap-avatar, .ap-thumb { position: relative; display: block; flex: none; overflow: hidden; background: linear-gradient(135deg, color-mix(in srgb, var(--fork-accent) 16%, var(--fork-hover)), var(--fork-hover)); }
.ap-avatar { width: 36px; height: 36px; border-radius: 8px; }
.ap-avatar.is-large { width: 100%; height: auto; aspect-ratio: 1; border-radius: 10px; }
.ap-thumb { width: 100%; aspect-ratio: 16 / 9; border-radius: 8px; }
.ap-avatar img, .ap-thumb img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center top; }
.ap-thumb img { object-position: center; }

/* Pack library (panel-ui-design.md §四): one compact hairline row per pack, no thumbnails on first paint. */
/* Phone width: the switch sits above the icon actions so the name keeps the row. */
.ap-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.ap-diff { display: flex; flex-wrap: wrap; gap: 2px 12px; margin: 2px 0; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-glyph { flex: none; }
.ap-ui button.ap-icon-button .ap-glyph { stroke-width: 1.3; }
.ap-ui button.ap-icon-button.is-danger:hover:not(:disabled) { color: var(--ap-error); }
/* Pack detail: icon back · title · ⋯ menu on one line. */
.ap-thumb-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }
.ap-ui .ap-tile { position: relative; display: block; min-height: 0; padding: 0; overflow: hidden; border: 0; border-radius: 8px; background: none; text-align: left; white-space: normal; }
.ap-tile .ap-thumb { border-radius: 8px; }
.ap-tile-name { position: absolute; left: 0; right: 0; bottom: 0; padding: 18px 8px 6px; background: var(--fk-current-mediaScrim, none); color: #fff; font-size: var(--fork-fs-meta); font-weight: 600; line-height: 1.35; text-shadow: 0 1px 2px #0008; }
.ap-tile-flag { position: absolute; top: 6px; left: 6px; padding: 0 6px; border-radius: 4px; background: var(--fk-current-mediaChip, #16141c); color: #fff; font-size: var(--fork-fs-meta); }
.ap-ui button.ap-tile:hover:not(:disabled) { background: none; }
.ap-ui button.ap-tile:hover .ap-thumb img { transform: scale(1.04); }
.ap-tile .ap-thumb img { transition: transform .3s var(--fork-ease, ease); }
.ap-ui .ap-tile[aria-pressed=true] { outline: 2px solid var(--fork-accent); outline-offset: 2px; }
/* Character select (after the old 素材库 立绘 browser): a 3:4 standing sprite, name over a gradient, form summary. */
.ap-figure-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(118px, 1fr)); gap: 12px; }
.ap-ui .ap-figure-card { position: relative; display: block; min-width: 0; min-height: 0; padding: 0; overflow: hidden; border: 0; border-radius: 10px; background: none; color: #fff; text-align: left; white-space: normal; }
.ap-ui button.ap-figure-card:hover:not(:disabled) { background: none; }
.ap-figure-art { position: relative; display: block; width: 100%; aspect-ratio: 3 / 4; overflow: hidden; border-radius: 10px; background: radial-gradient(120% 80% at 50% 18%, color-mix(in srgb, var(--fork-accent) 22%, var(--fork-hover)), var(--fork-hover) 70%); }
.ap-figure-art img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center top; transition: transform .35s var(--fork-ease, ease); }
.ap-figure-art.is-standing img { width: 150%; height: auto; max-width: none; margin-left: -25%; object-fit: initial; }
.ap-ui button.ap-figure-card:hover .ap-figure-art img { transform: scale(1.04); }
.ap-figure-card[data-disabled] .ap-figure-art { filter: grayscale(.85); filter: var(--fk-current-dim, grayscale(1)); }
.ap-figure-caption { position: absolute; left: 0; right: 0; bottom: 0; display: grid; gap: 1px; padding: 26px 9px 8px; border-radius: 0 0 10px 10px; background: var(--fk-current-mediaScrim, none); text-shadow: 0 1px 2px #0008; pointer-events: none; }
.ap-figure-caption strong { overflow: hidden; font-size: var(--fork-fs-body); font-weight: 600; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.ap-ui .ap-figure-caption small { overflow: hidden; color: #ffffffc0; font-size: var(--fork-fs-meta); line-height: 1.3; text-overflow: ellipsis; white-space: nowrap; }

/* Pack category navigation: underline tabs with glyphs; a left rail (old 素材库 modal) once the panel is wide. */
.ap-kind-icon { flex: none; margin-right: 6px; color: var(--fk-current-fgMuted, var(--fork-ink-2, CanvasText)); }
.ap-ui .ap-tabs button[aria-pressed=true] .ap-kind-icon { color: var(--fork-accent); opacity: 1; }
/* Pack entries (§四 素材包详情): one calm row per entry — expand · enable · name · lamp · preview.
   Names read as text and become editable on focus; the open row is marked by the accent bar. */
.ap-lamp-dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 22%, transparent); }
/* 关闭 is a grey hollow ring wherever a lamp dot is drawn (LampMenu, its menu). */
[data-mode=off] > .ap-lamp-dot { box-sizing: border-box; background: transparent; box-shadow: inset 0 0 0 1.5px currentColor; }
.ap-ui button.ap-icon-button { width: 30px; height: 30px; min-height: 0; padding: 0; border: 0; border-radius: 50%; color: var(--fork-ink-2); }
.ap-ui button.ap-icon-button:hover:not(:disabled) { color: var(--fork-ink); }
.ap-ui button.ap-icon-button[aria-pressed=true], .ap-ui button.ap-icon-button[aria-pressed=true]:hover:not(:disabled) { background: var(--fork-accent-fill); color: var(--fork-on-accent); }
.ap-ui button.ap-icon-button[data-state=error] { color: var(--ap-error); }
.ap-icon-button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; }
.ap-icon-button svg .is-fill { fill: currentColor; stroke: currentColor; stroke-width: 1; stroke-linejoin: round; }
.ap-icon-button svg .is-stroke { stroke-width: 2.4; }
.ap-icon-button > .fork-spinner { --fork-spinner-size: 15px; }
.ap-counter { display: block; margin-top: 2px; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); text-align: right; font-variant-numeric: tabular-nums; }
.ap-counter[data-over] { color: var(--ap-error); }
.ap-field-error { display: block; margin-top: 4px; color: var(--ap-error); font-size: var(--fork-fs-meta); }
.ap-note-muted { margin: 0 0 10px; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }

/* Card page: sticky save bar. */
.ap-card { padding-bottom: 8px; }
.ap-savebar { position: sticky; bottom: 0; z-index: 2; display: flex; align-items: center; justify-content: flex-end; gap: 12px; margin: 12px -24px 0; padding: 10px 24px; border-top: 1px solid var(--ap-border); background: linear-gradient(var(--fork-surface, transparent), var(--fork-surface, transparent)), Canvas; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }
.ap-savebar[data-dirty] { color: var(--fork-ink-2); }
.ap-savebar[data-dirty] > span::before { content: ""; display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--fork-accent); vertical-align: 1px; }

/* Editors, engine settings and previews reuse the same rows. */
.ap-editor > h2, .ap-editor > h3 { margin-top: 4px; font-size: 15px; }
.ap-editor > code { margin-bottom: 8px; }
.ap-settings-grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(260px,100%),1fr)); gap: 0 24px; }
.ap-dimensions { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(170px,100%),1fr)); gap: 10px 16px; }
.ap-dimensions > label { display: flex; align-items: center; gap: 8px; }
.ap-dimensions > label > input { order: -1; }
.ap-preset { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--ap-border); }
.ap-preview-grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(160px,100%),1fr)); gap: 12px; }
.ap-ui figure { min-width: 0; margin: 10px 0; padding: 0; }
.ap-ui figcaption { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-ui figure img { display: block; max-width: 100%; max-height: 280px; margin: 6px 0; border-radius: 8px; object-fit: contain; background: var(--fork-hover); }
.ap-ui details > summary { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); cursor: pointer; }

/* Dialogs: the only second-level container; dividers inside. */
.ap-modal-scrim { position: fixed; inset: 0; z-index: 10000; display: grid; place-items: center; background: var(--fk-s-modal-veil); padding: 16px; }
/* a dialog that takes focus itself never shows a ring for it. */
.ap-modal:focus, .ap-modal:focus-visible { outline: none; }
.ap-modal { width: min(720px,100%); max-height: calc(100dvh - 32px); overflow: auto; padding: 22px 24px; border: .5px solid var(--ap-border-strong); border-radius: 14px; background: linear-gradient(var(--fork-surface, transparent), var(--fork-surface, transparent)), Canvas; box-shadow: 0 18px 60px #0000003d; }
.ap-modal > header { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 4px; }
.ap-modal > header h2 { font-size: 16px; }
@container (max-width: 560px) {
  .ap-cast-editor { padding-left: 0; }
  .ap-thumb-grid { grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); }
  .ap-actions { justify-content: flex-start; }
}
@media (max-width: 480px) {
  .ap-ui { padding: 16px 16px 0; }
  .ap-savebar { margin: 12px -16px 0; padding: 10px 16px; }
  .ap-modal { padding: 16px; }
}
.ap-ui .fork-voice-combobox-list > button { justify-content: flex-start; min-height: 0; padding: 7px 10px; border: 0; border-radius: 0; white-space: normal; }

/* the existing searchable library picker, inline card voice mode. */
.fork-voice-combobox { position: relative; min-width: 0; }
.fork-voice-combobox > input { width: 100%; }
.fork-voice-combobox-list { position: absolute; z-index: 20; top: 100%; left: 0; right: 0; max-height: 18rem; overflow-y: auto; background: var(--fork-surface, Canvas); border: 1px solid var(--fork-line, GrayText); border-radius: 6px; box-shadow: 0 8px 24px #0002; }
.fork-voice-combobox-list > button { display: block; width: 100%; padding: 8px; text-align: left; overflow-wrap: anywhere; }
.fork-voice-combobox-list > button[aria-selected=true] { background: var(--fk-current-selected, var(--fork-accent-soft, Canvas)); }

/* one Homura-style face window and ruler for every non-film theme. */
.fork-gal-stage[data-theme]:not(.is-film) .fork-gal-box {
  --cl-pad-top: clamp(12px, 1.7vh, 20px); --cl-pad-bottom: clamp(26px, 3.3vh, 36px);
  --cl-name: clamp(14px, calc(.55vw + .5vh), 17px); --cl-fs: clamp(17px, calc(.85vw + .75vh), 28px);
  --cl-box-h: calc(var(--cl-pad-top) + var(--cl-name) * 1.5 + 4px + var(--cl-fs) * 5.1 + var(--cl-pad-bottom));
  --cl-face: calc(var(--cl-box-h) * 1.5); --cl-face-out: calc(var(--cl-face) * .15);
  width: min(94%, 1560px);
}
/* retain the top/right ruler and screen-clipped left/bottom. Paint above the
   textbox surface/border/blur, within its stacking context so stage overlays stay above the face. */
.fork-gal-stage[data-theme] .fork-gal-side { bottom: calc(-1 * var(--gal-box-normal-bottom)); z-index: 1; overflow: visible; clip-path: inset(0 0 -100vmax -100vmax); }
.fork-gal-side-img.fork-pack-crop { overflow: visible; }
/* only a page that shows a face (.is-facing, latched per page
   by useGalFaceColumn) gives the face its column; narration and faceless pages start at the box's own padding in
   every theme. The page counter moves with the text column so it never sits under the face. */
.fork-gal-stage[data-theme]:not([data-theme="classic"]):not(.is-film) .fork-gal-box.has-face.is-facing {
  --text-left: calc(var(--cl-face) - var(--cl-face-out) + 22px);
  padding-left: var(--text-left);
}
.fork-gal-stage[data-theme]:not([data-theme="classic"]):not(.is-film) .fork-gal-box.has-face.is-facing .fork-gal-meta { left: var(--text-left); }
/* Phones: the compact control row starts at the text column, so the counter keeps its old place left of it. */
@media (max-width: 640px) { .fork-gal-stage[data-theme]:not([data-theme="classic"]):not(.is-film) .fork-gal-box.has-face.is-facing .fork-gal-meta { left: calc(var(--face-w) + var(--face-gap)); } }
@media (max-width: 640px) {
  .fork-gal-stage[data-theme]:not(.is-film) .fork-gal-box { width: 96%; --cl-face: calc(var(--cl-box-h) * 1.1); }
}
/* phones (≤ 640 px, the one stage breakpoint). The control row keeps four 44 px targets
   (自动 / 跳过 / 履历 / ≡, galControlIds in gal-stage.js; the rest is in the menu); the row's lower
   edge reaches into the margin under the box, so the box and its text layout keep their size. The top bar (
   「手机版就不要显示 bgm，地点的文字了，纯 icon 吧」): one row of 44 px icon buttons in every skin - the place and the track
   name are not shown (they stay in the buttons' aria-label / title, and in the panels they open); a place without its
   background button has no icon and is not shown. Wider screens are unchanged (.fork-gal-hud-line is display: contents there). */
.fork-gal-hud-line { display: contents; }
@media (max-width: 640px) {
  .fork-gal-stage[data-theme] .fork-gal-controls[data-compact] { gap: 0; }
  .fork-gal-stage[data-theme] .fork-gal-controls[data-compact] .fork-gal-control { box-sizing: border-box; width: 44px; height: 44px; padding: 3px 7px 11px; background-clip: content-box; } /* a 30 px glyph chip on the page count's line, inside a 44 px target */
  .fork-gal-stage[data-theme]:not(.is-film) .fork-gal-controls[data-compact] { bottom: -12px; }
  /* Icons never shrink: the two groups are one packed group of
     44 px icons - scene icons, then the features, side by side
     - at the top centre.
     --bar-l / --bar-r are the free width's edges (the screen's, or a skin's drawn top buttons, 「stage skin: art」); the group's
     widest row (--fk-bar-group, gal-stage.js galTopbarGroup: the icons packed into that width) is a box centred on the stage's centre
     line, moved only as far as the drawn buttons need. More icons than one row takes wrap onto further rows, which start at
     the box's left edge as lines of text do (「第一行不一定填满，所以默认中间显示，如果需要第二行的话，因为第一行一定满了，
     所以第二行开始的图标就左对齐」): one row is the box itself, centred; the first of several fills it. Without the measure the
     box is the whole free width. The box keeps 1px of slack against rounding, on its right: the row starts where a centred
     row of the same width would (the left edge's +1px is 0 while the measure reads the free width). */
  .fork-gal-stage[data-theme] .fork-gal-topbar,
  .fork-gal-stage[data-theme="crt"]:not([data-fk-skin]) .fork-gal-topbar { --bar-l: 8px; --bar-r: 8px; flex-wrap: wrap; justify-content: flex-start; align-items: flex-start; align-content: flex-start; gap: 0;
    padding: 4px clamp(var(--bar-r), calc(50% - var(--fk-bar-group, 100%) / 2 - 1px), calc(100% - var(--bar-l) - var(--fk-bar-group, 100%) - 2px)) 0
      clamp(calc(var(--bar-l) + min(1px, 100% - var(--fk-bar-group, 100%))), calc(50% - var(--fk-bar-group, 100%) / 2), calc(100% - var(--bar-r) - var(--fk-bar-group, 100%) - 1px)); }
  .fork-gal-stage .fork-gal-topbar :is(.fork-gal-topleft, .fork-gal-topright) { display: contents; }
  .fork-gal-stage .fork-gal-topbar > :is(.fork-gal-topleft, .fork-gal-topright) > :not(.fork-stage-entry),
  .fork-gal-stage .fork-gal-topbar > :is(.fork-gal-topleft, .fork-gal-topright) > .fork-stage-entry > * { flex: none; }
  .fork-gal-stage .fork-gal-topbar :is(.fork-gal-film, .fork-gal-quit, .fork-gal-mixer-toggle, .fork-gal-danmaku, .fork-widget-menu button.fork-widget-menu-trigger) { width: 44px; height: 44px; }
  .fork-gal-stage .fork-gal-topbar .fork-gal-generate-turn { height: 44px; }
  .fork-gal-stage .fork-gal-topbar .fork-gal-hud-line { display: flex; flex: none; align-items: center; height: 44px; }
  .fork-gal-stage .fork-gal-topbar :is(.fork-gal-place-name, .fork-gal-track-name, .fork-gal-hud-from, .fork-gal-place:not(.fork-bg-chip)) { display: none; }
  .fork-gal-stage .fork-gal-topbar :is(.fork-gal-place.fork-bg-chip, .fork-gal-track) { flex: none; justify-content: center; width: 44px; max-width: none; height: 44px; padding: 0; border: 0; border-radius: 50%; }
  .fork-gal-stage .fork-gal-topbar .fork-gal-place.is-changing::before, .fork-gal-stage .fork-gal-topbar .fork-gal-place.is-changing::after { content: none; }
}

/* 舞台设置 — one card-centric page, auto-saved, hairline sections. */
/* The page (not the panel root) is the size container, so dialogs rendered beside it position against the viewport. */
.ap-ui.ap-stage { container-type: normal; }
.ap-stage .ap-head { position: relative; align-items: center; min-height: 28px; }
.ap-stage-page { position: relative; container-type: inline-size; }
.ap-save-state { position: absolute; top: -12px; right: 0; margin: 0; min-height: 18px; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-save-state[data-state=error] { color: var(--ap-error); }
/* a draft page's 「有未保存的修改」 is the same save state, in its sticky save bar (CG, 引擎设置, 演出风格). */
:where(.ap-cg-savebar, .ap-engine-foot) > .ap-save-state { position: static; display: inline-flex; align-items: center; gap: 6px; min-height: 0; margin-right: auto; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-save-state[data-state=dirty]::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--fork-accent); }
.ap-ui button.ap-inline-link { min-height: 0; height: auto; padding: 0; border: 0; border-radius: 0; background: none; color: var(--fork-accent); font-size: inherit; vertical-align: baseline; }
.ap-ui button.ap-inline-link:hover:not(:disabled) { background: none; text-decoration: underline; text-underline-offset: 2px; }
.ap-need { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 400; white-space: nowrap; }
.ap-section[data-blocked] > .ap-section-body { filter: var(--fk-current-dim, grayscale(1)); filter: saturate(.4); pointer-events: none; user-select: none; }
.ap-section-body { min-width: 0; }
.ap-inline-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 10px 0 4px; }
.ap-inline-actions.is-start { margin-top: 0; }
.ap-note-muted { margin: 6px 0 10px; }
.ap-warn { margin: 4px 0; padding-left: 10px; border-left: 2px solid var(--dsw-alias-state-warning-primary, #c98a12); color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-issue { margin-left: 8px; color: var(--fork-accent); font-size: var(--fork-fs-meta); font-style: normal; }
/* A state that needs an action (HintLine): warning mark + short state in normal ink + one link chip; compact on a
   switch row (mark + chip only, the state is the tooltip). Never an indented grey note. */
.ap-hint-line { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 6px 0; color: var(--fork-ink); font-size: var(--fork-fs-meta); }
.ap-hint-line.is-compact { display: inline-flex; flex-wrap: nowrap; margin: 0; font-weight: 400; }
/* 「智能判断 未设置」's ⚠ sits right after the heading, wrapping under it when narrow. */
.ap-engine-judge > .ap-section-head { flex-wrap: wrap; row-gap: 4px; }
.ap-engine-judge > .ap-section-head > .ap-hint-line { margin: 0 auto 0 0; }
.ap-hint-mark { display: inline-flex; flex: none; color: var(--fork-warn); }
.ap-hint-mark .ap-glyph { width: 15px; height: 15px; }
/* a panel that failed to render — ⚠ + one line + 重试 in its own place
   (PanelBoundary). The 22 px chip reaches a 30 px (phone 36 px) hit area without growing the line. */
.fork-panel-error { margin: 8px 0; }
.fork-panel-error .ap-hint-mark .fork-inline-glyph { width: 15px; height: 15px; color: inherit; }
.fork-panel-error > .ap-hint-chip { position: relative; }
.fork-panel-error > .ap-hint-chip::after { content: ""; position: absolute; inset: -4px -2px; }
@media (max-width: 720px) { .fork-panel-error > .ap-hint-chip::after { inset: -7px -4px; } }
.ap-ui button.ap-hint-chip { min-height: 0; height: 22px; padding: 0 9px; border: 0; border-radius: 11px; background: var(--fork-accent-soft, var(--fk-current-selected, Canvas)); color: var(--fork-accent); font-size: var(--fork-fs-meta); font-weight: 500; line-height: 1; white-space: nowrap; cursor: pointer; }
.ap-ui button.ap-hint-chip:hover:not(:disabled) { background: color-mix(in srgb, var(--fork-accent) 22%, var(--fk-current-bgSolid, Canvas)); }

/* First run: the single solid button on the page. */
.ap-first-run { padding: 26px 0 10px; border-top: 1px solid var(--ap-border); }
.ap-first-title { margin: 0 0 6px; font-size: 15px; font-weight: 600; }
.ap-first-run .ap-inline-actions { margin-top: 14px; }
.ap-first-run .ap-primary .ap-glyph { margin-right: 6px; vertical-align: -3px; }

/* Switch rows: label + switch on one line, a quiet description under it. */
.ap-switch-row { padding: 8px 0 6px; }
.ap-switch-row + .ap-switch-row { border-top: 1px dashed var(--ap-border); }
.ap-switch-main { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 28px; font-size: var(--fork-fs-body); font-weight: 500; cursor: pointer; }
.ap-switch-name { display: inline-flex; align-items: center; gap: 8px; min-width: 0; order: 1; margin-right: auto; }
.ap-switch-main > .ap-hint-line { order: 2; margin-right: -6px; }
.ap-switch-main > input { order: 3; }
.ap-switch-name > .ap-glyph { color: var(--fork-ink-2); }
.ap-switch-name .ap-help-anchor { margin-left: 0; }
.ap-switch-row[data-disabled] .ap-switch-main { color: var(--ap-ink-3); cursor: default; }

/* Packs used by the card. */
.ap-pill.is-muted { background: var(--fork-hover, var(--fk-current-hover, var(--fork-hover, Canvas))); color: var(--fork-ink-2); font-weight: 500; }
.ap-plain-value { font-size: var(--fork-fs-body); }
.ap-figure-meta { display: inline-flex; align-items: center; gap: 3px; margin-right: 8px; }
.ap-figure-meta .ap-glyph { width: 12px; height: 12px; }
.ap-pill { display: inline-flex; align-items: center; height: 18px; padding: 0 7px; border-radius: 9px; background: var(--fork-accent-soft, var(--fk-current-selected, var(--fork-accent-soft, Canvas))); color: var(--fork-accent); font-size: var(--fork-fs-meta); font-weight: 600; letter-spacing: .04em; }
.ap-ui button.ap-more { width: 28px; height: 28px; font-size: 16px; letter-spacing: .05em; }
.ap-popover-anchor { position: relative; display: inline-block; }
.ap-popover { position: absolute; z-index: 30; top: calc(100% + 4px); right: 0; min-width: 200px; max-width: min(340px, 86vw); max-height: 320px; overflow: auto; padding: 4px;
  border: .5px solid var(--ap-border-strong); border-radius: 10px; background: linear-gradient(var(--fork-surface, transparent), var(--fork-surface, transparent)), Canvas; box-shadow: 0 10px 32px #0000002e; }
.ap-ui .ap-menu-item { display: flex; justify-content: flex-start; width: 100%; min-height: 32px; padding: 0 10px; border: 0; border-radius: 6px; font-size: var(--fork-fs-body); }
.ap-ui .ap-menu-item.is-danger { color: var(--ap-error); }
.ap-ui button.ap-chip-button { min-height: 26px; margin-left: 8px; padding: 0 12px; font-size: var(--fork-fs-meta); }

/* Cast rows. */
.ap-cast-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin-top: 3px; }
.ap-cast-chip { display: inline-flex; align-items: center; justify-content: center; min-width: 20px; height: 20px; padding: 0 3px; border-radius: 6px; background: var(--fork-hover, var(--fk-current-hover, var(--fork-hover, Canvas))); color: var(--fork-ink-2); }
.ap-cast-chip .ap-glyph { width: 13px; height: 13px; }
.ap-cast-mark { font-size: var(--fork-fs-meta); font-weight: 600; line-height: 1; }
.ap-cast-chips .ap-issue { margin-left: 2px; }
.ap-stage .ap-create { max-width: 420px; }
.ap-stage .ap-create .ap-link, .ap-ui .ap-stage .ap-create button.ap-icon-button:not(:disabled) { color: var(--fork-accent); }

/* Emotion chips: builtin and card emotions are the same filled pill. Fill = --chip-color 14% over the surface, text =
   --chip-color at the surface table's --fk-current-chipInk share over the surface ink (surfaces.cjs EMOTIONS,
   validated 4.5:1 for every builtin and card colour). Card emotions get their colour from forkSurfaces.emotionColors;
   only the ＋ chip is outlined. */
.ap-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.ap-chip { display: inline-flex; align-items: center; box-sizing: border-box; height: 24px; padding: 0 10px; border: .5px solid transparent; border-radius: 12px; font-size: var(--fork-fs-meta); }
.ap-chip.is-builtin, .ap-ui button.ap-chip.is-custom { background: color-mix(in srgb, var(--chip-color) 14%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--chip-color) var(--fk-current-chipInk, 62%), var(--fk-current-fg, var(--fork-ink))); }
.ap-ui button.ap-chip { min-height: 0; height: 24px; padding: 0 10px; font-size: var(--fork-fs-meta); }
.ap-ui button.ap-chip.is-custom { border-color: transparent; }
.ap-ui button.ap-chip.is-custom:hover:not(:disabled) { border-color: color-mix(in srgb, var(--chip-color) 60%, var(--fk-current-bgSolid, Canvas)); background: color-mix(in srgb, var(--chip-color) 14%, var(--fk-current-bgSolid, Canvas)); }
.ap-ui button.ap-chip.is-custom:focus-visible { outline: 2px solid var(--chip-color); outline-offset: 1px; }
.ap-ui button.ap-chip.is-add { width: 24px; padding: 0; border: .5px dashed var(--ap-border-strong); }

/* Director dimensions: grouped toggle chips (.ap-check-row, a ✓ when on) — 舞台模式 › 可用演出 only (global only).
   no native checkboxes. Most are on, so on is the calm state (ink + filled ✓) and off
   reads quieter (muted ink, empty ring) instead of a page of accent chips. */
.ap-ui .ap-dimension-list button.ap-check-row[aria-checked=true] { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui .ap-dimension-list button.ap-check-row[aria-checked=false] { background: none; box-shadow: inset 0 0 0 1px var(--ap-border-strong); color: var(--fork-ink-2); }
.ap-dimension-list { display: flex; flex-wrap: wrap; gap: 6px; }
.ap-check-row[data-changed]::after { content: ""; flex: none; width: 5px; height: 5px; margin-left: -2px; border-radius: 50%; background: currentColor; }
.ap-ui .ap-radio input { appearance: auto; width: 15px; height: 15px; margin: 0; border-radius: 3px; background: none; accent-color: var(--fork-accent); }
.ap-radio-list { display: grid; gap: 2px; margin: 4px 0 6px; }
.ap-radio { display: flex; align-items: flex-start; gap: 10px; padding: 6px 0; cursor: pointer; }
.ap-ui label.ap-radio > input[type=radio]:not([type=checkbox]):not([type=file]) { flex: none; width: 15px; height: 15px; min-height: 0; margin: 3px 0 0; padding: 0; border: 0; box-shadow: none; accent-color: var(--fork-accent); }
.ap-radio > span { display: grid; }
.ap-radio small { color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }

/* the global 读音词典 in the 配音 page (ReadingsEditor) — the
   preset menu with its ⋯, the search box, a windowed list of fixed 36px lines 写法 → 读音 · language tag · ✕ (borderless
   ForkInlineFields; only the lines in view are mounted) and the add line (InlineAdd: 写法 → 读音). */
.ap-ui.fork-readings { width: auto; max-width: none; min-height: 0; margin: 0; padding: 0; background: none; flex-shrink: 1; }
.fork-readings-bar { display: flex; align-items: center; gap: 8px; min-height: 36px; }
.fork-readings-bar > .fork-readings-preset, .fork-readings-bar > .fork-readings-name { flex: 1 1 auto; min-width: 0; }
.fork-readings-search { margin: 6px 0 4px; }
.ap-readings { position: relative; overflow-y: auto; overscroll-behavior: contain; container-type: inline-size; }
.ap-readings-track { position: relative; }
.ap-readings-row { display: grid; grid-template-columns: minmax(0,1fr) 14px minmax(0,1fr) 66px 28px; column-gap: 8px; align-items: center; height: 36px; }
.ap-readings-track > .ap-readings-row { position: absolute; top: 0; left: 0; right: 0; contain: layout style; }
.ap-readings-row > .ap-reading-lang-anchor { grid-column: 4; justify-self: end; }
.ap-readings-row > .ap-reading-remove { grid-column: 5; justify-self: center; }
.ap-reading-arrow { color: var(--ap-ink-3); font-size: var(--fork-fs-meta); text-align: center; }
.ap-readings-row > .fork-inline-field.ap-reading-field { min-width: 0; min-height: 30px; }
.ap-readings-row > .fork-inline-field.is-form { font-weight: 600; }
.ap-ui .ap-readings-row button.ap-reading-remove { width: 26px; height: 26px; min-height: 0; padding: 0; border: 0; border-radius: 7px; background: none; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }
.ap-ui .ap-readings-row button.ap-reading-remove:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-reading-lang-anchor { justify-self: start; }
.ap-ui .ap-readings-row button.ap-reading-lang, .ap-ui .ap-readings-row button.ap-reading-lang:not(:disabled) { align-self: center; height: 24px; min-height: 0; padding: 0 9px; }
.ap-ui button.ap-reading-lang { gap: 3px; min-height: 0; height: 22px; padding: 0 8px; border: 0; border-radius: 11px; background: var(--fork-hover); color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 500; white-space: nowrap; }
.ap-ui button.ap-reading-lang:hover:not(:disabled) { color: var(--fork-ink); }
.ap-ui button.ap-reading-lang.is-warn { background: color-mix(in srgb, var(--fork-warn) 14%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-warn); }
.ap-reading-lang-anchor .ap-popover { min-width: 132px; }
/* The add line: Enter in 写法 moves to 读音, Enter in 读音 adds and starts the next one; Esc closes it. */
.ap-readings-row.is-new { grid-template-columns: minmax(0,1fr) 14px minmax(0,1fr) 102px; margin-top: 2px; }
.ap-readings-row.is-new > input.fork-readings-input { min-width: 0; }
.ap-ui button.fork-inline-add.fork-readings-add { width: 28px; height: 28px; margin-top: 4px; border-radius: 8px; }
@container (max-width: 300px) { .ap-readings-row { grid-template-columns: minmax(0,1fr) 14px minmax(0,1fr) 28px; } .ap-readings-row > .ap-reading-lang-anchor { display: none; } .ap-readings-row > .ap-reading-remove { grid-column: 4; } }
/* the quiet 「›」 on a 基础设置 row — the 素材库 at that kind; no text, no frame. */
.ap-ui button.ap-kind-jump { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 24px; min-height: 0; height: 24px; margin: 0 0 0 -10px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--fork-ink-2); }
.ap-ui button.ap-kind-jump:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui button.ap-kind-jump:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.ap-kind-jump .ap-glyph { width: 14px; height: 14px; }
.ap-kind-jump-anchor .ap-popover { min-width: 160px; }
/* Right after the row's name (「BGM ›」), the switch stays at the far right. */
.ap-switch-main > .ap-kind-jump, .ap-switch-main > .ap-kind-jump-anchor { order: 1; margin-right: auto; }
.ap-switch-main:has(> .ap-kind-jump, > .ap-kind-jump-anchor) > .ap-switch-name { margin-right: 0; }
.ap-switch-main > .ap-kind-jump-anchor { display: inline-flex; flex: none; width: auto; min-width: 0; margin-left: -10px; }
.ap-switch-main > .ap-kind-jump-anchor > button.ap-kind-jump { margin-left: 0; }
.ap-ui .ap-switch-main > button.ap-kind-jump { margin-right: auto; }
/* 「配音 › ⚠」 — the ⚠ of a current failure follows the 「›」 beside the name,
   never on the right; the name itself opens 声音设置 (pointer only; the 「›」 is the keyboard route). */
.ap-switch-main > .ap-switch-warn { order: 1; margin: 0 auto 0 -10px; cursor: default; }
.ap-ui .ap-switch-main > button.ap-kind-jump:has(+ .ap-switch-warn) { margin-right: 0; }
.ap-switch-main:has(> .ap-switch-warn) > .ap-switch-name { margin-right: 0; }
/* a row with a page (SwitchRow onOpen, 舞台模式) opens it from anywhere but
   the switch: the row paints on hover (not while the pointer is on the switch, which gets its own halo), its 「›」 darkens,
   and the 「›」's keyboard focus rings the whole row. The switch's hit area grows to 30px around the 36×20 track. */
.ap-switch-row.is-openable { position: relative; isolation: isolate; cursor: pointer; }
.ap-switch-row.is-openable::before { content: ""; position: absolute; inset: 0 -6px; z-index: -1; border-radius: 8px; pointer-events: none; }
.ap-switch-row.is-openable:hover:not(:has(.ap-switch-hit:hover, .ap-help-anchor:hover, .ap-hint-chip:hover))::before { background: var(--fork-hover); }
.ap-switch-row.is-openable:has(.ap-kind-jump:focus-visible)::before { outline: var(--fork-focus); outline-offset: -2px; }
.ap-ui .ap-switch-row.is-openable button.ap-kind-jump:focus-visible { outline: none; }
.ap-ui .ap-switch-row.is-openable:hover:not(:has(.ap-switch-hit:hover)) button.ap-kind-jump { color: var(--fork-ink); }
.ap-switch-row.is-openable .ap-switch-main, .ap-switch-row.is-openable[data-disabled] .ap-switch-main { cursor: pointer; }
.ap-switch-hit { display: inline-flex; flex: none; order: 3; align-items: center; margin: -5px -6px -5px -8px; padding: 5px 6px 5px 8px; cursor: pointer; }
.ap-switch-row[data-disabled] .ap-switch-hit { cursor: default; }
.ap-ui .ap-switch-hit:hover > input[type=checkbox]:not(:disabled) { box-shadow: 0 0 0 4px var(--fork-hover); }
@media (pointer: coarse) { .ap-switch-hit { margin-block: -8px; padding-block: 8px; } }
@media (pointer: coarse) { .ap-ui button.ap-kind-jump { width: 32px; height: 32px; } }


/* 开场画面: one row per greeting (scene thumbnail + first line); the editor is a single dialog, no inner boxes. */
/* 开场设置 opens in place. Closed, the head is one button: the title on the left, a
   compact summary on the right (主角 face + name, the first greeting's picture, BGM, skin) and a chevron. Open, every
   field shares one label column and one control width (360px), the skin select included. Narrow: the summary wraps
   under the title. */
.ap-stage .ap-opening-head { padding-bottom: 0; }
.ap-opening-head > h3 { flex: 1; min-width: 0; margin: 0; }
.ap-ui button.ap-opening-toggle { display: flex; align-items: center; gap: 14px; width: 100%; min-height: 40px; height: auto; margin: 0; padding: 0 0 6px; border: 0; border-radius: 0; background: none; color: inherit; font: inherit; text-align: left; white-space: nowrap; cursor: pointer; }
.ap-ui button.ap-opening-toggle:hover:not(:disabled) { background: none; }
.ap-ui button.ap-opening-toggle:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 2px; border-radius: 6px; }
.ap-opening-title { flex: none; }
.ap-opening-summary { display: flex; flex: 1 1 auto; justify-content: flex-end; align-items: center; gap: 16px; min-width: 0; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-body); font-weight: 400; }
.ap-opening-summary-item { display: inline-flex; flex: 0 1 auto; align-items: center; gap: 6px; min-width: 0; }
.ap-opening-summary-item > span:last-child { min-width: 0; max-width: 9em; overflow: hidden; text-overflow: ellipsis; }
.ap-opening-summary-item.is-picture { flex: none; }
.ap-opening-summary-item > .ap-glyph { flex: none; width: 14px; height: 14px; color: var(--fork-ink-3); }
.ap-opening-summary-item .ap-avatar.is-mini { flex: none; }
.ap-opening-summary .ap-opening-summary-thumb { display: block; width: 46px; height: auto; aspect-ratio: 16 / 9; border-radius: 4px; object-fit: cover; }
.ap-opening-chevron { display: inline-flex; flex: none; color: var(--fork-ink-3); transition: transform .15s; }
.ap-opening-toggle[aria-expanded=true] .ap-opening-chevron { transform: rotate(180deg); }
.ap-opening-toggle[aria-expanded=true] .ap-opening-title { margin-right: auto; }
@container (max-width: 520px) {
  .ap-ui button.ap-opening-toggle { flex-wrap: wrap; row-gap: 8px; }
  .ap-opening-title { margin-right: auto; }
  .ap-opening-summary { order: 3; flex-basis: 100%; justify-content: flex-start; gap: 14px; }
}
/* 开场设置 is one column of inline rows (InlineRow); every picker in an
   inline row (开场 pickers, 皮肤, a widget's 壁纸) reads as its value with a chevron — no box, an underline on hover, like
   InlineField's menus. */
.ap-opening-field.fork-inline-field { --fork-inline-label-w: 112px; align-items: start; }
.ap-opening-field > .fork-inline-label { min-height: 38px; }
.ap-opening-field > .fork-inline-value > * { min-width: 0; max-width: 100%; }
.ap-opening-section .ap-skin-anchor { max-width: none; }
.ap-opening-section .ap-skin-trigger .fork-gal-config-theme-art { width: 40px; height: 24px; }
.ap-ui .fork-inline-field :is(.ap-opening-picker > button.ap-target-button, .ap-opening-add > button.ap-target-button, button.ap-skin-trigger):not([data-fi-a]):not([data-fi-b]) { width: auto; max-width: 100%; height: 32px; min-height: 0; gap: 8px; padding: 0 6px; border: 0; border-radius: 6px; background: none; box-shadow: none; color: var(--fork-ink); font-size: 13.5px; font-weight: 400; letter-spacing: 0; justify-content: flex-start; }
.ap-ui .fork-inline-field :is(.ap-opening-picker > button.ap-target-button, .ap-opening-add > button.ap-target-button, button.ap-skin-trigger):not([data-fi-a]):not([data-fi-b]):is(:hover, [aria-expanded=true]) { background: var(--fork-hover); }
.ap-ui .fork-inline-field .ap-opening-picker.has-art > button.ap-target-button:not([data-fi-a]):not([data-fi-b]) { padding-left: 0; }
.fork-inline-field .ap-opening-picker:not(.is-compact) { display: inline-block; max-width: 100%; }
.fork-inline-field .ap-opening-picker.has-art .ap-opening-picker-value { flex: 0 1 auto; }
.ap-ui .fork-inline-field .ap-opening-add > button.ap-target-button:not([data-fi-a]):not([data-fi-b]) { color: var(--fork-accent); }
.ap-ui .fork-inline-field .ap-opening-picker.is-compact > button.ap-target-button:not([data-fi-a]):not([data-fi-b]) { height: 30px; }
.ap-opening-greeting { display: grid; gap: 4px; min-width: 0; }
.ap-opening-greeting-meta { display: flex; align-items: center; gap: 8px; min-width: 0; min-height: 24px; }
.ap-opening-custom { display: inline-flex; flex: none; align-items: center; gap: 2px; }
.ap-opening-scene { margin-top: 2px; }
.ap-ui .ap-opening-line { flex: 1 1 auto; min-width: 0; margin: 0; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-body); text-overflow: ellipsis; white-space: nowrap; }
/* 开场背景 — a small thumbnail (240px, the picture's own aspect; 16:9 until it has loaded)
   with the background's name under it; the thumbnail is the button that opens the background picker. */
.ap-ui button.ap-opening-bg-button { display: inline-grid; justify-items: start; gap: 4px; width: auto; max-width: 100%; height: auto; min-height: 0; margin: 3px 0 4px; padding: 0; border: 0; border-radius: 8px; background: none; color: var(--fork-ink-2); font: inherit; font-size: var(--fork-fs-meta); text-align: left; cursor: pointer; }
.ap-ui button.ap-opening-bg-button:hover:not(:disabled) { background: none; color: var(--fork-ink); }
.ap-ui button.ap-opening-bg-button:hover .ap-opening-stage, .ap-ui button.ap-opening-bg-button[aria-expanded=true] .ap-opening-stage { box-shadow: 0 0 0 2px var(--fork-accent-soft); }
.ap-ui button.ap-opening-bg-button:focus-visible { outline: var(--fork-focus); outline-offset: 2px; }
.ap-opening-bg-button .ap-opening-stage { display: block; width: 240px; max-width: 100%; height: auto; aspect-ratio: auto; border-radius: 8px; object-fit: cover; transition: box-shadow .15s; }
.ap-opening-bg-button span.ap-opening-stage:is([data-empty], [data-ap-media=loading]) { aspect-ratio: 16 / 9; }
.ap-opening-bg-button span.ap-opening-stage img { height: auto; }
.ap-opening-bg-name { max-width: 240px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* The picker: the library's background rows (EntryItem) in a grid, one group per pack, 「无」 first. */
.ap-modal.ap-opening-bg-modal { display: flex; flex-direction: column; width: min(980px, 92vw, 100%); height: min(760px, 88dvh); padding: 0; overflow: hidden; }
.ap-opening-bg-modal > .ap-modal-body { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.ap-opening-bg-tools { flex: none; flex-wrap: wrap; }
.ap-opening-bg-tools > .ap-search { flex: 0 1 320px; }
.ap-opening-bg-category { flex: none; max-width: 14em; }
.ap-opening-bg-body { flex: 1; min-height: 0; overflow: auto; padding: 0 0 16px; }
.ap-ui .ap-opening-bg-items { flex: none; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); overflow: visible; padding-bottom: 4px; }
.ap-opening-bg-group-head { padding: 10px 20px 4px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 600; }
.ap-opening-bg-none { display: block; object-fit: cover; }
@media (max-width: 720px) {
  .ap-modal.ap-opening-bg-modal { width: 100%; height: 100%; max-height: 100dvh; border: 0; border-radius: 0; }
  .ap-ui .ap-opening-bg-items { grid-template-columns: minmax(0, 1fr); }
  .ap-opening-bg-tools > .ap-search { flex: 1 1 0; min-width: 0; }
}
@container (max-width: 560px) {
  .ap-opening-field.fork-inline-field { --fork-inline-label-w: 4.5em; }
}
.ap-opening-actor { display: flex; align-items: center; gap: 8px; min-height: 44px; }
.ap-opening-actor + .ap-opening-actor { border-top: 1px solid var(--ap-border); }
.ap-opening-name { flex: 1; min-width: 0; font-size: var(--fork-fs-body); font-weight: 500; }
.ap-opening-moves { display: inline-flex; gap: 2px; }
/* the opening editor's pickers are packs-v3 Popover menus (no native select); a graded preview carries
   its stage colour matrix in a zero-size SVG filter beside the picture. */
.ap-opening-grade { position: absolute; width: 0; height: 0; overflow: hidden; pointer-events: none; }
.ap-opening-picker:not(.is-compact) { display: block; }
.ap-ui .ap-opening-picker:not(.is-compact) > button.ap-target-button { width: 100%; justify-content: space-between; }
.ap-ui .ap-opening-actor .ap-opening-picker > button.ap-target-button { max-width: 9.5em; height: 30px; }
.ap-opening-picker-value { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* percentage widths only for an in-flow menu; a floating one (top layer, position: fixed) would take
   the window's width — its width comes from popoverPlace (fit: at least the trigger's). */
.ap-opening-picker:not(.is-compact) > .ap-popover:not(.is-floating) { min-width: 100%; box-sizing: border-box; }
.ap-opening-picker.is-compact .ap-popover { left: auto; right: 0; min-width: 160px; }
.ap-opening-menu-label { flex: 1; min-width: 0; }
.ap-opening-menu-group + .ap-opening-menu-group { margin-top: 4px; padding-top: 4px; border-top: 1px solid var(--ap-border); }
.ap-opening-menu-head { padding: 4px 10px 2px; color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 600; letter-spacing: .04em; }
.ap-opening-add { display: block; width: max-content; margin-top: 6px; }
.ap-opening-add .ap-avatar.is-mini { flex: none; }

/* Dialogs: a neutral dark scrim in both schemes (CanvasText would wash a dark page out to grey). */
.ap-stage .ap-modal-scrim { background: var(--fk-s-modal-veil); }
.ap-confirm { width: min(460px, 100%); }
.ap-confirm-extra { color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.ap-ui button.ap-danger-text { border-color: transparent; color: var(--ap-error); }
.ap-busy { display: inline-flex; align-items: center; gap: 6px; margin-right: auto; color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }
.ap-actions .ap-actions-start { margin-right: auto; }

/* Character modal v2 (panel-ui-design.md §六之三): 560px; header (avatar · name + save state · ⋯ · ✕), no footer;
   four hairline sections at one rhythm; every form row uses one grammar (icon + name column, control column). */
.ap-modal.ap-character-modal { display: flex; flex-direction: column; width: min(560px, 100%); padding: 0; overflow: hidden; }
.ap-character-head { display: grid; grid-template-columns: 40px minmax(0,1fr) auto auto; align-items: center; gap: 6px 10px; padding: 16px 18px 12px 22px; border-bottom: 1px solid var(--ap-border); }
.ap-character-head .ap-avatar { width: 40px; height: 40px; border-radius: 10px; }
.ap-character-title { display: grid; min-width: 0; }
.ap-character-head h2 { overflow: hidden; font-size: var(--fork-fs-title); text-overflow: ellipsis; white-space: nowrap; }
.ap-character-head .ap-save-state { position: static; min-height: 0; line-height: 16px; }
.ap-character-head .ap-save-state:empty { display: none; }
.ap-ui button.ap-close { width: 30px; height: 30px; font-size: var(--fork-fs-body); }
.ap-modal-body { flex: 1; min-height: 0; overflow: auto; padding: 0 22px 20px; }
.ap-character-modal .ap-modal-body { container-type: inline-size; }
.ap-character-modal .ap-section { padding: 16px 0 10px; }
.ap-character-modal .ap-section-head { min-height: 26px; margin-bottom: 8px; }
.ap-character-modal .ap-section:first-child { border-top: 0; }
.ap-section-wrap > .ap-section:first-child { border-top: 1px solid var(--ap-border); }
/* One row grammar: 104px label column (16px line icon + short name, ? after it), control column filling the rest. */
.ap-form-row { display: grid; grid-template-columns: 104px minmax(0,1fr); align-items: center; gap: 12px; min-height: 34px; margin: 6px 0; }
.ap-form-label { display: inline-flex; align-items: center; gap: 7px; min-width: 0; color: var(--fork-ink-2); font-size: var(--fork-fs-body); white-space: nowrap; }
.ap-form-label > .ap-glyph { flex: none; width: 15px; height: 15px; }
.ap-form-label > label { cursor: pointer; }
.ap-form-label .fork-help-tip, .ap-form-label .ap-help-anchor { margin-left: 0; }
.ap-form-control { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-width: 0; min-height: 32px; }
.ap-form-control > input:not([type=checkbox]):not([type=color]), .ap-form-control > select, .ap-form-control > textarea, .ap-form-control > .fork-voice-combobox { flex: 1 1 0; min-width: 0; }
.ap-form-control > .ap-field-error { flex-basis: 100%; margin: 0; }
.ap-ui .ap-form-control > button.ap-icon-button { flex: none; width: 32px; height: 32px; border-radius: 8px; }
.ap-ui .ap-form-control > button.ap-icon-button:hover:not(:disabled) { background: var(--fork-hover); }
.ap-form-row:has(textarea) { align-items: start; }
.ap-form-row:has(textarea) > .ap-form-label { padding-top: 7px; }
.ap-form-row[data-blocked] > .ap-form-label { color: var(--ap-ink-3); }
.ap-form-row.is-switch > .ap-form-control { min-height: 28px; }
.ap-swatches { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.ap-ui button.ap-swatch { width: 22px; height: 22px; min-height: 0; padding: 0; border: 0; border-radius: 50%; background: var(--swatch); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fork-ink) 10%, transparent); }
.ap-ui button.ap-swatch:hover:not(:disabled) { background: var(--swatch); transform: scale(1.08); }
.ap-ui button.ap-swatch[aria-checked=true] { box-shadow: 0 0 0 2px var(--fork-surface, Canvas), 0 0 0 4px var(--swatch); }
.ap-swatch-custom { display: inline-flex; align-items: center; gap: 6px; margin-left: 4px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); cursor: pointer; }
.ap-ui .ap-swatch-custom input[type=color] { width: 26px; height: 22px; }
.ap-id-value { font: 11.5px/1.6 var(--ap-mono); color: var(--fork-ink-2); }
.ap-head-tools { display: inline-flex; align-items: center; gap: 6px; }
.ap-head-tools .ap-issue { margin: 0; }
.ap-ui button.ap-icon-button.ap-head-icon { width: 26px; height: 26px; }
.ap-head-icon .ap-glyph { width: 14px; height: 14px; }
.ap-file-button.is-accent { border-color: var(--fork-accent); color: var(--fork-accent); }
.ap-file-button[data-disabled] { filter: var(--fk-current-dim, grayscale(1)); pointer-events: none; }
.ap-ui .ap-file-button { min-height: 28px; padding: 0 12px; font-size: var(--fork-fs-body); }

/* 形象: one stage card (what the stage draws), outfit chips + one tool group under it, then avatar · height · 不上舞台. */
.ap-stage-card { position: relative; height: 248px; overflow: hidden; border-radius: 12px; isolation: isolate;
  --ap-stage-glow: color-mix(in srgb, var(--fork-accent) 18%, var(--fk-current-bgSolid)); --ap-stage-top: color-mix(in srgb, var(--fork-accent) 6%, var(--fk-current-bgSolid));
  background: radial-gradient(90% 70% at 50% 108%, var(--ap-stage-glow), transparent 72%), linear-gradient(180deg, var(--ap-stage-top) 0%, var(--fk-current-hover, var(--fork-hover, Canvas)) 100%); }
.ap-stage-floor { position: absolute; z-index: 0; left: 8%; right: 8%; bottom: 10px; height: 18px; border-radius: 50%; --ap-floor: color-mix(in srgb, var(--fork-ink) 16%, var(--fk-current-hover)); background: radial-gradient(closest-side, var(--ap-floor), transparent); pointer-events: none; }
.ap-stage-art { position: absolute; z-index: 1; inset: 10px 10px 4px; display: flex; align-items: flex-end; justify-content: center; overflow: hidden; }
.ap-stage-art > img { display: block; max-width: 100%; max-height: 100%; object-fit: contain; pointer-events: none; user-select: none; }
.ap-stage-art[data-tall] { inset: 12px 10px 0; align-items: flex-start; }
.ap-stage-art[data-tall] > img { max-height: none; height: 156%; }
.ap-stage-art.is-avatar { align-items: center; }
.ap-stage-art.is-avatar .ap-avatar { width: 112px; height: 112px; border-radius: 22px; }
.ap-stage-mood { position: absolute; z-index: 2; top: 10px; left: 10px; display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 10px 0 8px; border-radius: 11px;
  background: color-mix(in srgb, var(--chip-color) 14%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--chip-color) var(--fk-current-chipInk, 62%), var(--fk-current-fg, var(--fork-ink))); font-size: var(--fork-fs-meta); font-weight: 600; }
.ap-stage-mood::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--chip-color); }
.ap-stage-form { position: absolute; z-index: 2; top: 10px; right: 10px; height: 20px; padding: 0 8px; border-radius: 6px; background: var(--fk-current-bgSolid, Canvas);
  color: var(--fork-ink-2); font-size: 10.5px; font-weight: 600; line-height: 20px; letter-spacing: .06em; }
.ap-stage-card.is-empty { height: 156px; }
.ap-stage-empty { position: absolute; z-index: 1; inset: 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; align-content: center; gap: 8px; padding: 12px; }
.ap-ui .ap-stage-empty > button:not(.ap-icon-button) { background: var(--fork-surface, Canvas); }
.ap-stage-empty .ap-glyph { width: 14px; height: 14px; margin-right: 2px; }
/* Live2D card preview (live2d-preview.js), no flash: the canvas fills the card, hidden until its first frame is
   drawn, then fades in over the model's remembered first frame (or the bare card floor). With no remembered frame and a
   load longer than 150 ms (the timer is in the component, so cached loads never flash it), a small busy ring in the
   DSH toolbar language (accent comet over a faint track, surface tokens) sits centred in the card, fades in, and fades
   out as the model fades in. The static fallback picture only when the model cannot load. */
/* optional runtime entry (cubism-core.js ForkRuntimeEntry) — name (?) state, then one
   row per missing/present piece (name · 未安装 · official page ↗ | ✓ 已安装) and one quiet accent 「同意许可并导入…」.
   No box, no grey paragraph (R2, R3); licence pages are links inside the (?) body. */
.fork-runtime { display: grid; gap: 2px; min-width: 0; color: var(--fork-ink); font: 400 var(--fork-fs-body)/1.6 var(--fork-font-ui); }
.fork-runtime:focus { outline: none; }
.fork-runtime-list { display: grid; gap: 12px; min-width: 0; }
.fork-runtime-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 30px; }
.fork-runtime-head strong { font-weight: 600; }
.fork-runtime-state { color: var(--fork-ink-3); font-size: var(--fork-fs-meta); }
.fork-runtime-head .fork-runtime-state { margin-left: auto; }
.fork-runtime[data-state=installed] .fork-runtime-state, .fork-runtime-piece[data-installed] .fork-runtime-state { color: var(--fork-ink-2); }
.fork-runtime-pieces { display: grid; grid-template-columns: minmax(0, max-content) minmax(0, 1fr); column-gap: 16px; margin: 0; padding: 0; list-style: none; }
.fork-runtime-piece { display: contents; }
.fork-runtime-name { min-height: 30px; display: flex; align-items: center; overflow-wrap: anywhere; }
.fork-runtime-links { display: flex; flex-wrap: wrap; align-items: center; gap: 0 12px; min-width: 0; }
.fork-runtime-piece > .fork-runtime-state { display: flex; align-items: center; min-height: 30px; }
.fork-runtime-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 0 12px; min-width: 0; }
.fork-runtime-link, .fork-runtime-import { appearance: none; display: inline-flex; align-items: center; gap: 4px; min-height: 30px; padding: 0; border: 0; background: none; color: var(--fork-accent); font: inherit; text-align: left; text-decoration: none; cursor: pointer; overflow-wrap: anywhere; }
.fork-runtime-import { gap: 6px; }
.fork-runtime-link:hover, .fork-runtime-import:hover:not(:disabled) { text-decoration: underline; text-underline-offset: 3px; }
.fork-runtime-import:disabled { color: var(--fork-ink-2); cursor: progress; }
.fork-runtime-out { font-size: var(--fork-fs-meta); }
.fork-runtime-link:focus-visible, .fork-runtime-import:focus-visible, .fork-runtime-retry:focus-visible { outline: var(--fork-focus); outline-offset: 2px; border-radius: 4px; }
.fork-runtime-alert { color: var(--fork-warn); overflow-wrap: anywhere; }
.fork-runtime-retry { appearance: none; min-height: 30px; margin-left: 8px; padding: 0 4px; border: 0; background: none; color: var(--fork-accent); font: inherit; cursor: pointer; }
@media (max-width: 720px) { .fork-runtime-link, .fork-runtime-import, .fork-runtime-retry, .fork-runtime-name, .fork-runtime-piece > .fork-runtime-state { min-height: 36px; } }

/* ==== fork settings page ==== */
/* 设置 › DSH Tavern. A group is its heading (+ 「?」, a
   short save state at the right end) over one card; every entry of a card is a row (.dsh-tavern-settings-row, settings.js
   TavernSettingRow) — name + 「?」 left, the control right, so every control ends on the card's right edge; one hairline
   between rows; explanations only in 「?」 (R3). A row is never a card: the card rule in tavern.css stacks its children,
   which is what blew up 界面大小 / 调试视图 when they carried the card class too. Narrow: a control that no longer fits
   wraps under its name and stays right-aligned. Colours are --fork-* only (light / dark through the host aliases). */
.dsh-tavern-global-settings { gap: 28px; color: var(--fork-ink); font-size: var(--fork-fs-body); }
.dsh-tavern-global-settings .dsh-tavern-gs-group { gap: 8px; }
.dsh-tavern-global-settings .dsh-tavern-gs-head { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; min-height: 28px; padding: 0 2px; }
.dsh-tavern-global-settings .dsh-tavern-gs-head h2 { margin: 0; color: var(--fork-ink); font-size: var(--fork-fs-heading); font-weight: 600; line-height: 1.4; }
.dsh-tavern-global-settings .dsh-tavern-gs-head > .dsh-tavern-gs-notice { margin-left: auto; }
.dsh-tavern-global-settings .dsh-tavern-gs-notice { margin: 0; padding: 0 2px; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); }
.dsh-tavern-global-settings .dsh-tavern-gs-notice.is-alert { color: var(--fork-warn); }
.dsh-tavern-global-settings .dsh-tavern-global-defaults { gap: 8px; }
.dsh-tavern-global-settings :is(.dsh-tavern-gs-card, .dsh-local-section) { padding: 2px 16px; border-color: var(--fork-hairline); border-radius: var(--fork-radius-lg); }
.dsh-tavern-global-settings :is(.dsh-local-section > h3, .dsh-tavern-gs-subhead) { display: flex; align-items: center; gap: 4px; margin: 0; padding: 12px 0 2px; color: var(--fork-ink-2); font-size: var(--fork-fs-body); font-weight: 500; line-height: 1.5; }
.dsh-tavern-global-settings .dsh-tavern-settings-row { display: flex; flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 24px; min-height: 44px; margin: 0; padding: 6px 0; box-sizing: border-box; cursor: default; }
/* One hairline above every row but the first of its card (slot rows sit in a display: contents wrapper, so no `+`). */
.dsh-tavern-global-settings :is(.dsh-tavern-gs-card, .dsh-local-section, .dsh-tavern-settings-group) .dsh-tavern-settings-row,
.dsh-tavern-global-settings .dsh-tavern-gs-card > * + .dsh-tavern-compaction-settings,
.dsh-tavern-global-settings .fork-runtime + .fork-runtime { border-top: 1px solid var(--fork-hairline); }
.dsh-tavern-global-settings :is(.dsh-tavern-gs-card, .dsh-local-section, .dsh-tavern-settings-group) > .dsh-tavern-settings-row:first-child,
.dsh-tavern-global-settings :is(.dsh-tavern-gs-card, .dsh-local-section) > :first-child:not(.dsh-tavern-settings-row) > .dsh-tavern-settings-row:first-child,
.dsh-tavern-global-settings :is(h3, .dsh-tavern-gs-subhead) + .dsh-tavern-settings-row { border-top: 0; }
.dsh-tavern-global-settings .dsh-tavern-settings-copy { flex: 1 1 10em; min-width: 0; }
.dsh-tavern-global-settings .dsh-tavern-settings-title { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 2px 4px; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 400; line-height: 1.5; }
.dsh-tavern-global-settings .dsh-tavern-settings-title > label { cursor: inherit; }
.dsh-tavern-global-settings .dsh-tavern-settings-control { display: flex; flex: 0 1 auto; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 4px 8px; min-width: 0; max-width: 100%; margin-left: auto; }
.dsh-tavern-global-settings .dsh-tavern-settings-control > .fork-inline-field { min-width: 0; max-width: 100%; min-height: 32px; }
.dsh-tavern-global-settings .dsh-tavern-settings-control > .fork-inline-field > .fork-inline-value { justify-content: flex-end; }
.dsh-tavern-global-settings .dsh-tavern-settings-control .fork-inline-trigger { max-width: 100%; }
.dsh-tavern-global-settings .dsh-tavern-settings-control .fork-inline-text { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dsh-tavern-global-settings .dsh-tavern-settings-note { color: var(--fork-ink-3); font-size: var(--fork-fs-meta); overflow-wrap: anywhere; }
.dsh-tavern-global-settings .dsh-tavern-settings-note:is([role=alert], [data-tone=warn]) { color: var(--fork-warn); }
/* A bare text box in a row's control (本地语音引擎's paths): the inline-edit look (fork-edit) at a fixed column width. */
.dsh-tavern-global-settings .dsh-tavern-settings-control > input.fork-edit { box-sizing: border-box; width: min(26em, 100%); min-width: 0; height: 30px; margin: 0; padding-left: 6px; color: var(--fork-ink); font: inherit; font-size: var(--fork-fs-body); }

/* ==== fork model image input ==== */
/* 设置 › 模型 › a pi-ai provider card — 「能看图 (?)」 over one row per listed
   model (name left, Switch right, one hairline between rows), the same row grammar as 设置 › DSH Tavern
   (modules/model-image-input.js). Sits inside the upstream card, so it draws no card or border of its own. */
.fork-model-image { display: flex; flex-direction: column; margin: 8px 0 0; color: var(--fork-ink); font-size: var(--fork-fs-body); }
.fork-model-image.is-loading { min-height: 28px; justify-content: center; }
.fork-model-image-head { display: flex; align-items: center; gap: 4px; min-height: 28px; color: var(--fork-ink-2); font-weight: 500; line-height: 1.5; }
.fork-model-image-row { display: flex; align-items: center; justify-content: space-between; gap: 4px 24px; min-height: 36px; border-top: 1px solid var(--fork-hairline); }
.fork-model-image-head + .fork-model-image-row { border-top: 0; }
.fork-model-image-name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fork-model-image-alert { margin: 4px 0 0; color: var(--fork-warn); font-size: var(--fork-fs-meta); overflow-wrap: anywhere; }
.fork-model-image-retry { appearance: none; min-height: 30px; margin-left: 8px; padding: 0 4px; border: 0; background: none; color: var(--fork-accent); font: inherit; cursor: pointer; }
.fork-model-image-retry:focus-visible { outline: var(--fork-focus); outline-offset: 2px; }
@media (max-width: 720px) { .fork-model-image-row { min-height: 44px; } .fork-model-image-retry { min-height: 36px; } }
.dsh-tavern-global-settings .dsh-tavern-settings-control > input.fork-edit[type=number] { appearance: textfield; }
.dsh-tavern-global-settings .dsh-tavern-settings-control > input.fork-edit[type=number]::-webkit-inner-spin-button,
.dsh-tavern-global-settings .dsh-tavern-settings-control > input.fork-edit[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
@container (max-width: 520px) {
  .dsh-tavern-global-settings .dsh-tavern-settings-control:has(> input.fork-edit) { flex: 1 1 100%; justify-content: flex-start; }
  .dsh-tavern-global-settings .dsh-tavern-settings-control > input.fork-edit { width: calc(100% + 6px); margin-left: -6px; }
}
.dsh-tavern-global-settings .dsh-tavern-settings-copy > .dtts-line-main { min-height: 32px; }
.dsh-tavern-global-settings .dsh-tavern-settings-actions:last-child { padding-bottom: 10px; }
/* 场景生图: its card is the page's one .dsh-tavern-settings-group; headings carry their 「?」 inline. */
.dsh-tavern-global-settings :is(.dsh-tavern-image-settings-title, .dsh-tavern-image-section > h4, .dsh-tavern-image-section > summary) .fork-help-tip { margin-left: 4px; vertical-align: middle; }
.dsh-tavern-global-settings .dsh-tavern-compaction-settings { display: flex; flex-direction: column; gap: 0; padding: 0 0 10px; }
.dsh-tavern-global-settings .dsh-tavern-settings-actions { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 4px 12px; padding-top: 6px; }
.dsh-tavern-global-settings .dsh-tavern-gs-card > .fork-runtime-list { gap: 0; padding: 4px 0; }
.dsh-tavern-global-settings .fork-runtime { padding: 6px 0; }
.dsh-tavern-global-settings .fork-runtime-head strong { font-weight: 400; }
.dsh-tavern-settings-loading { display: flex; justify-content: center; padding: 12px 0; }
.dsh-tavern-settings-alert { margin: 8px 0; color: var(--fork-warn); overflow-wrap: anywhere; }
.dsh-tavern-text-btn { appearance: none; min-height: 30px; padding: 0 4px; border: 0; background: none; color: var(--fork-accent); font: inherit; cursor: pointer; }
.dsh-tavern-text-btn:focus-visible { outline: var(--fork-focus); outline-offset: 2px; border-radius: 4px; }
@media (max-width: 720px) { .dsh-tavern-global-settings .dsh-tavern-settings-control > .fork-inline-field { min-height: 36px; } }
/* ==== end fork settings page ==== */
/* (?) bodies that hold links (HelpTip interactive): they take the pointer; links read as links. */
.fork-popover.fork-help-tip-body.is-interactive { pointer-events: auto; }
.fork-help-tip-body a { color: var(--fork-accent); text-decoration: underline; text-underline-offset: 2px; }
.fork-help-tip-body a:focus-visible { outline: var(--fork-focus); outline-offset: 1px; border-radius: 2px; }.ap-model-runtime { min-width: 0; }
.fork-live2d-preview[data-status=missing] { overflow: auto; cursor: auto; touch-action: auto; }
.fork-live2d-preview > .fork-runtime { position: relative; z-index: 2; padding: 16px; }
.fork-live2d-preview[data-status=missing] .fork-live2d-preview-fallback { position: relative; }
.fork-live2d-preview { position: absolute; z-index: 1; inset: 0; }
.fork-live2d-preview-canvas { position: absolute; inset: 0; }
.fork-live2d-preview-canvas[data-reveal=hidden] { visibility: hidden; }
.fork-live2d-preview-canvas[data-reveal=in] { animation: fork-media-in .24s ease-out; }
.fork-live2d-preview-canvas > canvas { display: block; width: 100% !important; height: 100% !important; }
.fork-live2d-preview-fallback { position: absolute; inset: 0; overflow: hidden; }
.fork-live2d-preview-still { position: absolute; top: 0; left: 50%; max-width: none; transform: translateX(-50%); pointer-events: none; user-select: none; }
.fork-live2d-preview-wait { --fork-spinner-max: 44px; }
/* Pack images (thumbnails, avatars, sprites, face snapshots): kept hidden at their reserved size until decoded, then
   faded in once; an image already decoded when mounted shows at once (data-ap-media=shown). */
[data-ap-media=loading] img, img[data-ap-media=loading] { visibility: hidden; }
[data-ap-media=in] img, img[data-ap-media=in] { animation: fork-media-in .2s ease-out; }
@keyframes fork-media-in { from { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { [data-ap-media=in] img, img[data-ap-media=in], .fork-live2d-preview-canvas[data-reveal=in] { animation: none; } }
.ap-figure-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; margin: 8px 0 0; }
.ap-outfit-chips { display: flex; flex-wrap: wrap; gap: 6px; min-width: 0; }
.ap-ui button.ap-outfit-chip { gap: 5px; min-height: 0; height: 26px; padding: 0 11px 0 9px; border-radius: 13px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-outfit-chip .ap-glyph { width: 13px; height: 13px; }
.ap-ui button.ap-outfit-chip[aria-checked=true] { border-color: transparent; background: var(--fork-accent-soft, var(--fork-hover)); color: var(--fork-accent); font-weight: 600; }
.ap-tool-group { display: inline-flex; flex-wrap: wrap; gap: 1px; margin-left: auto; padding: 2px; border-radius: 10px; background: var(--fork-hover); }
.ap-ui .ap-tool-group > button.ap-icon-button, .ap-ui .ap-tool-group > label.ap-icon-button { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px; min-height: 0; padding: 0; border: 0; border-radius: 8px; background: none; color: var(--fork-ink-2); }
.ap-ui .ap-tool-group > button.ap-icon-button:hover:not(:disabled), .ap-ui .ap-tool-group > label.ap-icon-button:hover { background: var(--fork-surface, Canvas); color: var(--fork-ink); }
.ap-tool-group > label.ap-icon-button:focus-within { outline: 2px solid var(--fork-accent); outline-offset: -1px; }
.ap-tool-group .ap-glyph { width: 16px; height: 16px; }
.ap-figure-meta-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin: 12px 0 2px; }
.ap-figure-avatar .ap-avatar { width: 36px; height: 36px; border-radius: 9px; }
