.ap-emotion-add { display: grid !important; place-items: center; background: none !important; color: var(--ap-ink-3); box-shadow: inset 0 0 0 1px var(--ap-border-strong) !important; }
.ap-emotion-add .ap-glyph { width: 15px; height: 15px; }
