.ap-prompt-section > .ap-section-head > h3 > .ap-section-meta { white-space: nowrap; }
.ap-prompt-row-head > .ap-prompt-tokens { grid-area: tokens; justify-self: start; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); font-weight: 400; letter-spacing: 0; font-variant-numeric: tabular-nums; white-space: nowrap; }
.ap-prompt-row-head > .ap-prompt-owner { grid-area: scope; justify-self: end; max-width: 240px; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); text-align: right; text-overflow: ellipsis; white-space: nowrap; }
.ap-prompt-stage-title { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 0 8px; min-width: 0; }
/* the stage heads (正文模型 / 导演 / 判断模型) are second-level headings under
   the 提示词 section title — ui-design §2.6 二级 (heading size, 500, ink-2), never bigger or bolder than their parent; rows
   are plain body text like 开场设置's. More room above a group than below it. */
.ap-prompt-stage-head { margin: 22px 0 2px; color: var(--fork-ink-2); font-size: var(--fork-fs-body); font-weight: 500; }
.ap-prompt-stage:first-child .ap-prompt-stage-head { margin-top: 14px; }
.ap-prompt-stage-head .ap-help-anchor, .ap-prompt-stage-head .fork-help-tip { margin-left: 0; }
.ap-prompt-rows { margin: 0; padding: 0; list-style: none; }
.ap-prompt-row + .ap-prompt-row { border-top: 1px dashed var(--ap-border); }
.ap-prompt-row-head { row-gap: 0; min-height: 36px; padding: 2px 0; }
.ap-ui button.ap-prompt-toggle { display: inline-flex; justify-content: flex-start; align-items: center; gap: 8px; min-width: 0; min-height: 32px; height: auto; margin-left: -4px; padding: 2px 4px; border: 0; border-radius: 6px; background: none; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 400; text-align: left; white-space: normal; }
/* the whole row head is the click target with one hover tint; the chevron
   button stays the only Tab stop and its focus ring is drawn around the whole head. */
.ap-prompt-row-head { margin: 0 -6px; padding: 2px 6px; border-radius: 6px; cursor: pointer; }
.ap-prompt-lead { cursor: inherit; }
@media (hover: hover) { .ap-prompt-row-head:hover { background: var(--fork-hover); } }
.ap-ui button.ap-prompt-toggle:hover:not(:disabled), .ap-ui button.ap-prompt-toggle:focus-visible { background: none; outline: none; }
.ap-prompt-row-head:has(.ap-prompt-toggle:focus-visible) { outline: var(--fork-focus); outline-offset: 0; }
.ap-prompt-toggle .ap-glyph { flex: none; width: 14px; height: 14px; color: var(--fork-ink-3); transition: transform .15s; }
.ap-prompt-toggle[aria-expanded=true] .ap-glyph { transform: rotate(90deg); }
.ap-prompt-name { min-width: 0; overflow-wrap: anywhere; }
.ap-prompt-note { min-width: 0; margin-left: 6px; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 400; text-overflow: ellipsis; white-space: nowrap; }
.ap-prompt-owner { color: var(--fork-ink-2); }
/* the actions are quiet icons only (pencil, reset), right after the row name. */
.ap-prompt-actions { display: inline-flex; flex: none; align-items: center; gap: 0; white-space: nowrap; }
.ap-ui .ap-prompt-actions > button.ap-icon-button { width: 28px; height: 28px; color: var(--fork-ink-3); }
.ap-ui .ap-prompt-actions > button.ap-icon-button:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui .ap-prompt-actions > button.ap-icon-button:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 1px; }
.ap-prompt-actions .ap-glyph { width: 15px; height: 15px; }
/* 素材清单 opened: one region per kind on a soft tint (the only surface: entries inside are lines, not boxes). The
   head is the kind, its count, its packs, its tokens and the quiet 「›」; entries are the verbatim text, one line each
   until opened. */
.ap-prompt-groups { display: grid; gap: 10px; }
.ap-prompt-group { min-width: 0; padding: 8px 12px 6px; border-radius: 10px; background: var(--fork-hover); }
.ap-prompt-group-head { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 12px; min-height: 28px; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-prompt-group-name { color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-prompt-group-count { margin-left: -6px; color: var(--fork-ink-2); }
.ap-prompt-group-head .ap-prompt-owner { min-width: 0; max-width: 18em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-ui .ap-prompt-group-head button.ap-kind-jump, .ap-prompt-group-head .ap-kind-jump-anchor { margin: 0 -4px 0 auto; }
.ap-prompt-raw-list { display: grid; margin: 2px 0 0; padding: 0; list-style: none; }
.ap-prompt-raw-list > li { display: grid; gap: 2px; min-width: 0; padding: 5px 0; }
.ap-prompt-raw-list > li + li { border-top: 1px dashed var(--ap-border); }
.ap-prompt-raw-label { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-prompt-raw, .ap-ui button.ap-prompt-raw { display: block; width: 100%; min-width: 0; min-height: 0; height: auto; margin: 0; padding: 0; border: 0; border-radius: 4px; background: none; color: var(--fork-ink); text-align: left; overflow-wrap: anywhere; white-space: pre-wrap; font: 11.5px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
.ap-ui button.ap-prompt-raw { cursor: pointer; }
.ap-ui button.ap-prompt-raw:hover:not(:disabled) { background: none; color: var(--fork-ink); }
.ap-ui button.ap-prompt-raw:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 2px; }
.ap-prompt-raw > code { font: inherit; }
.ap-prompt-raw.is-long[aria-expanded=false] > code { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-prompt-raw.is-long[aria-expanded=true] { max-height: 50vh; overflow: auto; }
.ap-prompt-body { display: grid; gap: 12px; padding: 2px 0 12px 22px; }
.ap-prompt-piece-head { display: flex; flex-wrap: wrap; gap: 2px 12px; margin-bottom: 4px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-prompt-piece-head .ap-prompt-owner, .ap-prompt-piece-head .ap-prompt-tokens { color: var(--fork-ink-3); font-variant-numeric: tabular-nums; }
.ap-prompt-piece pre { max-height: 50vh; margin: 0; padding: 10px 12px; overflow: auto; border-radius: 8px; background: var(--fork-hover); color: var(--fork-ink); white-space: pre-wrap; overflow-wrap: anywhere; font: 11.5px/1.6 var(--dsw-font-mono, ui-monospace, monospace); }
/* where a piece goes (system / 用户消息 / 工具) as a quiet tag; the op
   schemas one op per line; 结构与分隔 outlines show the other rows as ⟨name⟩ and a new line as ↵. */
.ap-prompt-at { padding: 0 6px; border-radius: 4px; box-shadow: inset 0 0 0 1px var(--ap-border); color: var(--fork-ink-3); font: 11px/18px var(--dsw-font-mono, ui-monospace, monospace); }
.ap-prompt-raw-label .ap-prompt-at { margin-right: 2px; }
/* the place tag (系统 / 本轮消息 / 工具) in words, its (?) right after it. */
.ap-prompt-at-tag { display: inline-flex; align-items: center; gap: 0; white-space: nowrap; }
.ap-prompt-at-tag > .ap-prompt-at { font-family: inherit; }
/* 指令参数格式 / 工具定义 as a reference — the 素材清单 group boxes, one
   per command group; in each, a command per row: its name in words, its command name (mono, muted) and (?) on the left,
   its parameters on the right as 「name (?)  what to give」 with the options as chips and a quiet 可不填 tag. One column
   in a narrow pane. 「查看原文」 sits at the end of the header line it switches. */
.ap-prompt-head-end { display: inline-flex; align-items: center; margin-left: auto; }
.ap-ui button.ap-schema-toggle { min-height: 28px; height: auto; padding: 0 8px; border: 0; border-radius: 6px; background: none; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); font-weight: 400; white-space: nowrap; }
.ap-ui button.ap-schema-toggle[aria-pressed=true] { color: var(--fork-accent); }
.ap-ui button.ap-schema-toggle:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui button.ap-schema-toggle:focus-visible { outline: var(--fork-focus); outline-offset: 1px; }
.ap-prompt-piece-head { align-items: center; }
/* 指令参数格式 / 工具定义 / 剧情 state rows — one row per target (mono, left),
   one line per verb (mono, 600) carrying its arguments: an asset chip (accent-soft, a button opening this turn's options),
   a value set as one segmented chip, a value / range / length chip, `name:` before a value only where needed; optional
   arguments in one dashed 「可选」 box, alternatives joined by 「或」. One column in a narrow pane. */
.ap-cmd-rows { display: grid; margin: 2px 0 0; padding: 0; list-style: none; }
.ap-cmd-row { display: grid; grid-template-columns: minmax(6em, 9em) minmax(0, 1fr); align-items: start; gap: 2px 12px; min-width: 0; padding: 6px 0; }
.ap-cmd-row + .ap-cmd-row { border-top: 1px dashed var(--ap-border); }
.ap-cmd-target { color: var(--fork-ink); font-family: var(--dsw-font-mono, ui-monospace, monospace); font-size: var(--fork-fs-meta); font-weight: 600; line-height: 26px; overflow-wrap: anywhere; }
.ap-cmd-lines { display: grid; gap: 3px; min-width: 0; }
.ap-cmd-line { display: grid; grid-template-columns: minmax(4.8em, max-content) minmax(0, 1fr); align-items: start; column-gap: 8px; min-width: 0; }
.ap-cmd-line.is-bare { grid-template-columns: minmax(0, 1fr); }
.ap-cmd-verb { color: var(--fork-ink); font-family: var(--dsw-font-mono, ui-monospace, monospace); font-size: var(--fork-fs-meta); font-weight: 600; line-height: 24px; overflow-wrap: anywhere; cursor: help; }
.ap-cmd-verb.is-name { font-family: inherit; font-weight: 500; cursor: default; }
.ap-cmd-args { display: flex; flex-wrap: wrap; align-items: center; gap: 3px 10px; min-width: 0; min-height: 24px; }
.ap-cmd-arg { display: inline-flex; align-items: center; gap: 3px; min-width: 0; max-width: 100%; }
.ap-cmd-arg > * { flex: none; }
.ap-cmd-arg > .ap-cmd-set { flex: 0 1 auto; }
.ap-cmd-key { color: var(--fork-ink-2); font-family: var(--dsw-font-mono, ui-monospace, monospace); font-size: var(--fork-fs-meta); line-height: 20px; }
.ap-cmd-key::after { content: ":"; }
.ap-cmd-asset, .ap-ui button.ap-cmd-asset { position: relative; display: inline-block; min-width: 0; min-height: 0; height: auto; max-width: 100%; margin: 0; padding: 0 7px; border: 0; border-radius: 5px; background: var(--fork-accent-soft); color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 400; line-height: 20px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* The chip stays 20px tall; its touch target is 32px (36px on touch screens) without moving the line. */
.ap-ui button.ap-cmd-asset { overflow: visible; cursor: pointer; }
.ap-ui button.ap-cmd-asset::before { content: ""; position: absolute; inset: -6px -2px; }
@media (pointer: coarse) { .ap-ui button.ap-cmd-asset::before { inset: -8px -2px; } }
.ap-ui button.ap-cmd-asset:hover:not(:disabled), .ap-ui button.ap-cmd-asset[aria-expanded=true] { background: var(--fork-accent-soft); color: var(--fork-ink); box-shadow: inset 0 0 0 1px var(--fork-accent); }
.ap-ui button.ap-cmd-asset:focus-visible { outline: var(--fork-focus); outline-offset: 1px; }
.ap-cmd-asset-anchor { display: inline-flex; min-width: 0; max-width: 100%; }
.ap-cmd-choice { min-height: 28px; cursor: default; }
.ap-cmd-choice.is-empty { color: var(--fork-ink-3); }
.ap-cmd-set { display: inline-flex; flex-wrap: wrap; align-items: center; min-width: 0; max-width: 100%; padding: 0 2px; border-radius: 5px; background: var(--fork-surface); font-size: var(--fork-fs-meta); line-height: 20px; }
.ap-cmd-set > span { padding: 0 5px; color: var(--fork-ink); font-family: var(--dsw-font-mono, ui-monospace, monospace); }
