/* Title-safe area: the top chrome steps in from the darkened tube edge and corners (the runtime notices follow). */
.fork-gal-stage[data-theme="crt"]:not([data-fk-skin]) .fork-gal-topbar { padding: 16px 22px 10px 26px; }
.fork-gal-stage[data-theme="crt"]:not([data-fk-skin]) .fork-gal-notices { right: 22px; }
