  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--crt-phos) 22%, transparent), inset 0 0 44px 8px rgb(0 0 0 / .6),
    0 0 28px color-mix(in srgb, var(--crt-phos) 11%, transparent), 0 18px 44px rgb(0 0 0 / .5);
