.fork-gal-stage[data-theme="crt"] .fork-gal-frame :is(.bow, .spark) { display: none; }
.fork-gal-stage[data-theme="crt"] .fork-gal-frame :is(.tl, .br, .sweep) { visibility: hidden; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-frame :is(.tl, .br) {
