.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-frame .tl { top: 0; bottom: auto; transform-origin: 50% 0; border-radius: 22px 22px 0 0 / 28px 28px 0 0; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-frame .br { top: auto; bottom: 0; transform-origin: 50% 100%; border-radius: 0 0 22px 22px / 0 0 28px 28px; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-frame .sweep {
  top: calc(50% - 1px); left: 4%; right: 4%; z-index: 6; height: 2px; overflow: visible; border-radius: 2px;
  background: var(--crt-hot); box-shadow: 0 0 6px 1px var(--crt-phos), 0 0 18px 4px var(--crt-glow);
}
.fork-gal-stage[data-theme="crt"] .fork-gal-frame .sweep::after { content: none; animation: none; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box:not(.is-hidden) .fork-gal-frame :is(.tl, .br) { animation: fork-gal-crt-shutter .62s cubic-bezier(.3, 0, .2, 1) both; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box:not(.is-hidden) .fork-gal-frame .sweep { animation: fork-gal-crt-beam .62s ease-out both; }
