@keyframes fork-gal-crt-beam { 0% { visibility: visible; transform: scaleX(.01); } 30% { transform: scaleX(1); } 42% { transform: scaleX(1) scaleY(1.6); } 60% { visibility: visible; transform: scaleX(1) scaleY(0); } 61%, 100% { visibility: hidden; transform: scaleX(1) scaleY(0); } }
/* Power-off (H / right click): the picture collapses to a line, then to a dot. Only the hide animates the box itself. */
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box.is-hidden { transform: translateX(-50%); transform-origin: 50% 50%; animation: fork-gal-crt-off .3s cubic-bezier(.5, 0, .9, .5) both; transition: visibility 0s .3s; }
@keyframes fork-gal-crt-off { 0% { scale: 1 1; filter: none; } 55% { scale: 1 .012; filter: brightness(2.2); } 100% { scale: 0 .012; filter: brightness(2.2); } }
/* The speaker as an on-screen-display line: a block prompt in a light tint of the speaker colour, monospace Latin
   over the stage font, a one-pixel RGB split on the name only (never on body text). */
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-name {
  top: calc(var(--box-pad) * .6); gap: .55em; padding: 0; transform: none; clip-path: none; border-radius: 0; background: none; box-shadow: none; filter: none;
  --figure-ink: auto; color: color-mix(in srgb, var(--bubble-color) 26%, #8dffb0); font: 600 clamp(13px, 1.02vw, 16px)/1.4 var(--crt-mono), var(--gal-ui-font); letter-spacing: .14em;
}
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-name b { font-weight: inherit; text-shadow: -1px 0 rgb(255 70 120 / .42), 1px 0 rgb(70 190 255 / .42), 0 0 10px var(--crt-glow); }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-name-gem { width: .5em; height: 1.05em; clip-path: none; background: currentColor; box-shadow: 0 0 8px var(--crt-glow); }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-name span { padding: 0 .5em; border: 1px solid color-mix(in srgb, currentColor 45%, transparent); border-radius: 2px; background: none; color: var(--gal-box-ink-2); font: 500 11px/1.5 var(--crt-mono), var(--gal-ui-font); letter-spacing: .06em; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-name .fork-gal-voice { width: 24px; height: 24px; margin: -2px 0; border-radius: 4px; }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box .fork-gal-name .fork-gal-voice[data-state="playing"] { color: var(--crt-phos); }
/* Body text: pale phosphor with one soft bloom; narration and thoughts step down in brightness, all >= 9:1. */
