.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box.is-narration .fork-gal-text { color: var(--crt-narration); }
.fork-gal-stage[data-theme="crt"]:not(.is-film):not([data-fk-skin]) .fork-gal-box.is-thought .fork-gal-text { color: var(--crt-thought); }
