.fork-gal-stage[data-theme][data-fk-skin]:not(.is-film) .fork-gal-box::before { content: none; }
.fork-gal-stage[data-theme][data-fk-skin]:not(.is-film) .fork-gal-box .fork-gal-text {
  color: var(--gal-skin-fg); font-family: var(--gal-skin-font-body); font-weight: var(--gal-skin-weight);
