.fork-gal-stage[data-theme][data-fk-skin]:not(.is-film) .fork-gal-box .fork-gal-name {
  display: inline-flex; width: fit-content; max-width: calc(100% - 2em); padding: .15em .65em; margin-bottom: 8px;
  opacity: 1; filter: none; clip-path: none; transform-origin: left bottom;
  background: var(--gal-skin-name-bg); color: var(--gal-skin-name-fg); font-family: var(--gal-skin-font-name); --figure-ink: none;
  border-radius: var(--gal-skin-name-radius); rotate: var(--gal-skin-name-rotate); text-shadow: none;
}
/* no quick-menu plate; icons take the skin's own ink (idle) and accent (hover/on). */
.fork-gal-stage[data-fk-skin]:not(.is-film) .fork-gal-controls { background: none; color: var(--gal-skin-qm-idle); font-family: var(--gal-skin-font-ui,var(--gal-skin-font-body));
  --gal-control-idle: var(--gal-skin-qm-idle); --gal-control-on: var(--gal-skin-qm-on); --gal-qm-hover: var(--gal-skin-qm-hover); --gal-qm-active: var(--gal-skin-qm-active); --gal-qm-active-ink: var(--gal-skin-qm-on); }
.fork-gal-stage[data-fk-skin]:not(.is-film) .fork-gal-frame { display: none; }
.fork-gal-stage[data-theme][data-fk-skin]:not(.is-film) .fork-gal-box {
  --gal-skin-top: max(var(--cl-pad-top,calc(var(--box-pad) + 10px)),var(--gal-skin-pad-top));
  --gal-skin-bottom: max(var(--cl-pad-bottom,34px),var(--gal-skin-pad-bottom));
  --gal-box-normal-height: calc(var(--gal-skin-top) + var(--gal-skin-bottom) + var(--gal-skin-name-space,0px) + var(--cl-fs,clamp(16px,1.45vw,21px)) * var(--gal-skin-line-height) * 3 + var(--gal-skin-border-width) * 2);
  padding-top: var(--gal-skin-top); padding-bottom: var(--gal-skin-bottom);
