}
.fork-gal-stage[data-theme="classic"][data-fk-skin] .fork-gal-box { --gal-skin-name-space: calc(var(--cl-name) * 1.8 + 8px); }
.fork-skin-frame { position: absolute; inset: 0; pointer-events: none; overflow: clip; border-radius: inherit; }
.fork-skin-frame > i { position: absolute; display: block; }
.fork-skin-corner { position: absolute; width: 32px; height: 32px; }
.fork-skin-corner.tl { left: 2px; top: 2px; } .fork-skin-corner.tr { right: 2px; top: 2px; }
.fork-skin-corner.br { right: 2px; bottom: 2px; } .fork-skin-corner.bl { left: 2px; bottom: 2px; }
/* The skin cursor is a transparent cut-out: out-rank the classic narration triangle paint (#e4e0ea), which otherwise
   showed as a light square once the skin cleared its clip-path. */
.fork-gal-stage[data-theme][data-fk-skin]:not(.is-film) .fork-gal-box .fork-gal-text > .fork-gal-next.fork-skin-next { width: 20px; height: 20px; margin-right: calc(-20px - .45em); clip-path: none; background: none; box-shadow: none; animation: none; }
.fork-skin-next canvas { display: block; width: 20px; height: 20px; }
/* Paint a transformed copy without turning the layout glyph into an inline-block.
   The original glyph and .fork-gal-type-rest keep the pre-laid-out line advances.
   cut-out glyph hops on twos (GalTypewriter hop clock). data-hop is the glyph's
   age in 12/s steps: 0 = the entry pose, 1 = the landing pose, then it joins the plain shown run. Poses are held
   flat and opaque like paper cut-outs (no transition, no CSS timer, no translucency) and stay inside the glyph's own cell: overflow: clip keeps the scrolling
   textbox's overflow unchanged, so poses are sized to read inside it rather than being cropped. The copy resets
   the inherited text-indent: classic dialogue hangs its opening quote with text-indent -1em, which shifted every
   copy out of its clip box, so spoken lines showed nothing until each glyph settled. */
.fork-gal-type[data-skin-reveal] .fork-gal-glyph { color: transparent; animation: none; }
.fork-skin-glyph-paint { position: absolute; inset: 0; overflow: clip; pointer-events: none; }
.fork-gal-type[data-skin-reveal] .fork-skin-glyph-paint::after { content: attr(data-glyph); position: absolute; left: 0; top: 0; color: var(--gal-skin-fg); white-space: pre; text-indent: 0; pointer-events: none; transform-origin: 50% 60%; }
/* OS reduced motion (calm) keeps the stepped reveal but drops the per-glyph poses. */
@media (prefers-reduced-motion: no-preference) {
  .fork-gal-type[data-skin-reveal="ink"] .fork-skin-glyph-paint[data-hop="0"]::after { filter: blur(.7px); transform: scale(1.1); color: var(--gal-skin-flash); }
  .fork-gal-type[data-skin-reveal="ink"] .fork-skin-glyph-paint[data-hop="1"]::after { filter: blur(.25px); transform: scale(1.03); }
  .fork-gal-type[data-skin-reveal="pop"] .fork-skin-glyph-paint[data-hop="0"]::after { transform: translateY(-.1em) scale(1.12) rotate(-4deg); color: var(--gal-skin-flash); }
  .fork-gal-type[data-skin-reveal="pop"] .fork-skin-glyph-paint[data-hop="1"]::after { transform: translateY(.04em) scale(.95) rotate(2deg); }
  .fork-gal-type[data-skin-reveal="stutter"] .fork-skin-glyph-paint[data-hop="0"]::after { color: var(--gal-skin-flash); }
  .fork-gal-type[data-skin-reveal="stamp"] .fork-skin-glyph-paint[data-hop="0"]::after { transform: translateY(calc(var(--gal-skin-stamp-y) * .25)) scale(1.1); }
  .fork-gal-type[data-skin-reveal="stamp"] .fork-skin-glyph-paint[data-hop="1"]::after { transform: translateY(calc(var(--gal-skin-stamp-y) * -.05)); }
  .fork-gal-type[data-skin-reveal="cut"] .fork-skin-glyph-paint[data-hop="0"]::after { transform: rotate(-9deg) translate(-.04em,-.06em); color: var(--gal-skin-flash); }
  .fork-gal-type[data-skin-reveal="cut"] .fork-skin-glyph-paint[data-hop="1"]::after { transform: rotate(3deg); }
  .fork-gal-type[data-skin-reveal="scan"] .fork-skin-glyph-paint[data-hop="0"]::after { transform: scaleY(.3); color: var(--gal-skin-flash); }
  .fork-gal-type[data-skin-reveal="scan"] .fork-skin-glyph-paint[data-hop="1"]::after { transform: scaleY(1.1); }
  .fork-gal-type[data-skin-reveal="scrawl"] .fork-skin-glyph-paint[data-hop="0"]::after { transform: skewX(-16deg) translateX(-.06em); color: var(--gal-skin-flash); }
  .fork-gal-type[data-skin-reveal="scrawl"] .fork-skin-glyph-paint[data-hop="1"]::after { transform: skewX(-5deg); }
  /* textFx.poses (skin-interface.md §18 E1): the skin's own entrance poses replace the reveal's two (stageSkinGlyphPoses
     tokens, one rule per pose index); emphasis jitter adds the glyph's seeded offset while it enters (--gj-x / --gj-y,
     the individual translate composes with any pose); emphasis none enters in the body ink, ink in the flash. */
  .fork-gal-type[data-skin-poses] .fork-skin-glyph-paint:is([data-hop="0"], [data-hop="1"], [data-hop="2"], [data-hop="3"])::after { transform: var(--gal-hop-t); filter: var(--gal-hop-f); color: var(--gal-hop-c); }
  .fork-gal-type[data-skin-poses] .fork-skin-glyph-paint[data-hop="0"] { --gal-hop-t: var(--gal-hop-0-t); --gal-hop-f: var(--gal-hop-0-f); --gal-hop-c: var(--gal-hop-0-c); }
  .fork-gal-type[data-skin-poses] .fork-skin-glyph-paint[data-hop="1"] { --gal-hop-t: var(--gal-hop-1-t); --gal-hop-f: var(--gal-hop-1-f); --gal-hop-c: var(--gal-hop-1-c); }
  .fork-gal-type[data-skin-poses] .fork-skin-glyph-paint[data-hop="2"] { --gal-hop-t: var(--gal-hop-2-t); --gal-hop-f: var(--gal-hop-2-f); --gal-hop-c: var(--gal-hop-2-c); }
  .fork-gal-type[data-skin-poses] .fork-skin-glyph-paint[data-hop="3"] { --gal-hop-t: var(--gal-hop-3-t); --gal-hop-f: var(--gal-hop-3-f); --gal-hop-c: var(--gal-hop-3-c); }
  .fork-gal-type[data-skin-poses="1"] .fork-skin-glyph-paint[data-hop="1"]::after, .fork-gal-type[data-skin-poses="2"] .fork-skin-glyph-paint[data-hop="2"]::after,
  .fork-gal-type[data-skin-poses="3"] .fork-skin-glyph-paint[data-hop="3"]::after { transform: none; filter: none; color: var(--gal-skin-fg); }
  .fork-gal-type[data-skin-emphasis="jitter"] .fork-skin-glyph-paint[style]::after { translate: var(--gj-x) var(--gj-y); }
  .fork-gal-type[data-skin-emphasis="none"] .fork-skin-glyph-paint::after { color: var(--gal-skin-fg); }
  .fork-gal-type[data-skin-emphasis="ink"]:not([data-skin-poses]) .fork-skin-glyph-paint[data-hop="0"]::after { color: var(--gal-skin-flash); }
}


/* ==== stage skin: ADV layouts ==== */
/* closed skin words, written as root attributes by applyStageSkin
   (stageSkinMarks). A skin without them gets none of these rules. Colours are the skin's own tokens only.
   Every size is in --adv-f (the stage body size, --cl-fs) so the ornaments keep the official proportions to the text at
   any reading size; the numbers are measured on the official story stills.
   - textbox.layout scrim: no box - a full-width fade from the bottom edge into the scene, one text column;
     card: a floating opaque card with a lower lip (ガルパ). Both drop the face window, the classic 【】「」
     (gal-stage.js advLayout) and the page counter (the official screens have none), keep the 3-line page.
   - nameplate ribbon (a pill over the card's top-left edge, a shooting star at its end) / underline (plain name over a
     fading rule).
   - nameplate.tint figure: the plate takes the speaker's image colour (--bubble-color, moved by
     figure-color-contrast.js until the skin's name ink reads on it).
