/* ==== end stage skin: P5 slash layout ==== */

.fork-status-tab-icon { display: inline-grid; place-items: center; flex: none; }
.fork-status-tab-spinner { --fork-spinner-size: 14px; }
.fork-status-tab-error { display: grid; place-items: center; width: 14px; height: 14px; border: 1px solid currentColor; border-radius: 50%; font: 700 11px/1 var(--fork-font-ui); color: var(--dsh-tavern-accent-error); }

/* one pack row, one state control, one shared two-column pack modal.
   State colours (owner): 全局启用 blue · 本卡使用 green · 关闭 grey. Hairlines only — no boxes inside the panel or modal. */
/* one blue, one green — the standard --fork-state-* / --fork-lamp-* tokens. */
.ap-ui { --ap-state-global: var(--fork-state-global); --ap-state-card: var(--fork-state-card); --ap-state-off: color-mix(in srgb, var(--fork-ink) 10%, transparent);
  --ap-lamp-blue: var(--fork-lamp-blue); --ap-lamp-green: var(--fork-lamp-green); }
/* State tag — the one 全局 / 本卡 / 关闭 control; it opens the styled menu.
   one size everywhere — the small text-only tag (24px, meta size, no lamp,
   no chevron); the larger lamp pill is gone. Chips size to their content; the three labels are all two characters, so the
   rows still line up by content alone. */
.ap-state-tag { display: inline-flex; align-items: center; gap: 5px; flex: none; width: max-content; min-width: max-content; height: 24px; padding: 0 10px; border-radius: 12px; white-space: nowrap; font-size: var(--fork-fs-meta); font-weight: 500; line-height: 1; }
.ap-ui button.ap-state-tag { min-height: 0; height: 24px; padding: 0 10px; border: 0; border-radius: 12px; font-size: var(--fork-fs-meta); }
.ap-state-tag > span { flex: none; min-width: max-content; }
.ap-state-tag > .fork-spinner { --fork-spinner-size: 12px; }
.ap-state-opt .ap-glyph { width: 13px; height: 13px; }
/* 关 is grey hollow — a 1px --fork-state-off ring, no fill. */
.ap-state-tag[data-state=off], .ap-ui button.ap-state-tag[data-state=off] { background: none; box-shadow: inset 0 0 0 1px var(--fork-state-off); color: color-mix(in srgb, var(--fork-ink) 78%, transparent); }
.ap-state-tag[data-state=card], .ap-ui button.ap-state-tag[data-state=card] { background: color-mix(in srgb, var(--ap-state-card) 16%, transparent); color: color-mix(in srgb, var(--ap-state-card) 80%, var(--fork-ink)); }
.ap-state-tag[data-state=global], .ap-ui button.ap-state-tag[data-state=global] { background: color-mix(in srgb, var(--ap-state-global) 16%, transparent); color: color-mix(in srgb, var(--ap-state-global) 80%, var(--fork-ink)); }
.ap-ui button.ap-state-tag[data-state=off]:hover:not(:disabled) { background: color-mix(in srgb, var(--fork-ink) 16%, transparent); }
.ap-ui button.ap-state-tag[data-state=card]:hover:not(:disabled) { background: color-mix(in srgb, var(--ap-state-card) 25%, transparent); }
.ap-ui button.ap-state-tag[data-state=global]:hover:not(:disabled) { background: color-mix(in srgb, var(--ap-state-global) 25%, transparent); }
.ap-state-anchor .ap-popover { min-width: 196px; padding: 5px; }
.ap-ui button.ap-state-opt { display: flex; align-items: center; justify-content: flex-start; gap: 10px; width: 100%; min-height: 0; height: 38px; padding: 0 10px 0 6px; border: 0; border-radius: 8px; background: none; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 500; }
.ap-ui button.ap-state-opt:hover:not(:disabled) { background: var(--fork-hover); }
.ap-state-dot { display: grid; place-items: center; flex: none; width: 24px; height: 24px; border-radius: 50%; }
.ap-state-opt[data-state=off] .ap-state-dot { background: var(--ap-state-off); color: color-mix(in srgb, var(--fork-ink) 78%, transparent); }
.ap-state-opt[data-state=card] .ap-state-dot { background: color-mix(in srgb, var(--ap-state-card) 18%, transparent); color: var(--ap-state-card); }
.ap-state-opt[data-state=global] .ap-state-dot { background: color-mix(in srgb, var(--ap-state-global) 18%, transparent); color: var(--ap-state-global); }
/* the state menu's indicator is the lamp — 全局 blue dot, 本卡 green dot, 关闭 a
   grey hollow dot. */
.ap-state-lamp { flex: none; box-sizing: border-box; width: 8px; height: 8px; border-radius: 50%; }
.ap-state-lamp[data-state=global] { background: var(--ap-lamp-blue); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ap-lamp-blue) 22%, transparent); }
.ap-state-lamp[data-state=card] { background: var(--ap-lamp-green); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ap-lamp-green) 22%, transparent); }
.ap-state-lamp[data-state=off] { background: transparent; border: 1.5px solid color-mix(in srgb, var(--fork-ink) 45%, transparent); }
.ap-state-opt .ap-state-dot { background: none; }
.ap-ui button.ap-state-opt[aria-checked=true][data-state=off] { background: color-mix(in srgb, var(--fork-ink) 6%, transparent); }
.ap-ui button.ap-state-opt[aria-checked=true][data-state=card] { background: color-mix(in srgb, var(--ap-state-card) 9%, transparent); }
.ap-ui button.ap-state-opt[aria-checked=true][data-state=global] { background: color-mix(in srgb, var(--ap-state-global) 9%, transparent); }
.ap-state-label { flex: 1; text-align: left; }
.ap-state-check { display: inline-flex; color: var(--fork-accent); }
.ap-state-opt[data-state=card] .ap-state-check { color: var(--ap-state-card); }
.ap-state-opt[data-state=global] .ap-state-check { color: var(--ap-state-global); }
.ap-avatar.is-mini { width: 20px; height: 20px; border-radius: 50%; }
.ap-pack-users .ap-avatar + .ap-avatar { margin-left: -7px; box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas); }

/* Pack rows (素材库, 舞台设置 and 管理): title · users · 「N 张卡」 · count · state. */
.ap-pack-toolbar { display: flex; align-items: center; gap: 4px; margin: 2px 0 8px; }
.ap-search { position: relative; display: flex; flex: 1; align-items: center; min-width: 0; }
.ap-search > .ap-glyph { position: absolute; left: 12px; width: 14px; height: 14px; color: var(--ap-ink-3); pointer-events: none; }
.ap-ui .ap-search > input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { width: 100%; min-height: 0; height: 32px; padding: 0 14px 0 32px; border-color: transparent; border-radius: 16px; background: var(--fork-hover); }
.ap-ui .ap-search > input { border-color: var(--fork-accent); background: var(--ap-field); }
.ap-search.is-compact { margin: 4px; }
.ap-ui .ap-search.is-compact > input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { height: 28px; font-size: var(--fork-fs-body); }
.ap-file-item input { position: absolute; inset: 0; width: 100%; opacity: 0; cursor: pointer; }
.ap-ui .ap-pack-toolbar > button.ap-icon-button { width: 32px; height: 32px; color: var(--fork-ink); }
.ap-ui .ap-pack-toolbar > button.ap-icon-button:hover:not(:disabled) { background: var(--fork-hover); }
.ap-pack-list { margin: 0; padding: 0; list-style: none; }
.ap-pack-row { display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 4px 0; border-bottom: 1px solid var(--ap-border); }
.ap-pack-list > .ap-pack-row:last-child { border-bottom: 0; }
/* the whole row opens the pack. Its hover wash and the keyboard ring (the
   name button has focus) are drawn by ::before, reaching 6px past the content so the text never touches the edge; the
   chip, 导出 and the selection check keep their own hover. No border, no box. */
.ap-pack-row.is-openable { position: relative; isolation: isolate; cursor: pointer; }
.ap-pack-row.is-openable::before { content: ""; position: absolute; inset: 0 -6px; z-index: -1; border-radius: 8px; pointer-events: none; }
.ap-pack-row.is-openable:hover:not(:has(.ap-state-anchor:hover, button:not(.ap-pack-name):hover))::before { background: var(--fork-hover); }
.ap-pack-row.is-openable:has(> .ap-pack-title > button.ap-pack-name:focus-visible)::before { outline: var(--fork-focus); outline-offset: -2px; }
.ap-ui .ap-pack-row.is-openable > .ap-pack-title > button.ap-pack-name:focus-visible { outline: none; }
.ap-ui button.ap-pack-name, .ap-pack-name.is-missing { flex: 1 1 auto; min-width: 0; min-height: 0; height: 34px; padding: 0; border: 0; border-radius: 0; background: none; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-ui button.ap-pack-name { display: block; line-height: 34px; }
.ap-ui button.ap-pack-name:hover:not(:disabled) { background: none; color: var(--fork-accent); }
.ap-pack-name.is-missing { display: inline-flex; align-items: center; gap: 6px; color: var(--dsw-alias-state-warning-primary, #d9942a); }
.ap-pack-users { display: inline-flex; flex: none; align-items: center; gap: 6px; font-size: var(--fork-fs-meta); }
.ap-pack-users > span:last-child { max-width: 12em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-pack-row.is-new { border-bottom-color: var(--fork-accent); }
.ap-ui input.ap-new-input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { flex: 1; min-width: 0; height: 34px; font-size: var(--fork-fs-body); font-weight: 600; }
.ap-ui button.ap-solid-pill { display: inline-flex; align-items: center; gap: 6px; min-height: 0; height: 30px; padding: 0 14px; border: 0; border-radius: 15px; background: var(--fork-accent-fill, var(--fork-accent)); color: var(--fork-on-accent, #fff); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-ui button.ap-solid-pill:hover:not(:disabled), .ap-ui button.ap-solid-pill[aria-expanded=true] { background: var(--fork-accent-fill, var(--fork-accent)); opacity: .9; }
.ap-ui button.ap-solid-pill:disabled { opacity: .45; }
.ap-ui button.ap-solid-pill.is-large { height: 34px; padding: 0 16px 0 12px; font-size: var(--fork-fs-body); }
.ap-solid-pill .ap-glyph { width: 14px; height: 14px; }
.ap-pack-list.is-broken { margin-top: 8px; }
.ap-pack-row.is-broken { flex-wrap: wrap; }
.ap-pack-row.is-broken .ap-alert { flex-basis: 100%; margin: 0 0 6px; }
.ap-ui button.ap-manage { min-height: 0; height: 26px; padding: 0 12px; font-size: var(--fork-fs-meta); }
.ap-ui button.ap-manage.is-done { border-color: transparent; background: var(--fork-accent-soft); color: var(--fork-accent); }
.ap-more-link { margin: 10px 0 0; font-size: var(--fork-fs-body); }
@container (max-width: 520px) {
  .ap-pack-users > span:last-child { display: none; }
}
/* the title flexes and carries the faces
   right after it; only the state sits on the right. The title takes every free pixel and ellipsizes only when the row is
   really full. Faces: 1 whole, 2 a hair apart, 3+ overlapping tighter the more there are (≤ 5); the users' names are
   the tooltip. */
.ap-pack-title { display: flex; flex: 1 1 auto; align-items: center; gap: 8px; min-width: 0; }
.ap-pack-title > .ap-pack-name, .ap-ui .ap-pack-title > button.ap-pack-name { flex: 0 1 auto; min-width: 2.5em; }
.ap-pack-title > .ap-hint-mark { flex: none; }
.ap-pack-title > .ap-pack-users { position: relative; display: inline-flex; flex: none; gap: 0; }
.ap-pack-title > .ap-pack-users > .ap-pack-user-names { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.ap-pack-users .ap-avatar.is-mini { width: 22px; height: 22px; }
.ap-ui .ap-pack-users .ap-avatar + .ap-avatar { margin-left: var(--ap-face-overlap, 2px); box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas); }
.ap-pack-users[data-count="3"] { --ap-face-overlap: -6px; }
.ap-pack-users[data-count="4"] { --ap-face-overlap: -9px; }
.ap-pack-users[data-count="5"] { --ap-face-overlap: -11px; }
/* 舞台设置 › 素材包 — what a pack holds, right after its name: faces →
   pictures → kind icons, each group a tight overlapping stack (--ap-pv-f: the share of a tile hidden under the next one,
   larger the more tiles). The strip yields width before the name does, never wraps, and fades out at its end only while
   it is clipped. Tiles are tiny WebPs (fork-asset-pack-preview-ui.js); an unready tile is a faint shape, never a letter. */
.ap-pack-title > .ap-pack-previews { display: inline-flex; flex: 0 4 auto; align-items: center; gap: 7px; min-width: 0; margin-left: -2px; padding: 2px; overflow: hidden; }
.ap-pack-previews[data-clipped] { -webkit-mask-image: linear-gradient(to right, var(--fork-ink) calc(100% - 20px), transparent); mask-image: linear-gradient(to right, var(--fork-ink) calc(100% - 20px), transparent); }
.ap-pv-group { display: inline-flex; flex: none; align-items: center; }
.ap-pv-tile { position: relative; display: block; flex: none; overflow: hidden; }
.ap-pv-tile[data-empty] { background: var(--fork-hover); }
.ap-pv-tile > img { display: block; width: 100%; height: 100%; object-fit: cover; }
.ap-pv-tile.is-face { width: 22px; height: 22px; border-radius: 50%; }
.ap-pv-tile.is-wide { width: 30px; height: 20px; border-radius: 4px; }
.ap-pv-tile.is-item { width: 20px; height: 20px; border-radius: 4px; background: var(--fork-hover); }
.ap-pv-tile.is-item > img { object-fit: contain; }
.ap-pv-tile + .ap-pv-tile { box-shadow: 0 0 0 1.5px var(--fk-current-bgSolid, Canvas); }
.ap-pv-tile.is-face + .ap-pv-tile { margin-left: calc(var(--ap-pv-f, 0) * -22px); }
.ap-pv-tile.is-wide + .ap-pv-tile { margin-left: calc(var(--ap-pv-f, 0) * -30px); }
.ap-pv-tile.is-item + .ap-pv-tile { margin-left: calc(var(--ap-pv-f, 0) * -20px); }
/* 舞台设置 › 人物 — a quiet wrapping row of avatar + name pills, the pack row's
   face size and hover; the whole pill opens the figure. */
.ap-cast-strip { display: flex; flex-wrap: wrap; gap: 4px; margin: 4px -6px 0; padding: 0; list-style: none; }
.ap-cast-strip > li { min-width: 0; max-width: 100%; }
.ap-ui button.ap-cast-pill { display: inline-flex; align-items: center; gap: 7px; max-width: 100%; height: 34px; min-height: 0; margin: 0; padding: 0 10px 0 6px; border: 0; border-radius: 8px; background: none; color: color-mix(in srgb, var(--fork-ink) 84%, transparent); font-size: var(--fork-fs-body); font-weight: 400; white-space: nowrap; }
.ap-ui button.ap-cast-pill:hover { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui button.ap-cast-pill:focus-visible { outline: var(--fork-focus); outline-offset: -2px; }
.ap-cast-pill > .ap-avatar.is-mini { flex: none; width: 24px; height: 24px; }
.ap-cast-pill > .ap-avatar.ap-figure-silhouette { background: color-mix(in srgb, var(--figure-color, var(--fork-figure-fallback)) 18%, var(--fk-current-bgSolid, Canvas)); }
.ap-cast-pill > .ap-figure-silhouette > svg { width: 60%; height: 60%; }
.ap-cast-pill-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 720px) { .ap-ui button.ap-cast-pill { height: 38px; } }
.ap-pv-group.is-icons { gap: 3px; color: var(--fork-ink-3, var(--fork-ink-2)); }
.ap-pv-icon { display: block; flex: none; width: 14px; height: 14px; }
/* The chip keeps its content width in the row (never squeezed by a long title); 本卡 / 全局 / 关闭 are the same length,
   so the right edges line up without a hard-coded width. */
.ap-ui .ap-pack-row button.ap-state-tag { flex: none; width: max-content; min-width: max-content; }
/* 「素材包」 — 管理 · 导出 · 导入 as the head's quiet pills; each row ends with
   its size (one right-aligned column, so the tags line up) and a quiet 导出 icon. Selection mode: a round house-style
   check before the title (no native input), the icon gone. */
.ap-pack-head-actions { display: inline-flex; flex-wrap: wrap; justify-content: flex-end; align-items: center; gap: 6px; }
/* rows have no size or 导出 icon; in selection mode the size sits right after
   the check, a quiet tabular column. A 模组 row names its pack only when two widgets share a name. */
.ap-pack-row > .ap-pack-size { flex: none; min-width: 4.6em; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; text-align: left; white-space: nowrap; }
.ap-pack-title > .ap-widget-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); text-overflow: ellipsis; white-space: nowrap; }
.ap-ui .ap-pack-row > button.ap-pack-check { display: grid; flex: none; place-items: center; width: 28px; height: 28px; min-height: 0; margin: 0 -2px 0 -4px; padding: 0; border: 0; border-radius: 50%; background: none; }
.ap-ui .ap-pack-row > button.ap-pack-check:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 0; }
.ap-pack-check .ap-check-mark { box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--fork-ink) 38%, transparent); color: var(--fork-on-accent, #fff); }
.ap-pack-check[aria-checked=true] .ap-check-mark { background: var(--fork-accent-fill, var(--fork-accent)); box-shadow: none; }
.ap-pack-check:disabled .ap-check-mark { box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--fork-ink) 16%, transparent); }
.ap-ui .ap-pack-section.is-picking .ap-pack-row:has(.ap-pack-check[aria-checked=false]) .ap-pack-name { color: var(--fork-ink-3); }
@container (max-width: 520px) {
  .ap-pack-row { gap: 8px; }
}
@container (max-width: 400px) {
  .ap-pack-row { gap: 6px; }
}
/* the kind filter and the sort sit on the search row — a filter icon (plus
   the chosen kind's short name, in the accent) and the sort icon; a little air separates them from the import / add icons. */
.ap-kind-anchor, .ap-sort-anchor { flex: none; }
.ap-pack-toolbar > .ap-sort-anchor { margin-right: 6px; }
.ap-ui button.ap-kind-menu { display: inline-flex; align-items: center; gap: 4px; min-width: 32px; min-height: 0; height: 32px; padding: 0 8px; border: 0; border-radius: 16px; background: none; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; white-space: nowrap; }
.ap-ui button.ap-kind-menu:hover:not(:disabled), .ap-ui button.ap-kind-menu[aria-expanded=true] { background: var(--fork-hover); }
.ap-ui button.ap-kind-menu[data-on] { padding: 0 11px 0 9px; color: var(--fork-accent); }
.ap-kind-menu .ap-glyph { flex: none; width: 15px; height: 15px; }
.ap-kind-anchor .ap-popover { min-width: 148px; }
.ap-ui .ap-kind-option .ap-kind-icon, .ap-ui .ap-kind-option > .ap-glyph { flex: none; width: 15px; height: 15px; color: var(--fork-ink-2); }
.ap-ui .ap-kind-option[aria-checked=true], .ap-ui .ap-kind-option[aria-checked=true] .ap-kind-icon, .ap-ui .ap-kind-option[aria-checked=true] > .ap-glyph { color: var(--fork-accent); }
.ap-kind-option > .ap-state-check { margin-left: auto; }
/* A phone-wide panel: the icons close up so the search keeps room for its words. */
@container (max-width: 400px) {
  .ap-pack-toolbar { gap: 0; }
  .ap-pack-toolbar > .ap-sort-anchor { margin-right: 0; }
  .ap-ui .ap-pack-toolbar > button.ap-icon-button, .ap-ui .ap-pack-toolbar .ap-sort-anchor button.ap-icon-button { width: 30px; }
  .ap-ui .ap-pack-toolbar button.ap-kind-menu { min-width: 30px; padding: 0 7px; }
  .ap-ui .ap-pack-toolbar button.ap-kind-menu[data-on] { padding: 0 8px 0 7px; }
}
.ap-ui .ap-sort-anchor button.ap-icon-button { width: 32px; height: 32px; color: var(--fork-ink); }
.ap-ui .ap-sort-anchor button.ap-icon-button[data-on] { color: var(--fork-accent); }
.ap-sort-anchor .ap-popover { min-width: 132px; }
/* 素材库 rows — size (one right-aligned column) and a quiet 导出 icon just
   left of the state pill; the icon's slot stays while selecting so nothing moves. Selection mode: the header's icons
   become 「已选 N」 · 取消 · 导出 (the 舞台设置 head pills); the round check before each title is the shared .ap-pack-check. */
.ap-lib-aside { display: inline-flex; flex: none; align-items: center; gap: 2px; }
.ap-lib-size { min-width: 4.6em; color: var(--fork-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
.ap-ui .ap-lib-aside > button.ap-lib-export, .ap-lib-export.is-gap { display: grid; flex: none; place-items: center; width: 28px; height: 28px; min-height: 0; padding: 0; color: var(--fork-ink-3); }
.ap-ui .ap-lib-aside > button.ap-lib-export:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-lib-export .ap-glyph { width: 15px; height: 15px; }
.ap-lib-picked { flex: none; margin: 0 6px 0 8px; color: var(--fork-ink-2); white-space: nowrap; }
.ap-ui .ap-pack-toolbar > button.ap-manage { flex: none; height: 28px; }
.ap-pack-toolbar > button.ap-lib-cancel { margin-right: 6px; }
@container (max-width: 400px) {
  .ap-lib-size { min-width: 0; }
  .ap-home.is-picking .ap-pack-toolbar > .ap-search { min-width: 6.2em; }
  .ap-lib-picked { margin: 0 4px 0 2px; font-size: var(--fork-fs-body); }
  .ap-ui .ap-pack-toolbar > button.ap-manage { padding: 0 9px; }
  .ap-pack-toolbar > button.ap-lib-cancel { margin-right: 3px; }
}

/* Menus: target picker (复制到… / 保存到), filter, 添加文件. */
.ap-target-menu { display: flex; flex-direction: column; gap: 1px; min-width: 232px; }
.ap-ui .ap-menu-item { align-items: center; gap: 8px; text-align: left; white-space: normal; }
.ap-ui .ap-menu-item.is-create { color: var(--fork-accent); font-weight: 600; }
.ap-target-plus { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--fork-accent-soft); color: var(--fork-accent); }
.ap-target-plus .ap-glyph { width: 13px; height: 13px; }
.ap-target-new { display: flex; align-items: center; gap: 6px; padding: 4px; }
.ap-ui .ap-target-new input.ap-new-input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { height: 30px; font-size: var(--fork-fs-body); }
.ap-target-list { display: flex; flex-direction: column; gap: 1px; margin-top: 2px; padding-top: 4px; border-top: 1px solid var(--ap-border); }
.ap-file-item { position: relative; display: flex; align-items: center; gap: 10px; min-height: 34px; padding: 0 12px; border-radius: 6px; color: var(--fork-ink); font-size: var(--fork-fs-body); cursor: pointer; }
.ap-file-item:hover, .ap-file-item:focus-within { background: var(--fork-hover); }
.ap-file-item .ap-kind-icon { width: 15px; height: 15px; margin: 0; color: var(--fork-accent); }
.ap-add-files .ap-popover, .ap-filter-anchor .ap-popover { min-width: 150px; }
.ap-ui button.ap-target-button { min-height: 0; height: 30px; gap: 6px; padding: 0 10px 0 12px; border-radius: 8px; }
.ap-ui button.ap-target-button.is-empty { color: var(--fork-accent); }
.ap-target-anchor .ap-popover { left: 0; right: auto; }
.ap-tag { display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 8px; border-radius: 11px; background: var(--fork-hover); color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 500; }
.ap-tag.is-user { padding-left: 2px; background: var(--fork-accent-soft); color: var(--fork-accent); }

/* The pack modal: fixed size, header · left (kinds, tools, items, select bar) · right (detail). */
/* the pack modal grows with wide screens — 92% of the window up to
   1440 × 960 (90% of the height); short windows (≤ 800px) keep the old 16px margins so 1280 × 720 stays roomy. */
.ap-modal.ap-pack-modal { display: flex; flex-direction: column; width: min(1440px, 92vw, 100%); height: min(960px, 90dvh); padding: 0; overflow: hidden; }
@media (max-height: 800px) { .ap-modal.ap-pack-modal { height: calc(100dvh - 32px); } }
.ap-pack-modal > .ap-modal-body { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: 0; overflow: hidden; }
