.ap-stand-wrap .fork-live2d-preview[data-drag=pan] { cursor: grabbing; }
/* the crop tool acts on what the preview shows, so it floats on the preview's bottom-right
   corner — a translucent 32px disc that only firms up on hover / keyboard focus. */
.ap-ui button.ap-stand-tool { position: absolute; z-index: 2; right: 10px; bottom: 10px; display: grid; place-items: center; width: 32px; height: 32px; min-height: 0; padding: 0; border: 0; border-radius: 50%;
  background: color-mix(in srgb, var(--fk-current-bgSolid, Canvas) 62%, transparent); color: var(--fork-ink); box-shadow: 0 1px 4px #0000001f; transition: background-color .15s; }
