.ap-stand-wrap:has(> .ap-stand-tool) > .ap-view-tools { right: 50px; }
.ap-ui button.ap-view-tool { display: grid; place-items: center; width: 32px; height: 32px; min-height: 0; padding: 0; border: 0; border-radius: 50%;
  background: color-mix(in srgb, var(--fk-current-bgSolid, Canvas) 55%, transparent); color: var(--fork-ink); box-shadow: 0 1px 4px #0000001a; opacity: .72; transition: opacity .15s, background-color .15s; }
.ap-ui button.ap-view-tool:hover:not(:disabled), .ap-ui button.ap-view-tool:focus-visible { background: var(--fk-current-bgSolid, Canvas); opacity: 1; }
.ap-stand-wrap:hover .ap-view-tool, .ap-stand-wrap:focus-within .ap-view-tool { opacity: .92; }
.ap-ui button.ap-view-tool:disabled { opacity: .32; filter: none; cursor: default; }
.ap-view-tool .ap-glyph { width: 15px; height: 15px; }
.ap-view-hint { position: absolute; z-index: 2; left: 10px; bottom: 14px; max-width: calc(100% - 140px); overflow: hidden; padding: 3px 9px; border-radius: 11px; pointer-events: none;
  background: color-mix(in srgb, var(--fk-current-bgSolid, Canvas) 62%, transparent); color: var(--fork-ink-2); font-size: var(--fork-fs-meta); line-height: 16px; text-overflow: ellipsis; white-space: nowrap; opacity: 0; transition: opacity .2s; }
@media (hover: hover) { .ap-stand-wrap:hover > .ap-view-hint { opacity: 1; } }
.ap-stand-wrap:has(.ap-still-canvas:active, .fork-live2d-preview[data-drag]) > .ap-view-hint { opacity: 0; }
.ap-stand-wrap .fork-live2d-preview:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: -3px; }
@media (prefers-reduced-motion: reduce) { .ap-ui button.ap-view-tool, .ap-view-hint { transition: none; } }
/* the card's three corners — the 差分 label top-left, the asset actions
   top-right, zoom / fit bottom-right — are quiet translucent glass over the picture. With a mouse they appear while the
   pointer is on the card or focus is inside it; on touch they stay, subtle. What must stay seen stays: an empty card's
   actions (there is nothing to look at but them), a ✦ that is running / waiting / failed (its status dot), the ⚠ note. */
.ap-stand-wrap > .ap-stage-mood { background: color-mix(in srgb, var(--fk-current-bgSolid, Canvas) 58%, transparent); box-shadow: 0 1px 4px #0000001a; -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.ap-ui .ap-stand-wrap button.ap-view-tool { -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.ap-stand-wrap > :is(.ap-stage-mood, .ap-preview-actions, .ap-view-tools) { opacity: .82; transition: opacity .18s; }
@media (hover: hover) and (pointer: fine) {
  .ap-stand-wrap > :is(.ap-stage-mood, .ap-preview-actions, .ap-view-tools) { opacity: 0; }
  .ap-stand-wrap:is(:hover, :focus-within) > :is(.ap-stage-mood, .ap-preview-actions, .ap-view-tools),
  .ap-stand-wrap[data-empty] > .ap-preview-actions, .ap-stand-wrap > .ap-preview-actions:has([data-gen-state]) { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) { .ap-stand-wrap > :is(.ap-stage-mood, .ap-preview-actions, .ap-view-tools) { transition: none; } }
/* while the 声音 page plays a voice the 差分 label stays shown; a talking
   立绘's mouth is a canvas laid exactly over the still (same box as the picture); a picture without a mouth gets only the
   label's small waveform (the voice page's disc in miniature), never a fake mouth. */
.ap-stand-wrap > .ap-stage-mood[data-speaking] { opacity: 1; }
.ap-stand-box > canvas.ap-stand-mouth { position: absolute; pointer-events: none; }
.ap-stage-voice { display: inline-flex; align-items: center; gap: 2px; height: 10px; color: var(--chip-color); }
.ap-stage-voice > i { display: block; width: 2px; height: 5px; border-radius: 1px; background: currentColor; animation: ap-voice-wave .8s ease-in-out infinite alternate; }
.ap-stage-voice > i:nth-child(2) { height: 10px; animation-delay: -.4s; }
.ap-figure-silhouette { display: grid; place-items: center; color: var(--figure-color); background: color-mix(in srgb, var(--figure-color) 15%, Canvas); }
.ap-figure-silhouette > svg { width: 55%; height: 55%; }

.ap-figure-main { min-width: 0; }
/* The empty card's corner holds the upload badge (same corner as the crop tool). */
.ap-stand-wrap > .ap-slot-upload { right: 10px; bottom: 10px; width: 32px; height: 32px; }
.ap-stand-wrap > .ap-slot-upload .ap-glyph { width: 16px; height: 16px; }
/* desktop — the figure list takes the whole left column (the preview moved into the
   figure page); the page pads 20 / 28 / 32 and scrolls as one, the card staying pinned at its top. */
@media (min-width: 721px) {
  .ap-pack-cols[data-kind=figures] .ap-items { padding-bottom: 16px; }
  .ap-pack-right:has(> .ap-figure-editor) { padding: 20px 28px 32px; container: ap-figure-page / size; }
  /* the card uses the page's visible height instead of a fixed 232 × 348 box
     (a tall empty band sat under it). Height = the page's content box (its 20 / 32 padding already taken off),
     348–960px; width follows the height (× .44), 232–380px (v3.1 r3, with the larger modal), and always leaves the
     editor at least 480px. The sticky
     `top: 0` already counts from the page's padding edge, so the card never moves while the page scrolls and its bottom
     stays on the page's bottom padding. */
  /* the card grows with the page — up to .62 of its height in width, as
     long as the editor keeps at least 560px (its reading width; it takes all the rest) — so neither column leaves a gutter. */
  .ap-figure-editor { --ap-card-h: clamp(348px, 100cqh, 960px); --ap-card-w: clamp(240px, min(calc(var(--ap-card-h) * .62), calc(100cqw - 588px)), 600px); grid-template-columns: var(--ap-card-w) minmax(0, 1fr); }
  .ap-stand-wrap { width: var(--ap-card-w); height: var(--ap-card-h); }
  /* v3.1 r2: the selected outfit's 触发词 cell takes the rest of the strip and wraps its chips inside itself. */
  .ap-prop.is-words { flex: 1 1 200px; grid-template-rows: 16px auto; }
  .ap-prop.is-words .ap-prop-value { height: auto; min-height: 32px; }
  /* v3.1 r3: an emotion's wide properties (演出指导, 表情 / 动作 chips, the 立绘 grid) take a whole line of the strip. */
  .ap-prop.is-wide { flex: 1 1 100%; grid-template-rows: 16px auto; }
  .ap-prop.is-wide > .ap-prop-value { display: block; height: auto; }
  .ap-prop.ap-map-avatar { grid-template-rows: 16px auto; }
  .ap-prop.ap-map-avatar > .ap-prop-value { height: auto; }
}
/* desktop editor column. One left edge; type 20 / 14 /
   13 / 12; spacing 4 · 8 · 12 · 16 · 24; every control 32px high. The name row, then the properties as one strip of
   labelled cells (label above, control below; a cell wraps whole, never inside). */
.ap-figure-main > .ap-detail-title { margin: 0 0 12px; }
.ap-ui .ap-figure-main > .ap-detail-title input.ap-title-input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { font-size: 20px; font-weight: 700; }
.ap-fe-facts { display: grid; margin: 0 0 4px; }
.ap-figure-main .ap-fe-line { grid-template-columns: 80px minmax(0, 1fr); }
.ap-fe-props { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 12px 28px; margin: 0 0 4px; }
.ap-prop { display: grid; grid-template-rows: 16px 32px; gap: 6px; min-width: 0; }
.ap-prop-key { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 500; line-height: 16px; white-space: nowrap; }
.ap-prop-value { display: flex; align-items: center; gap: 8px; min-width: 0; height: 32px; font-size: var(--fork-fs-body); }
.ap-prop-value .ap-segmented { flex: none; }
