.ap-outfit-faces { display: grid; grid-template-columns: repeat(auto-fill, 80px); align-items: start; gap: 14px 16px; }
.ap-ui button.ap-outfit-face { display: flex; flex-direction: column; justify-content: flex-start; align-items: stretch; gap: 6px; min-width: 0; min-height: 0; padding: 0; border: 0; background: none; color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 400; white-space: normal; }
