.ap-outfit-lamp { position: absolute; z-index: 1; right: 6px; top: 6px; width: 10px; height: 10px; border-radius: 50%; background: var(--ap-lamp-green); box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas); }
