.ap-face-name { max-width: 100%; overflow: hidden; text-overflow: ellipsis; }
.ap-face[aria-pressed=true] .ap-face-name { color: var(--emotion-color, var(--fork-accent)); font-weight: 700; }
.ap-face[data-missing] .ap-face-art > * { filter: grayscale(1) contrast(.6) brightness(1.2); }
.ap-face[data-missing] .ap-face-art::after { box-shadow: none; border: 1.5px dashed var(--emotion-color, var(--fork-accent)); }
.ap-face[aria-pressed=true] .ap-face-art::after, .ap-face[aria-expanded=true] .ap-face-art::after { box-shadow: inset 0 0 0 3px var(--emotion-color, var(--fork-accent)); }
.ap-face[data-missing][aria-pressed=true] .ap-face-art::after, .ap-face[data-missing][aria-expanded=true] .ap-face-art::after { box-shadow: none; border-width: 3px; }
.ap-emotion-rest { position: absolute; left: calc(50% - 34px); top: -2px; z-index: 1; padding: 0 5px; border-radius: 6px; background: var(--emotion-color, var(--fork-accent)); color: #fff; font-size: 10px; font-weight: 600; line-height: 15px; }
.ap-face-add .ap-face-art { display: grid; place-items: center; background: none; color: var(--fork-ink-2); }
.ap-face-add .ap-face-art::after { box-shadow: none; border: 1.5px dashed var(--ap-border-strong); }
.ap-face-add:hover .ap-face-art::after { border-color: var(--fork-accent); }
.ap-face-add .ap-face-art .ap-glyph { width: 18px; height: 18px; }
.ap-ui button.ap-face-add:hover:not(:disabled) { background: none; color: var(--fork-accent); }
.ap-face-add[aria-expanded=true] .ap-face-art { color: var(--fork-accent); }
.ap-face-add[aria-expanded=true] .ap-face-art::after { border: 2px solid var(--fork-accent); }
.ap-emotion-dot { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--emotion-color, var(--fork-accent)); }
/* the open 差分 has no title and no heading row — inline 「label value」
   rows (名称 for a custom 差分, 使用情景 wrapping in its value column, then the media rows), one label column wide
   enough for 「使用情景 (?)」; delete / fold are quiet icons at the end of the first row. */
.ap-emotion-detail { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: start; column-gap: 8px; padding-top: 6px; }
.ap-emotion-fields { display: grid; min-width: 0; }
