.ap-emotion-fields .fork-inline-field.ap-map-prop > .fork-inline-value { padding: 6px 0; }
.ap-emotion-fields .fork-inline-field.ap-map-prop > .fork-inline-value > * { flex: 1 1 100%; min-width: 0; }
.ap-emotion-tools { display: inline-flex; align-items: center; gap: 0; min-height: 38px; }
.ap-ui .ap-emotion-tools > .ap-icon-button { width: 30px; height: 30px; color: var(--fork-ink-3, var(--fork-ink-2)); }
.ap-ui .ap-emotion-tools > .ap-icon-button:is(:hover, :focus-visible) { color: var(--fork-ink); }
.ap-tag.is-rest { background: color-mix(in srgb, var(--detail-color, var(--fork-accent)) 14%, Canvas); color: var(--fork-ink); }
.ap-fe-value > .ap-field-error { flex-basis: 100%; margin: 0; }
.ap-emotion-new .ap-fe-value { flex-wrap: nowrap; }
.ap-ui .ap-emotion-new input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { width: 140px; min-height: 0; height: 32px; }
.ap-ui .ap-emotion-new button.ap-emotion-add { margin: 0; }
.ap-emotion-new > .ap-field-error { margin: 0 0 4px; }
.ap-ui button.ap-add-row { gap: 6px; min-height: 0; height: 34px; margin: 4px 0 0; padding: 0 12px 0 10px; border-style: dashed; font-size: var(--fork-fs-body); }
.ap-add-row .ap-glyph { width: 13px; height: 13px; }
/* The media properties flow straight into the emotion's property group. */
.ap-map-panel { display: contents; }
.ap-map-choices { display: flex; flex-wrap: wrap; gap: 5px; max-height: 128px; overflow: auto; }
.ap-ui button.ap-map-choice { min-height: 0; height: 26px; padding: 0 10px; border-radius: 13px; font-size: var(--fork-fs-meta); }
.ap-ui button.ap-map-choice[aria-checked=true] { border-color: transparent; background: var(--fork-accent-fill, var(--fork-accent)); color: var(--fork-on-accent, #fff); }
/* 立绘 are standing pictures — small 3:4 busts in the outfit tile's frame, an upload
