.ap-map-states { display: grid; grid-template-columns: repeat(auto-fill, 52px); gap: 10px 10px; max-height: 236px; overflow: auto; padding: 2px; }
.ap-ui button.ap-map-state, .ap-ui label.ap-map-state { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); justify-items: stretch; align-content: start; gap: 4px; width: 100%; min-width: 0; min-height: 0; padding: 0; border: 0; background: none; color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 400; white-space: nowrap; cursor: pointer; }
.ap-ui button.ap-map-state:hover:not(:disabled), .ap-ui label.ap-map-state:hover { background: none; color: var(--fork-accent); }
.ap-map-state-art { position: relative; display: block; width: 100%; aspect-ratio: 3 / 4; overflow: hidden; border-radius: 8px;
  background: linear-gradient(color-mix(in srgb, var(--figure-color, var(--fork-accent)) 9%, Canvas), color-mix(in srgb, var(--figure-color, var(--fork-accent)) 20%, Canvas)); }
.ap-ui button.ap-map-state[aria-checked=true] { color: var(--fork-accent); font-weight: 600; }
/* one selection colour inside an emotion — its own colour, as on the roster and the
   detail's mark (the accent blue only selects outside an emotion: outfits, cast). Light emotion colours stay readable:
   the chip is a tint with ink text and the labels mix the colour with ink. */
.ap-ui .ap-emotion-detail button.ap-map-state[aria-checked=true] { color: color-mix(in srgb, var(--detail-color, var(--fork-accent)) 80%, var(--fork-ink)); }
.ap-ui .ap-emotion-detail button.ap-map-choice[aria-checked=true] { border-color: transparent; background: color-mix(in srgb, var(--detail-color, var(--fork-accent)) 22%, var(--fk-current-bgSolid, Canvas)); box-shadow: inset 0 0 0 1.5px var(--detail-color, var(--fork-accent)); color: var(--fork-ink); font-weight: 600; }
.ap-map-state > span:not(.ap-map-state-art) { max-width: 100%; overflow: hidden; text-align: center; text-overflow: ellipsis; }
.ap-map-states { align-items: start; }
.ap-map-state-add .ap-map-state-art { display: grid; place-items: center; box-sizing: border-box; background: none; border: 1.5px dashed var(--ap-border-strong); color: var(--fork-ink-2); }
.ap-map-state-add:not([data-disabled]):hover .ap-map-state-art { border-color: var(--fork-accent); color: var(--fork-accent); }
