.ap-map-state-add .ap-map-state-art .ap-glyph { width: 16px; height: 16px; }
.ap-map-state-add > input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); pointer-events: none; }
.ap-map-state-add:focus-within .ap-map-state-art { outline: 2px solid var(--fork-accent); outline-offset: 2px; }
.ap-map-state-add[data-disabled] { filter: var(--fk-current-dim, grayscale(1)); pointer-events: none; }
.ap-map-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.ap-map-avatar-art { position: relative; display: grid; flex: none; place-items: center; width: 40px; height: 40px; overflow: hidden; border-radius: 50%; background: var(--fork-hover); color: var(--fork-ink-2); }
.ap-map-avatar-art > .ap-map-avatar-thumb { position: absolute; inset: 0; }
.ap-map-avatar-art img { display: block; width: 100%; height: 100%; object-fit: cover; }
.ap-map-avatar-art > .ap-glyph { width: 18px; height: 18px; }
.ap-ui .ap-map-actions .ap-file-button, .ap-ui .ap-map-actions button.ap-chip-button { display: inline-flex; align-items: center; justify-content: center; gap: 5px; min-height: 0; height: 32px; margin: 0; padding: 0 14px; border-radius: 16px; font-size: var(--fork-fs-meta); }
.ap-map-actions .ap-glyph { width: 13px; height: 13px; }
@media (prefers-reduced-motion: reduce) and (update: none) { .ap-outfit-art, .ap-face-art { transition: none; } }
/* the upload badge of an empty slot — a 22px accent disc on the slot's
