.ap-ui button.ap-slot-gen { position: absolute; left: 50%; top: 50%; display: grid; place-items: center; width: 30px; height: 30px; min-height: 0; margin: -15px 0 0 -15px; padding: 0; border: 0; border-radius: 50%; background: none; color: var(--emotion-color, var(--fork-accent)); pointer-events: auto; cursor: pointer; transition: background-color .15s, transform .15s; }
.ap-ui button.ap-slot-gen:hover { background: var(--fork-hover); transform: scale(1.06); }
