.ap-hero-wrap > .ap-slot-upload .ap-glyph { width: 16px; height: 16px; }
.ap-ui button.ap-hero-gen { position: absolute; z-index: 2; right: 10px; bottom: 10px; display: grid; place-items: center; width: 32px; height: 32px; min-height: 0; padding: 0; overflow: visible; border: 0; border-radius: 50%;
  background: var(--fk-current-bgSolid, Canvas); color: var(--fork-accent); box-shadow: 0 1px 4px #0000002e; }
