.ap-hero-gen > .ap-gen-img { position: absolute; inset: 2px; width: calc(100% - 4px); height: calc(100% - 4px); border-radius: 50%; object-fit: cover; }
.ap-hero-gen > .ap-gen-dot { right: -1px; top: -1px; }
