.ap-gen-sheet.is-wide > .ap-modal-body { grid-template-columns: minmax(0, 1fr); }
.ap-gen-stage { position: relative; display: grid; place-items: center; min-width: 0; min-height: 0; box-sizing: border-box; padding: 20px; overflow: hidden; container-type: size;
  background: color-mix(in srgb, var(--fork-ink) 4%, var(--fk-current-bgSolid, Canvas)); }
.ap-gen-stage[data-checker] { background: repeating-conic-gradient(color-mix(in srgb, var(--fork-ink) 8%, Canvas) 0 25%, Canvas 0 50%) 0 0 / 16px 16px; }
/* A whole picture is laid over the stage inside its padding, so any ratio fits without growing the stage. */
.ap-gen-stage > .ap-gen-full { position: absolute; left: 20px; top: 20px; display: block; width: calc(100% - 40px); height: calc(100% - 40px); }
.ap-gen-full img, img.ap-gen-full { display: block; width: 100%; height: 100%; object-fit: contain; }
.ap-gen-stage > .fork-spinner { position: static; }
.ap-gen-empty { display: grid; place-items: center; box-sizing: border-box; width: min(56cqw, calc(64cqh * var(--gen-a, 1))); aspect-ratio: var(--gen-a, 1); border: 1.5px dashed var(--ap-border-strong); border-radius: 16px; color: var(--fork-ink-2); }
.ap-gen-empty > .ap-glyph { width: 28px; height: 28px; }
.ap-gen-stage[data-kind=sprite] { --gen-a: .667; }
.ap-gen-stage[data-kind=settei], .ap-gen-stage[data-kind=avatar-sheet] { --gen-a: 1.5; }
.ap-gen-stage[data-kind=background] { --gen-a: 1.778; }
.ap-gen-wait { display: grid; justify-items: center; gap: 6px; max-width: 320px; color: var(--fork-ink-2); text-align: center; }
.ap-gen-wait-spin { position: relative; display: block; width: 64px; height: 64px; margin-bottom: 2px; }
.ap-gen-wait > strong { color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-gen-time { font-size: var(--fork-fs-body); font-variant-numeric: tabular-nums; }
.ap-gen-wait > small { color: var(--ap-ink-3); font-size: var(--fork-fs-meta); }
