.ap-gen-wait.is-failed > p { margin: 0; color: var(--fork-ink); font-size: var(--fork-fs-body); line-height: 20px; }
.ap-gen-slices { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px 12px; width: min(100%, 132cqh); }
.ap-gen-slice { display: grid; justify-items: center; gap: 4px; min-width: 0; margin: 0; font-size: var(--fork-fs-meta); }
.ap-gen-slice-art { position: relative; display: block; width: 100%; aspect-ratio: 1; overflow: hidden; border-radius: 14px; box-shadow: 0 0 0 1px var(--ap-border); }
.ap-gen-slice-art img { display: block; width: 100%; height: 100%; object-fit: contain; }
.ap-gen-slice.is-skip { aspect-ratio: 1; box-sizing: border-box; border: 1.5px dashed var(--ap-border); border-radius: 14px; }
.ap-gen-side { display: flex; flex-direction: column; gap: 16px; min-width: 0; min-height: 0; box-sizing: border-box; padding: 20px; overflow: auto; border-left: 1px solid var(--ap-border); }
.ap-gen-side > * { margin: 0; }
.ap-gen-side > .ap-alert { margin: 0; }
.ap-gen-side .ap-gen-reason { margin: 0; }
.ap-gen-warns { display: flex; flex-wrap: wrap; gap: 6px; }
.ap-gen-warn { display: inline-flex; align-items: center; gap: 5px; max-width: 100%; min-height: 26px; box-sizing: border-box; padding: 3px 10px 3px 8px; border-radius: 13px; font-size: var(--fork-fs-meta); line-height: 18px; cursor: help;
  background: color-mix(in srgb, var(--fork-warn) 14%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--fork-warn) 55%, var(--fork-ink)); }
.ap-gen-warn > .ap-glyph { flex: none; width: 13px; height: 13px; color: var(--fork-warn); }
.ap-gen-tones { display: flex; gap: 8px; }
.ap-gen-tone { position: relative; display: block; width: 76px; aspect-ratio: 3 / 4; overflow: hidden; border-radius: 10px; box-shadow: 0 0 0 1px var(--ap-border); }
.ap-gen-tones[data-shape=avatar] .ap-gen-tone { width: 64px; aspect-ratio: 1; border-radius: 14px; }
.ap-gen-tone[data-tone=light] { background: #f3f1ee; }
.ap-gen-tone[data-tone=dark] { background: #1d1c22; }
.ap-gen-tone img { display: block; width: 100%; height: 100%; object-fit: contain; }
.ap-gen-tone > .fork-spinner { position: absolute; }
.ap-gen-view { align-self: flex-start; }
.ap-gen-used, .ap-gen-field { display: grid; gap: 6px; }
.ap-gen-used .ap-gen-ref { width: 40px; height: 40px; border-radius: 8px; }
.ap-gen-foot { display: flex; flex: none; align-items: center; justify-content: flex-end; gap: 8px; padding: 12px 20px; border-top: 1px solid var(--ap-border); }
.ap-ui .ap-gen-foot button, .ap-ui .ap-gen-foot .ap-file-button { min-height: 0; height: 32px; }
.ap-ui .ap-gen-foot button .ap-glyph { width: 14px; height: 14px; }
.ap-gen-foot > .ap-busy { margin-right: auto; }
/* ==== gen-ui r12: pictures are made where they go ==== */
/* The 差分 heading's tools: 「✦ 生成缺失立绘」 / 「✦ 生成缺失头像」 (no count), 「正在画 a/b · 停止」, 「N 张待采用 · 全部采用」 — quiet, before the ⋯. */
.ap-gen-tools { display: inline-flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 4px 12px; min-width: 0; font-size: var(--fork-fs-meta); font-weight: 500; letter-spacing: 0; }
.ap-ui button.ap-gen-fill { display: inline-flex; align-items: center; gap: 5px; min-height: 0; height: 28px; padding: 0 10px 0 8px; font-size: var(--fork-fs-meta); }
