.ap-gen-fill > .ap-glyph { width: 13px; height: 13px; color: var(--fork-accent); }
.ap-gen-progress, .ap-gen-waiting { display: inline-flex; align-items: center; gap: 6px; color: var(--fork-ink-2); white-space: nowrap; font-variant-numeric: tabular-nums; }
.ap-gen-tools .ap-inline-link { font-size: inherit; font-weight: 600; }
.ap-gen-notices { display: grid; gap: 6px; margin: 0 0 8px; }
.ap-gen-notices > * { margin: 0; }
/* The tile menu (mock E2): the app's popover with a head (差分 · view · state), menu items, a ⚠ row for a failure or a
   missing 设定, and 「设置回退 ›」 turning into its choices. A gated item stays listed with its reason under it. */
.ap-face-menu-anchor { display: block; }
.ap-face-menu-anchor > button.ap-face { width: 100%; }
.ap-cell-menu { display: grid; min-width: 232px; max-width: 280px; padding: 2px 0; }
.ap-cell-menu-head { display: flex; align-items: baseline; gap: 8px; margin: 0 0 3px; padding: 6px 10px; border-bottom: 1px solid var(--ap-border); }
.ap-cell-menu-head > b { color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-ui .ap-cell-menu .ap-menu-item { gap: 10px; min-height: 34px; height: auto; padding: 4px 10px; }
.ap-cell-menu .ap-menu-item > .ap-glyph:first-child { flex: none; width: 15px; height: 15px; color: var(--fork-ink-2); }
.ap-cell-menu .ap-menu-item.is-danger > .ap-glyph:first-child { color: inherit; }
.ap-cell-menu .ap-menu-item > .ap-glyph:last-child:not(:first-child) { flex: none; width: 12px; height: 12px; color: var(--fork-ink-3, var(--fork-ink-2)); }
.ap-cell-menu-text { display: grid; flex: 1 1 auto; min-width: 0; text-align: left; }
.ap-cell-menu-hint { flex: none; max-width: 7em; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); text-overflow: ellipsis; white-space: nowrap; }
.ap-cell-menu-warn { display: flex; align-items: flex-start; gap: 6px; margin: 2px 0; padding: 4px 10px; color: color-mix(in srgb, var(--fork-warn) 65%, var(--fork-ink)); font-size: var(--fork-fs-meta); line-height: 1.45; }
.ap-cell-menu-warn > .ap-glyph { flex: none; width: 13px; height: 13px; margin-top: 1.5px; color: var(--fork-warn); }
.ap-ui .ap-cell-menu .ap-menu-item.ap-cell-menu-back { color: var(--fork-ink-2); font-weight: 600; }
.ap-cell-menu .ap-menu-item .ap-state-check { display: inline-grid; flex: none; margin-left: auto; color: var(--fork-accent); }
.ap-cell-menu .ap-menu-item .ap-state-check .ap-glyph { width: 14px; height: 14px; }
.ap-menu-sep { height: 1px; margin: 4px 8px; background: var(--ap-border); }
/* The selected 差分's request line in its detail (R9): one row — state pill, ⚠ chips, the reason or detail, the actions
   (compact; it wraps only when the width runs out, the actions keeping to the right). */
.ap-gen-status { display: grid; gap: 4px; padding: 2px 0 6px; }
.ap-gen-status-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; min-height: 32px; }
.ap-gen-pill { display: inline-flex; align-items: center; height: 22px; padding: 0 9px; border-radius: 11px; background: var(--fork-accent-soft, var(--fork-hover)); color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 600; white-space: nowrap; }
.ap-gen-pill[data-state=failed] { background: color-mix(in srgb, var(--fork-warn) 18%, var(--fk-current-bgSolid, Canvas)); }
.ap-gen-pill[data-state=queued] { background: var(--fork-hover); color: var(--fork-ink-2); }
.ap-gen-status-actions { display: inline-flex; flex-wrap: wrap; gap: 8px; margin-left: auto; }
.ap-ui .ap-gen-status-actions button { display: inline-flex; align-items: center; gap: 5px; min-height: 0; height: 30px; padding: 0 12px; }
.ap-gen-status-actions .ap-glyph { width: 13px; height: 13px; }
.ap-gen-status-meta { display: flex; flex: 1 1 10em; min-width: 0; align-items: center; gap: 6px; margin: 0; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); line-height: 1.4; overflow-wrap: anywhere; }
.ap-gen-warn-ink { display: inline-flex; align-items: flex-start; gap: 5px; color: color-mix(in srgb, var(--fork-warn) 65%, var(--fork-ink)); }
.ap-gen-warn-ink > .ap-glyph { flex: none; width: 13px; height: 13px; margin-top: 2px; color: var(--fork-warn); }
.ap-gen-status .ap-gen-warns { gap: 4px; }
.ap-gen-status .ap-gen-warn { min-height: 22px; padding: 1px 8px 1px 6px; font-size: var(--fork-fs-meta); }
/* The preview card while the picked 差分 draws (the ring, 正在画 and the time) and while its candidate waits (checkerboard,
   「待采用」, the outfit 设定图 in the corner to compare against). */
.ap-gen-stage-wait { display: grid; justify-items: center; gap: 6px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-gen-stage-wait > b { color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-stand.ap-gen-stand { position: absolute; inset: 0; display: block; overflow: hidden; border-radius: inherit;
  background: repeating-conic-gradient(color-mix(in srgb, var(--fork-ink) 8%, var(--fk-current-bgSolid, Canvas)) 0 25%, var(--fk-current-bgSolid, Canvas) 0 50%) 0 0 / 16px 16px; }
.ap-gen-stand-art { position: absolute; inset: 14px 14px 0; display: block; }
.ap-gen-stand-art img { display: block; width: 100%; height: 100%; object-fit: contain; object-position: center bottom; }
.ap-gen-stand[data-kind=avatar] .ap-gen-stand-art { inset: 14px; }
.ap-gen-stand[data-kind=avatar] .ap-gen-stand-art img { object-position: center; }
.ap-gen-stand-art > .fork-spinner { position: absolute; }
.ap-gen-badge.is-stage { left: 12px; bottom: 12px; padding: 2px 10px; border-radius: 10px; font-size: var(--fork-fs-meta); line-height: 18px; transform: none; }
/* The preview of a 差分 another stands in for (回退): the stand-in's picture with this quiet tag at its foot. */
.ap-stage-standin { position: absolute; left: 12px; bottom: 12px; z-index: 3; display: inline-flex; align-items: center; gap: 4px; max-width: calc(100% - 24px); height: 24px; box-sizing: border-box; padding: 0 10px 0 8px;
  border-radius: 12px; background: var(--fk-current-bgSolid, Canvas); box-shadow: 0 0 0 1px var(--ap-border-strong); color: var(--fork-ink-2); font-size: var(--fork-fs-meta); white-space: nowrap; }
.ap-stage-standin > .ap-glyph { flex: none; width: 12px; height: 12px; }
.ap-stage-standin > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.ap-gen-pip { position: absolute; right: 10px; top: 10px; z-index: 3; display: grid; justify-items: center; gap: 2px; width: 112px; padding: 4px 4px 2px; border-radius: 10px;
  background: var(--fk-current-bgSolid, Canvas); box-shadow: 0 0 0 1px var(--ap-border-strong); }
.ap-gen-pip > .ap-thumb { display: block; width: 104px; height: 70px; overflow: hidden; border: 0; border-radius: 6px; }
.ap-gen-pip img { display: block; width: 100%; height: 100%; object-fit: contain; }
.ap-gen-pip > small { color: var(--fork-ink-2); font-size: var(--fork-fs-meta); line-height: 16px; }
/* ---------- The ONE generation dialog (gen-ui b5): one column, no preview, no divider lines ---------- */
.ap-modal.ap-gen-dialog { display: flex; flex-direction: column; width: min(640px, 100%); max-height: min(760px, calc(100dvh - 32px)); padding: 0; overflow: hidden; }
.ap-gen-dialog > .ap-modal-body { display: block; min-height: 0; padding: 0; overflow: auto; }
.ap-gen-dialog .ap-gen-sheet-head { border-bottom: 0; padding-bottom: 4px; }
.ap-gen-dialog .ap-gen-sheet-head > .ap-gen-sheet-meta { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-gen-dialog .ap-gen-sheet-head > .ap-help-anchor { margin-left: -4px; }
.ap-gen-dialog .ap-gen-foot { border-top: 0; padding-top: 4px; }
.ap-gd-body { display: block; padding: 16px 24px; }
.ap-gd-fields { display: grid; align-content: start; gap: 8px; min-width: 0; }
.ap-gd-fields > p { margin: 0; }
.ap-gd-row.fork-inline-field { --fork-inline-label-w: 5.5em; }
.ap-gd-row.is-text.fork-inline-field { padding-block: 2px; }
/* 参考图: the 设定图 that exist (wide), the picture being redrawn, uploads, and the dashed ＋. */
.ap-gd-refs { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 8px 12px; padding: 4px 0 2px; }
