.fork-widget-context{position:absolute;z-index:4;pointer-events:auto;display:grid;gap:2px;width:max-content;min-width:184px;max-width:min(280px,calc(100% - 16px));box-sizing:border-box;padding:8px 6px 6px;overflow:hidden;background:var(--gal-ui-surface);color:var(--gal-ui-ink);border:1px solid color-mix(in srgb,var(--gal-ui-line) 70%,var(--gal-ui-surface));border-radius:calc(var(--gal-ui-radius) + 6px);box-shadow:var(--gal-ui-shadow);font:13px/1.3 var(--gal-ui-font);animation:fork-widget-context-in .14s ease-out}
