.fork-widget-context button.fork-widget-context-row.is-parted{margin-top:7px}
.fork-widget-context-row.is-parted::before{content:"";position:absolute;left:12px;right:12px;top:-5px;height:1px;background:color-mix(in srgb,var(--gal-ui-line) 50%,var(--gal-ui-surface))}
