.fork-widget-context.is-sheet{left:max(8px,calc(50% - 220px));right:max(8px,calc(50% - 220px));bottom:max(8px,env(safe-area-inset-bottom));width:auto;min-width:0;max-width:none;padding:6px 8px 10px;border-radius:calc(var(--gal-ui-radius) + 12px);animation-name:fork-widget-context-rise}
