.fork-widget-menu-list{position:absolute;top:calc(100% + 10px);right:-4px;z-index:3;box-sizing:border-box;display:grid;width:max-content;min-width:168px;max-width:min(280px,calc(100vw - 16px));max-height:min(60vh,420px);overflow:hidden auto;overscroll-behavior:contain;padding:4px;
  border-radius:min(var(--gal-ui-radius),14px);background:var(--gal-ui-surface-2);color:var(--gal-ui-ink);box-shadow:var(--gal-ui-shadow),inset 0 0 0 1px var(--gal-ui-line);font-family:var(--gal-ui-font);cursor:default;animation:fork-widget-context-in .16s ease-out}
