.ap-ui button.ap-widget-reset { width: 30px; min-width: 30px; height: 30px; min-height: 30px; padding: 0; border: 0; border-radius: 50%; color: var(--fork-ink-2); }
.ap-ui button.ap-widget-reset:hover:not(:disabled) { color: var(--fork-accent); background: var(--fork-hover); }
.ap-widget-mode { display: flex; align-items: center; gap: 6px; }
/* pack-level only — a changed field says 「已修改」 in quiet ink next to its title; a
   field on the widget default shows nothing. */
.ap-widget-modified { display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; line-height: 1; color: var(--fork-ink-2); white-space: nowrap; }
.ap-widget-modified::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--fork-accent); }
.ap-widget-settings-title { font-size: var(--fork-fs-body); font-weight: 600; }
.ap-detail-pane > .ap-widget-settings { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--ap-border); }
.ap-detail-pane > .ap-widget-settings > .ap-widget-settings-head { margin: 0; }
.ap-entry-menu { flex: none; }
/* Switch (a button with role=switch). */
.ap-ui button.ap-widget-switch { position: relative; gap: 8px; min-height: 30px; padding: 0; border: 0; border-radius: 15px; background: none; font-size: var(--fork-fs-meta); color: var(--fork-ink-2); }
.ap-ui button.ap-widget-switch:hover:not(:disabled) { background: none; color: var(--fork-ink); }
.ap-widget-knob { position: relative; flex: none; width: 36px; height: 20px; border-radius: 10px; background: var(--ap-border-strong); transition: background-color .15s; }
.ap-widget-knob::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px #0003; transition: transform .15s; }
.ap-widget-switch[aria-checked=true] .ap-widget-knob { background: var(--fork-accent); }
.ap-widget-switch[aria-checked=true] .ap-widget-knob::after { transform: translateX(16px); }
.ap-widget-switch-text { order: -1; min-width: 2em; text-align: right; }
/* Slider + number. */
.ap-widget-range { display: flex; flex: 1 1 auto; align-items: center; gap: 14px; min-width: 0; max-width: 420px; }
.ap-widget-slider { --ratio: 0; position: relative; flex: 1 1 160px; min-width: 120px; height: 44px; touch-action: none; cursor: pointer; border-radius: 6px; }
.ap-widget-slider::before { content: ""; position: absolute; left: 0; right: 0; top: 20px; height: 4px; border-radius: 2px; background: var(--ap-border-strong); }
.ap-widget-slider-fill { position: absolute; left: 0; top: 20px; height: 4px; width: calc(var(--ratio) * 100%); border-radius: 2px; background: var(--fork-accent); pointer-events: none; }
.ap-widget-slider-thumb { position: absolute; top: 13px; left: calc(var(--ratio) * (100% - 18px)); width: 18px; height: 18px; border-radius: 50%; background: var(--ap-field); box-shadow: 0 0 0 1.5px var(--fork-accent), 0 1px 3px #0003; pointer-events: none; }
.ap-widget-slider:focus-visible { outline: none; }
.ap-widget-slider:focus-visible .ap-widget-slider-thumb { box-shadow: 0 0 0 1.5px var(--fork-accent), 0 0 0 5px color-mix(in srgb, var(--fork-accent) 22%, transparent); }
/* the slider's exact value is an inline number (InlineField, hidden label). */
.ap-widget-range > .fork-inline-field.ap-widget-number { flex: none; min-height: 0; }
/* Colour: the live swatch, 跟随舞台 / 自定义颜色, quick swatches, exact hex. */
/* pack-level colour row — swatch + 跟随舞台/自定义 on the title line; palette + hex below only for 自定义. */
/* Image setting: one trigger (current picture + name) opening the shared background picker; small 16:9 lazy thumbs. */
.ap-widget-setting .ap-opening-picker { max-width: 360px; }
.ap-ui .ap-opening-picker.has-art > button.ap-target-button { height: 40px; padding-left: 6px; gap: 10px; }
.ap-opening-picker.has-art .ap-opening-picker-value { flex: 1; text-align: left; }
.ap-opening-picker.has-art .ap-menu-item { gap: 10px; min-height: 40px; padding-left: 6px; }
.ap-ui .ap-picker-art { display: grid; place-items: center; flex: none; width: 48px; height: 27px; aspect-ratio: auto; border-radius: 5px; overflow: hidden; background: var(--fork-hover); color: var(--fork-accent); }
.ap-picker-art[data-default] { background: linear-gradient(160deg, var(--fork-accent-soft), var(--fork-hover)); }
.ap-picker-art .ap-glyph { width: 15px; height: 15px; }
/* Binding editor. */
.ap-widget-binding { display: grid; justify-items: start; gap: 8px; min-width: 0; }
.ap-ui .ap-widget-binding input:not([type=checkbox]):not([type=file]) { max-width: 360px; }
.ap-widget-fallback { display: flex; align-items: center; gap: 8px; margin: 0; font-size: 12.5px; }
/* Feedback: ready = quiet info line; anything else = ⚠ chip. */
.ap-ui p.ap-widget-feedback { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 6px; justify-self: start; max-width: 100%; margin: 0; padding: 3px 10px; border-radius: 12px; font-size: var(--fork-fs-meta); line-height: 1.5; color: var(--fork-ink); background: color-mix(in srgb, var(--ap-state-card) 10%, transparent); }
.ap-ui p.ap-widget-feedback.is-warning { background: color-mix(in srgb, var(--dsw-alias-state-warning-primary, #b7791f) 13%, transparent); }
.ap-ui p.ap-widget-feedback.is-loading { background: var(--fork-hover); }
.ap-widget-feedback .fork-spinner { --fork-spinner-size: 12px; }
.ap-widget-feedback .ap-hint-mark .ap-glyph { width: 14px; height: 14px; }
.ap-widget-snapshot { display: inline-flex; align-items: center; height: 18px; padding: 0 7px; border-radius: 9px; font-size: 11px; background: color-mix(in srgb, var(--fork-ink) 8%, transparent); white-space: nowrap; }
.ap-widget-snapshot[data-kind=saved-unverified], .ap-widget-snapshot[data-kind=unavailable] { background: color-mix(in srgb, var(--dsw-alias-state-warning-primary, #b7791f) 16%, transparent); }
.ap-widget-snapshot[data-kind=live-only] { background: color-mix(in srgb, var(--ap-state-global) 14%, transparent); }
.ap-ui p.ap-widget-dependency { display: flex; align-items: center; gap: 6px; margin: 0; font-size: var(--fork-fs-meta); }
.ap-widget-dependency .ap-glyph { width: 14px; height: 14px; color: var(--fork-accent); }
.ap-widget-reset-all { justify-content: flex-start; margin: 8px 0 0; }
.ap-widget-reset-all .ap-glyph { width: 14px; height: 14px; margin-right: 2px; }
/* a widget entry in the 素材库 — the shared defaults, then this card's part (本卡 switch +
   its settings) after one hairline, never a box. */
.ap-widget-card { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--ap-border); min-width: 0; }
.ap-widget-head-end { display: inline-flex; align-items: center; gap: 10px; margin-left: auto; min-width: 0; }
.ap-widget-head-end > .ap-widget-reading { margin-left: 0; }
.ap-widget-settings-head > .ap-widget-head-end > .ap-hint-line { margin: 0; }
.ap-ui .ap-widget-card button.ap-widget-switch { min-height: 44px; }
/* Stage theme (background author panel). */
.ap-stage-theme > summary { display: flex; align-items: center; gap: 6px; min-height: 36px; cursor: pointer; font-weight: 600; font-size: var(--fork-fs-body); }
/* Export dependency list. */
.ap-dependency-list { list-style: none; margin: 8px 0 0; padding: 0; }
.ap-dependency-list li { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; padding: 8px 0; border-top: 1px dashed var(--ap-border); font-size: var(--fork-fs-body); }
.ap-dependency-what { flex: 1; min-width: 0; }
.ap-dependency-from { display: inline-flex; align-items: center; gap: 4px; font-size: var(--fork-fs-meta); }
.ap-dependency-from[data-missing] { color: var(--fork-warn); }
.ap-dependency-from .ap-glyph { width: 13px; height: 13px; }
@media (max-width: 420px) {
  .ap-widget-setting .ap-segmented { flex-wrap: wrap; }
  .ap-widget-range { gap: 8px; }
  .ap-ui button.ap-widget-reset { min-width: 36px; min-height: 36px; }
}
@media (pointer: coarse) {
  .ap-ui button.ap-widget-reset, .ap-ui button.ap-widget-switch { min-width: 44px; min-height: 44px; }
}
@media (prefers-reduced-motion: reduce) {
  .ap-widget-knob, .ap-widget-knob::after { transition: none; }
}

/* cast binding choices are readable cards, not white captions over stage art. */
/* 角色表 — story name → figure + 出场方式 as transparent faces on a floor tinted
   with the figure's colour (no boxes); the entry sheet and its figure picker share the same face grammar. */
.ap-ui .ap-cast { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 4px; }
.ap-ui .ap-cast > li { min-width: 0; border-bottom: 0; }
.ap-ui button.ap-cast-row, .ap-ui button.ap-cast-choice { display: grid; justify-items: center; align-content: start; gap: 3px; width: 100%; height: 100%; min-height: 0; margin: 0; padding: 8px 4px 10px; border: 0; border-radius: 12px; background: none; color: var(--fork-ink); text-align: center; white-space: normal; }
.ap-ui button.ap-cast-row:hover:not(:disabled), .ap-ui button.ap-cast-choice:hover:not(:disabled) { background: var(--fork-hover); }
.ap-cast-face { position: relative; display: grid; place-items: end center; flex: none; width: 64px; height: 64px; }
.ap-cast-face::before { content: ""; position: absolute; left: 8px; right: 8px; bottom: 0; height: 9px; border-radius: 50%; background: color-mix(in srgb, var(--figure-color, var(--fork-accent)) 38%, var(--fk-current-bgSolid, Canvas)); filter: blur(2.5px); }
.ap-cast-face > .ap-avatar { position: relative; width: 58px; height: 58px; margin-bottom: 3px; border-radius: 0; background: none; }
.ap-cast-face > .ap-avatar img { object-fit: contain; object-position: center bottom; }
.ap-cast-face > .ap-avatar.ap-figure-silhouette { width: 52px; height: 52px; margin-bottom: 5px; border-radius: 50%; }
.ap-cast-face > .ap-figure-silhouette > svg { width: 56%; height: 56%; }
/* no figure-colour underline (a pale colour read as 「no underline」); the colour stays on the
   floor under the face. */
.ap-cast-name { max-width: 100%; overflow: hidden; font-size: var(--fork-fs-body); font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
/* One cast face frame (r4, CAST_FACE): head-and-shoulders from the head anchor, fading out at the shoulders. */
.ap-cast-face > .ap-avatar.ap-head-art { position: relative; overflow: hidden; -webkit-mask-image: linear-gradient(#000 78%, transparent); mask-image: linear-gradient(#000 78%, transparent); }
.ap-cast-face > .ap-avatar:not(.ap-figure-silhouette) { -webkit-mask-image: linear-gradient(#000 78%, transparent); mask-image: linear-gradient(#000 78%, transparent); }
/* Hover never paints a box (a grey card read as a second 「selected」 style); only the selection has the tint + ✓. */
.ap-ui button.ap-cast-row:hover:not(:disabled), .ap-ui button.ap-cast-choice:hover:not(:disabled) { background: none; }
.ap-ui button.ap-cast-choice[aria-pressed=true]:hover:not(:disabled) { background: var(--fork-accent-soft); }
.ap-cast-face::before { transition: background-color .15s; }
.ap-cast-row:hover:not(:disabled) .ap-cast-face::before, .ap-cast-choice:hover:not(:disabled) .ap-cast-face::before { background: color-mix(in srgb, var(--figure-color, var(--fork-accent)) 70%, var(--fk-current-bgSolid, Canvas)); }
.ap-ui button.ap-cast-row:hover:not(:disabled) .ap-cast-name, .ap-ui button.ap-cast-choice:hover:not(:disabled) .ap-cast-name { color: var(--fork-accent); }
.ap-cast-issue { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; color: var(--fork-warn); font-size: var(--fork-fs-meta); line-height: 1.4; }
.ap-cast-issue .ap-glyph { flex: none; width: 12px; height: 12px; }
.ap-cast-badge { position: absolute; z-index: 1; right: 0; top: 2px; display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; background: var(--fk-current-bgSolid, Canvas); box-shadow: 0 0 0 1px var(--ap-border-strong); color: var(--fork-ink); }
.ap-cast-badge .ap-glyph { width: 12px; height: 12px; }
.ap-cast-badge.is-check { background: var(--fork-accent-fill, var(--fork-accent)); box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas); color: var(--fork-on-accent, #fff); }
/* a cast tile is face + name; a problem is a small ⚠ on the face (its text is the tooltip). */
.ap-cast-badge.is-warning { left: 0; right: auto; color: var(--fork-warn); box-shadow: 0 0 0 1px color-mix(in srgb, var(--fork-warn) 45%, transparent); }
.ap-ui button.ap-cast-row.is-add .ap-cast-face { place-items: center; }
.ap-cast-row.is-add .ap-cast-face::before { content: none; }
.ap-cast-row.is-add .ap-cast-face > .ap-glyph { width: 50px; height: 50px; padding: 15px; box-sizing: border-box; border: 1.5px dashed var(--ap-border-strong); border-radius: 50%; color: var(--fork-ink-2); }
.ap-cast-row.is-add .ap-cast-name { text-decoration: none; font-weight: 500; }
/* the placeholder is a visible disc in the figure colour, and its ⚠ sits on the disc's
   upper-left edge (like on a face) instead of floating in the tile's corner. */
.ap-cast-face > .ap-avatar.ap-figure-silhouette { background: color-mix(in srgb, var(--figure-color, var(--fork-figure-fallback)) 18%, var(--fk-current-bgSolid, Canvas)); box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--figure-color, var(--fork-figure-fallback)) 45%, transparent); }
.ap-cast-face:has(> .ap-figure-silhouette) > .ap-cast-badge.is-warning { left: 3px; top: 5px; }
.ap-cast-choice .ap-cast-face:has(> .ap-figure-silhouette) > .ap-cast-badge.is-warning, .ap-cast-head > .ap-cast-face:has(> .ap-figure-silhouette) > .ap-cast-badge.is-warning { left: 1px; top: 3px; }
.ap-avatar.is-live2d img, .ap-item-avatar.is-live2d img { width: 100%; height: 100%; object-fit: cover; object-position: center; }
.ap-ui .ap-cast > li.ap-cast-new:has(form) { grid-column: span 2; }
.ap-ui .ap-cast-new .ap-create { display: grid; align-content: center; gap: 8px; min-width: 0; height: 100%; margin: 0; padding: 8px 4px; }
.ap-cast-new .ap-create-tools { display: flex; align-items: center; gap: 4px; }
.ap-ui .ap-cast-new .ap-create-tools .ap-chip-button { margin: 0; }
.ap-cast-new .ap-create > .ap-field-error { margin: 0; }
/* a figure's lamp is a dot on its face's shoulder (the library's outfit lamp): a button
   that opens the 蓝灯 / 绿灯 / 关闭 menu. A switched-off figure is greyed. */
.ap-ui .ap-cast > li { position: relative; }
.ap-ui .ap-cast > li > .ap-cast-lamp-anchor { position: absolute; z-index: 1; top: 2px; left: calc(50% + 10px); }
.ap-ui button.ap-cast-lamp { display: grid; place-items: center; width: 30px; min-width: 30px; height: 30px; min-height: 0; padding: 0; border: 0; border-radius: 50%; background: none; color: var(--ap-lamp-green); }
.ap-ui button.ap-cast-lamp:hover:not(:disabled) { background: none; }
.ap-cast-lamp .ap-lamp-dot { width: 11px; height: 11px; box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas); transition: box-shadow .15s; }
.ap-cast-lamp:hover .ap-lamp-dot, .ap-cast-lamp[aria-expanded=true] .ap-lamp-dot { box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas), 0 0 0 3.5px currentColor; }
.ap-ui .ap-cast-lamp[data-mode=constant], .ap-ui .ap-lamp-opt[data-mode=constant] { color: var(--ap-lamp-blue); }
.ap-ui .ap-lamp-opt[data-mode=keyword] { color: var(--ap-lamp-green); }
.ap-ui .ap-cast-lamp[data-mode=off], .ap-ui .ap-lamp-opt[data-mode=off] { color: var(--fork-lamp-off); }
.ap-cast-lamp[data-mode=off] .ap-lamp-dot { background: var(--fk-current-bgSolid, Canvas); box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas), inset 0 0 0 1.5px currentColor; }
.ap-cast-lamp[data-mode=off]:hover .ap-lamp-dot, .ap-cast-lamp[data-mode=off][aria-expanded=true] .ap-lamp-dot { box-shadow: 0 0 0 2px var(--fk-current-bgSolid, Canvas), 0 0 0 3.5px currentColor, inset 0 0 0 1.5px currentColor; }
.ap-ui .ap-menu-item.ap-lamp-opt { gap: 10px; }
.ap-lamp-opt-name { flex: 1; color: var(--fork-ink); white-space: nowrap; }
.ap-cast-lamp-anchor .ap-popover { min-width: 132px; }
.ap-ui .ap-cast > li[data-off] .ap-cast-face { filter: grayscale(1); }
.ap-ui .ap-cast > li[data-off] .ap-cast-name { color: var(--ap-ink-3); }
/* the shell's touch rule (tavern.css: right-sidebar buttons at least 40px tall at ≤1023px
   or a coarse pointer) must not stretch the panel's round marks into ovals — the 「?」 and the figure lamps keep their
   circle (lamps) or glyph size (the 「?」, whose 32px touch target is padding — see the standard tokens block). */
@media (max-width: 1023px), (pointer: coarse) {
  body.dsh-tavern-shell-active [data-sidebar-right-panel] .ap-ui :is(button.fork-help-tip-button, button.ap-help) { min-height: 0; }
  body.dsh-tavern-shell-active [data-sidebar-right-panel] .ap-ui button.ap-cast-lamp { min-height: 0; }
  /* The state chip is one size everywhere (§三.10): the shell's 40px touch floor must not turn it into a square. */
  body.dsh-tavern-shell-active .ap-ui button.ap-state-tag { min-height: 0; }
}
/* UI standard R15 (acceptance M2): the phone's full-screen right drawer is a settings surface — opaque. The host paints it
   with --dsw-alias-bg-base, which is translucent under Desktop mica, so the chat showed through; use the solid base.
   Open only: DSH 0.2.x keeps the closed panel mounted as a full-screen, pointer-transparent layer over the chat (only its
   dock slides out), so an unconditional fill blanked the whole phone page behind the sidebar toggle. */
body.dsh-tavern-shell-active [data-sidebar-right-panel="fullscreen"][data-sidebar-right-open] { background: var(--fk-s-base-bgSolid, Canvas); }
/* Phone / touch: lamps get the 36px hit area (§三.11); the dot stays put. */
@media (max-width: 720px), (pointer: coarse) {
  .ap-ui button.ap-cast-lamp, .ap-ui button.ap-cast-lamp.ap-outfit-lamp-button { width: 36px; min-width: 36px; height: 36px; }
  .ap-ui .ap-cast > li > .ap-cast-lamp-anchor { top: -1px; left: calc(50% + 7px); }
  .ap-outfit-cell > .ap-outfit-lamp-anchor { top: -7px; right: -7px; }
}
/* 默认舞台皮肤 is the CONFIG skin select in panel paint — the trigger is the chosen skin's
   mini stage + name + chevron (as wide as the CONFIG one); menu rows are mini stage + name + ✓, as wide as the trigger. */
.ap-skin-anchor { display: block; max-width: 420px; }
.ap-ui button.ap-skin-trigger { justify-content: flex-start; gap: 14px; width: 100%; height: 52px; padding: 0 14px 0 6px; border-radius: 12px; background: var(--ap-field); font-size: 14px; font-weight: 600; letter-spacing: .06em; }
.ap-ui button.ap-skin-trigger[aria-expanded=true] { border-color: var(--fork-accent); box-shadow: 0 0 0 1px var(--fork-accent); }
.ap-skin-name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-align: left; text-overflow: ellipsis; white-space: nowrap; }
.ap-skin-trigger > .ap-glyph { flex: none; color: var(--fork-ink-2); transition: transform .15s; }
.ap-skin-trigger[aria-expanded=true] > .ap-glyph { transform: rotate(180deg); }
.ap-skin-anchor .ap-popover { padding: 6px; }
.ap-skin-anchor > .ap-popover:not(.is-floating) { left: 0; right: auto; min-width: 100%; }
.ap-skin-menu { display: grid; gap: 2px; }
.ap-skin-menu .ap-search.is-compact { margin: 2px 2px 6px; }
.ap-ui .ap-menu-item.ap-skin-option { gap: 14px; min-height: 48px; padding: 5px 12px 5px 5px; border-radius: 9px; font-size: 13.5px; font-weight: 600; letter-spacing: .06em; }
.ap-ui .ap-menu-item.ap-skin-option[aria-checked=true] { background: var(--fork-accent-soft); color: var(--fork-accent); }
.ap-skin-option .fork-gal-config-theme-art { width: 60px; height: 37px; }
.ap-ui .fork-gal-config-theme-art.is-unknown { background: var(--fork-hover); box-shadow: inset 0 0 0 1px var(--ap-border-strong); }
.ap-ui .fork-gal-config-theme-art.is-unknown b { color: var(--fork-accent); font-family: inherit; font-size: 16px; font-weight: 600; line-height: 1; }
/* SKIP is text, not a decorative tint; retain readable opaque ink throughout skipping. */
.fork-gal-stage[data-theme] .fork-gal-box.is-skipping[data-figure-skip-color]::after {
  color: var(--figure-skip-ink); background: var(--figure-skip-surface); animation: none;
}
/* a figure's 声音 — one compact property on the figure page and the voice page
   that replaces the figure column (desktop: the preview card stays pinned beside it; phone: a full-screen sub-page with
   its own top bar). One left edge, hairlines between the ways (no box in a box, no accent bar); ⚠ chips only for real
   warnings; adding is a dashed ＋ with no text; every paint is opaque. */
.ap-ui { --ap-warn: var(--fork-warn); }
.ap-ui .ap-prop button.ap-voice-pill { max-width: 240px; }
.ap-voice-pill[data-empty] > span { color: var(--fork-ink-2); }
.ap-ui button.ap-voice-pill > .ap-hint-mark { flex: none; margin-right: -2px; }
.ap-voice-pill > .ap-hint-mark .ap-glyph { width: 14px; height: 14px; color: var(--ap-warn); }
.ap-pick-pill > span.ap-voice-pill-muted { flex: none; padding: 0 6px; border-radius: 6px; background: var(--fork-hover); color: var(--fork-ink-2); font-size: var(--fork-fs-meta); line-height: 18px; }
.ap-ui button.ap-voice-play[aria-pressed=true] { background: var(--fork-accent-fill, var(--fork-accent)); color: var(--fork-on-accent, #fff); }
.ap-ui button.ap-voice-play[data-state=error] { color: var(--ap-warn); }

.ap-voice-page { min-width: 0; padding-bottom: 8px; }
.ap-voice-saving { display: inline-flex; margin-left: auto; --fork-spinner-size: 16px; }
.ap-voice-page > .ap-voice-error { position: sticky; top: 0; z-index: 2; margin: 0 0 12px; background: var(--fk-current-bgSolid, Canvas); }

/* The current voice: disc · name (⋯) · how it speaks · ⚠; then 配音语言 and the 试听 line — the page's focal point. */
.ap-voice-hero { display: grid; grid-template-columns: 64px minmax(0, 1fr); align-items: center; gap: 16px 20px; padding: 4px 0 24px; }
.ap-voice-hero > .ap-voice-props, .ap-voice-hero > .ap-voice-try, .ap-voice-hero > .ap-voice-try-error, .ap-voice-hero > .ap-notice { grid-column: 1 / -1; }
.ap-voice-id { display: grid; justify-items: start; gap: 4px; min-width: 0; }
