.ap-ui button.ap-voice-tile-main { display: grid; justify-content: stretch; justify-items: start; align-content: start; gap: 3px; width: 100%; height: 100%; min-height: 104px; padding: 12px 48px 12px 14px; border: 1px solid var(--ap-border-strong); border-radius: 14px;
  background: linear-gradient(160deg, color-mix(in srgb, var(--figure-color, var(--fork-accent)) 7%, var(--fk-current-bgSolid, Canvas)), var(--fk-current-bgSolid, Canvas) 70%); color: var(--fork-ink); text-align: left; white-space: normal; }
