.ap-ui button.ap-voice-provider-head:hover:not(:disabled) { background: none; color: var(--fork-accent); }
.ap-ui button.ap-voice-provider-head:focus-visible { outline-offset: -2px; }
.ap-voice-provider-name { min-width: 0; overflow-wrap: anywhere; }
.ap-voice-provider[data-current] .ap-voice-provider-name { color: var(--fork-accent); font-weight: 600; }
.ap-voice-provider-state { min-width: 0; margin-left: auto; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 400; white-space: nowrap; text-overflow: ellipsis; text-align: right; font-variant-numeric: tabular-nums; }
.ap-voice-provider-state.is-warn { display: inline-flex; align-items: center; gap: 4px; color: color-mix(in srgb, var(--ap-warn) 80%, var(--fork-ink)); }
