.ap-ui button.ap-clip-play[aria-pressed=true] { background: var(--fork-accent-fill, var(--fork-accent)); color: var(--fork-on-accent, #fff); }
.ap-clip-play .fork-spinner { --fork-spinner-size: 14px; }
.ap-ui .ap-clip input.ap-clip-text:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { height: 32px; }
