.ap-voice-tile-menu { position: absolute; top: 8px; right: 8px; }
.ap-voice-preset-rename { display: grid; align-content: start; gap: 6px; min-height: 72px; padding: 12px 14px; border: 1px solid var(--fork-accent); border-radius: 14px; box-shadow: 0 0 0 1px var(--fork-accent); }
.ap-ui .ap-voice-preset-rename input.ap-voice-preset-name-input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { width: 100%; height: 30px; }
.ap-voice-preset-add-row { display: grid; min-width: 0; }
.ap-ui button.ap-voice-preset-add { width: 100%; height: 100%; min-height: 72px; padding: 0; border: 1.5px dashed var(--ap-border-strong); border-radius: 14px; background: none; color: var(--fork-ink-2); }
.ap-ui button.ap-voice-preset-add:hover:not(:disabled) { border-color: var(--fork-accent); background: none; color: var(--fork-accent); }
.ap-voice-preset-add .ap-glyph { width: 16px; height: 16px; }
.ap-voice-tune-row > .fork-inline-value > .ap-tune { flex: 0 1 320px; min-width: 0; }
.ap-slider output.ap-tune-value { width: 52px; }
.ap-voice-na { color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.ap-voice-bymood { margin-top: 4px; border-top: 1px solid var(--ap-border); }
.ap-ui button.ap-voice-subhead { min-height: 44px; font-size: var(--fork-fs-body); }
.ap-voice-moods { display: grid; grid-template-columns: repeat(auto-fill, minmax(208px, 1fr)); gap: 4px 28px; margin: 0; padding: 0 0 4px; list-style: none; }
.ap-voice-mood-row { display: flex; align-items: center; gap: 8px; min-height: 40px; }
.ap-voice-mood-name { min-width: 3em; font-size: var(--fork-fs-body); }
.ap-voice-mood-row > .ap-popover-anchor { margin-left: auto; }
.ap-voice-dialog { width: min(460px, 100%); }

@media (max-width: 720px) {
  /* Phone: the voice page is a full-screen sub-page — its sub-page header (‹ · 声音, .ap-subhead, the same as on a desktop)
     replaces the figure's top bar. */
  .ap-figure-editor[data-voice] > .ap-figure-stage, .ap-figure-editor[data-voice] > .ap-fe-topbar { display: none; }
  .ap-voice-page > .ap-voice-error { top: 60px; }
  .ap-voice-hero { grid-template-columns: 52px minmax(0, 1fr); gap: 12px 14px; padding-bottom: 20px; }
  .ap-voice-disc { width: 52px; height: 52px; }
  .ap-voice-name { font-size: 17px; }
  .ap-voice-lang-row > .fork-inline-value > .ap-voice-warn { flex: 1 1 100%; }
  .ap-voice-try { flex-wrap: wrap; }
  .ap-ui input.ap-voice-try-text:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { flex: 1 1 100%; height: 36px; font-size: 14px; }
  .ap-voice-mood-anchor { flex: 1; min-width: 0; }
  .ap-ui button.ap-voice-go { height: 36px; padding: 0 22px 0 18px; font-size: 14px; }
  .ap-ui button.ap-voice-way-head { min-height: 52px; font-size: 15px; }
  .ap-voice-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .ap-ui button.ap-voice-tile-main { min-height: 112px; padding: 12px 44px 12px 12px; }
  .ap-ui button.ap-voice-tile-play { top: 8px; right: 8px; width: 36px; height: 36px; }
  .ap-voice-row { grid-template-columns: minmax(0, 1fr) auto auto auto; gap: 8px; }
  .ap-ui .ap-voice-row button.ap-chip-button { height: 36px; padding: 0 12px; }
  .ap-ui .ap-voice-row button.ap-voice-play, .ap-ui .ap-voice-row button.ap-icon-button { width: 36px; height: 36px; }
  .ap-ui .ap-voice-search input:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]), .ap-ui .ap-voice-search button.ap-voice-find { height: 36px; }
  .ap-voice-tools > .ap-segmented { flex: 1 1 100%; }
  .ap-ui .ap-voice-tools > .ap-segmented button { flex: 1; height: 32px; font-size: var(--fork-fs-body); }
  .ap-ui input.ap-voice-filter:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { flex: 1; width: auto; height: 36px; }
  .ap-clip { grid-template-columns: 20px 36px minmax(0, 1fr) 36px; grid-template-areas: "no play text menu" ". . extra extra"; row-gap: 2px; padding: 8px 0; }
  .ap-clip-no { grid-area: no; }
  .ap-ui button.ap-clip-play { grid-area: play; width: 36px; height: 36px; }
  .ap-ui .ap-clip input.ap-clip-text:not([data-ap-a]):not([data-ap-b]):not([data-ap-c]) { grid-area: text; height: 36px; font-size: 14px; }
  .ap-clip-menu { grid-area: menu; }
  .ap-ui .ap-clip-menu .ap-icon-button { width: 36px; height: 36px; }
  .ap-clip-lang { grid-area: extra; justify-self: start; }
  .ap-clip-meta { grid-area: extra; justify-self: end; }
  .ap-clip-add { height: 44px; }
  .ap-voice-tune-row > .fork-inline-value > .ap-tune { flex: 1; }
  .ap-voice-moods { grid-template-columns: minmax(0, 1fr); }
  .ap-ui .ap-voice-tile-menu .ap-icon-button { width: 36px; height: 36px; }
  .ap-ui .ap-voice-preset button.ap-voice-tile-main, .ap-ui button.ap-voice-preset-add { min-height: 84px; }
}

/*
   从网址安装 · 素材目录 · 目录来源 · 更新 · the install sheet. One focal point per sheet — the pack's 封面 (type icon on a
   soft tint), its name and one plain line; real warnings are one amber band; expert facts sit behind a quiet 「详情」.
   Hairlines and fills only: no box inside a box, no accent-bar section heads; every tint is mixed into the opaque surface
   underneath (--fk-current-bgSolid), never into transparent. Phones (≤ 720px) get full-screen sheets with fixed actions. */
.ap-cat-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 0; }
.ap-cat-chip { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; min-height: 22px; padding: 0 9px; border-radius: 11px; background: color-mix(in srgb, var(--fork-ink) 7%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 500; line-height: 1.3; white-space: nowrap; }
.ap-cat-chip > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.ap-cat-chip .ap-glyph { width: 12px; height: 12px; }
.ap-cat-chip[data-tone=official], .ap-cat-chip[data-tone=update] { background: color-mix(in srgb, var(--ap-state-global) 14%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--ap-state-global) 82%, var(--fork-ink)); }
.ap-cat-chip[data-tone=installed], .ap-cat-chip[data-tone=ok] { background: color-mix(in srgb, var(--ap-state-card) 15%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--ap-state-card) 82%, var(--fork-ink)); }
.ap-cat-chip[data-tone=unofficial] { background: color-mix(in srgb, var(--fork-ink) 9%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink-2); }
.ap-cat-chip[data-tone=warn] { background: color-mix(in srgb, var(--fork-warn) 15%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--fork-warn) 78%, var(--fork-ink)); }

/* Sheets: a quiet header (title · ×), the scrolling body, the foot with the actions. */
.ap-modal.ap-cat-sheet { display: flex; flex-direction: column; width: min(480px, 100%); max-height: min(780px, calc(100dvh - 32px)); padding: 0; overflow: hidden; }
.ap-modal.ap-cat-sheet.ap-cat-sources-sheet { width: min(560px, 100%); }
.ap-cat-sheet > .ap-modal-body { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 0 28px 22px; }
.ap-modal > header.ap-cat-head { display: flex; align-items: center; justify-content: flex-start; gap: 10px; flex: none; margin: 0; padding: 14px 14px 4px 28px; }
.ap-cat-head h2 { flex: 1; min-width: 0; margin: 0; overflow: hidden; font-size: 15px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.ap-cat-head-tools { display: inline-flex; flex: none; align-items: center; gap: 2px; }
.ap-ui .ap-cat-head-tools button.ap-icon-button { width: 32px; height: 32px; color: var(--fork-ink); }
.ap-ui .ap-cat-head-tools button.ap-icon-button:hover:not(:disabled) { background: var(--fork-hover); }
.ap-cat-foot { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 10px; flex: none; padding: 14px 28px 20px; border-top: 1px solid var(--ap-border); }
.ap-ui .ap-cat-foot > button { min-width: 88px; height: 34px; border-radius: 17px; }
.ap-ui .ap-cat-foot > button.ap-primary { min-width: 116px; font-weight: 600; }
.ap-ui .ap-cat-foot button .ap-glyph { width: 13px; height: 13px; }
.ap-ui .ap-cat-foot button .fork-spinner, .ap-ui .ap-cat-detail-actions button .fork-spinner { --fork-spinner-size: 14px; margin-right: 2px; }
.ap-cat-sheet .ap-form-row { grid-template-columns: 92px minmax(0, 1fr); }
.ap-ui input.ap-cat-mono, .ap-ui .ap-cat-mono { font-family: var(--ap-mono); font-size: var(--fork-fs-meta); }
.ap-ui p.ap-cat-quiet { margin: 36px 0; color: var(--fork-ink); text-align: center; }
.ap-ui p.ap-cat-problem { margin: 0; color: var(--ap-error); font-size: var(--fork-fs-meta); }

/* The focal point: 封面 + name + one plain line. The 封面 is the pack's type icon on its tint (picked from the name), with
   a second card peeking out behind it; no remote image is ever loaded. */
.ap-cat-hero { display: flex; flex-direction: column; align-items: center; padding: 22px 0 20px; text-align: center; }
.ap-cat-hero-text { display: grid; justify-items: center; gap: 4px; min-width: 0; max-width: 100%; }
.ap-ui h3.ap-cat-hero-name { margin: 16px 0 2px; font-size: 21px; font-weight: 700; line-height: 1.35; letter-spacing: .01em; overflow-wrap: anywhere; }
.ap-ui p.ap-cat-hero-sub { margin: 0; color: var(--fork-ink-2); font-size: var(--fork-fs-body); line-height: 1.55; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ap-ui p.ap-cat-hero-sub.ap-cat-versions { display: inline-flex; align-items: center; gap: 6px; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-cat-versions .ap-glyph { width: 13px; height: 13px; color: var(--ap-state-global); }
.ap-cat-hero[data-row] { flex-direction: row; align-items: center; gap: 26px; padding: 6px 0 18px; text-align: left; }
.ap-cat-hero[data-row] .ap-cat-hero-text { justify-items: start; }
.ap-ui .ap-cat-hero[data-row] h3.ap-cat-hero-name { margin: 0 0 2px; font-size: 19px; }
.ap-cat-art { --ap-cat-tint: var(--fork-accent); position: relative; display: grid; place-items: center; flex: none; width: 76px; height: 76px; color: color-mix(in srgb, var(--ap-cat-tint) 80%, var(--fork-ink)); }
.ap-cat-art::before, .ap-cat-art::after { content: ""; position: absolute; inset: 0; border-radius: 22px; }
.ap-cat-art::before { background: color-mix(in srgb, var(--ap-cat-tint) 16%, var(--fk-current-bgSolid, Canvas)); transform: translate(9px, -5px) rotate(10deg); }
.ap-cat-art::after { background: linear-gradient(150deg, color-mix(in srgb, var(--ap-cat-tint) 30%, var(--fk-current-bgSolid, Canvas)), color-mix(in srgb, var(--ap-cat-tint) 17%, var(--fk-current-bgSolid, Canvas))); box-shadow: 0 0 0 1px color-mix(in srgb, var(--ap-cat-tint) 24%, var(--fk-current-bgSolid, Canvas)), 0 8px 20px -10px var(--ap-cat-tint); }
.ap-cat-art > svg { position: relative; z-index: 1; width: 34px; height: 34px; margin: 0; color: inherit; }
.ap-cat-art > svg path { stroke-width: 1.1; }
.ap-cat-art[data-size=row] { width: 64px; height: 64px; }
.ap-cat-art[data-size=row]::before, .ap-cat-art[data-size=row]::after { border-radius: 18px; }
.ap-cat-art[data-size=row]::before { transform: translate(6px, -4px) rotate(8deg); }
.ap-cat-art[data-size=row] > svg { width: 28px; height: 28px; }
.ap-cat-art[data-size=card] { width: 48px; height: 48px; }
.ap-cat-art[data-size=card]::before, .ap-cat-art[data-size=card]::after { border-radius: 14px; }
.ap-cat-art[data-size=card]::before { transform: translate(5px, -3px) rotate(9deg); }
.ap-cat-art[data-size=card] > svg { width: 22px; height: 22px; }
.ap-cat-art[data-size=card] > svg path { stroke-width: 1.25; }

/* Words under the hero: the plain consequence, a quiet note (组件, 官方), and the one warning surface (amber band). */
.ap-ui p.ap-cat-lead { margin: 0 0 14px; color: var(--fork-ink); font-size: var(--fork-fs-body); line-height: 1.75; }
.ap-ui p.ap-cat-switch { margin: -8px 0 14px; }
.ap-ui .ap-cat-switch button.ap-link { margin-left: -8px; color: var(--fork-accent); font-size: var(--fork-fs-body); }
.ap-ui .ap-cat-switch button.ap-link:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-accent); }
.ap-ui p.ap-cat-note { display: flex; align-items: flex-start; gap: 8px; margin: 0 0 14px; color: var(--fork-ink); font-size: var(--fork-fs-body); line-height: 1.7; }
.ap-cat-note-mark { display: inline-flex; flex: none; margin-top: 3px; color: var(--fork-ink-2); }
.ap-cat-note-mark svg { width: 15px; height: 15px; margin: 0; color: inherit; }
.ap-ui .ap-cat-hero p.ap-cat-note { align-items: center; gap: 5px; margin: 8px 0 0; color: color-mix(in srgb, var(--ap-state-card) 80%, var(--fork-ink)); font-size: var(--fork-fs-meta); }
.ap-cat-hero .ap-cat-note-mark { margin-top: 0; color: inherit; }
.ap-cat-hero .ap-cat-note-mark svg { width: 14px; height: 14px; }
.ap-cat-band { --ap-cat-warn: var(--fork-warn); display: flex; align-items: flex-start; gap: 10px; margin: 0 0 14px; padding: 12px 14px; border-radius: 12px; background: color-mix(in srgb, var(--ap-cat-warn) 12%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink); font-size: var(--fork-fs-body); line-height: 1.7; }
.ap-cat-band-mark { display: inline-flex; flex: none; margin-top: 3px; color: var(--ap-cat-warn); }
.ap-cat-band-mark .ap-glyph { width: 16px; height: 16px; }
.ap-cat-band-text { flex: 1; min-width: 0; }
.ap-ui .ap-cat-band-text > p { margin: 0; }
.ap-ui .ap-cat-band button.ap-cat-band-action { margin-left: 6px; color: var(--fork-accent); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-cat-band[data-compact] { gap: 7px; margin: -4px 0 16px; padding: 0; background: none; font-size: var(--fork-fs-body); line-height: 1.6; }
.ap-cat-band[data-compact] .ap-cat-band-mark { margin-top: 2px; }
.ap-cat-band[data-compact] .ap-cat-band-mark .ap-glyph { width: 14px; height: 14px; }
.ap-cat-items { display: flex; flex-wrap: wrap; gap: 4px 16px; margin: 8px 0 0; padding: 0; list-style: none; }
.ap-cat-items li { display: inline-flex; align-items: center; gap: 5px; font-weight: 600; }
.ap-cat-items .ap-kind-icon { flex: none; width: 14px; height: 14px; margin: 0; color: var(--fork-ink-2); }
.ap-cat-items li.is-more { color: var(--fork-ink-2); font-weight: 400; }

/* 「详情」: a quiet disclosure; facts on hairlines (no box). */
.ap-cat-more { margin: 2px 0 0; }
.ap-ui button.ap-cat-more-toggle { gap: 4px; min-height: 0; height: 28px; margin-left: -8px; padding: 0 8px; border: 0; border-radius: 8px; color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.ap-ui button.ap-cat-more-toggle:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-cat-more-toggle .ap-glyph { width: 13px; height: 13px; transition: transform .15s; }
.ap-cat-more[data-open] .ap-cat-more-toggle .ap-glyph { transform: rotate(180deg); }
.ap-cat-more-body { padding: 4px 0 0; }
.ap-cat-more-body > .ap-form-row:first-child { margin-top: 2px; }
.ap-cat-facts { margin: 0; }
.ap-cat-fact { display: grid; grid-template-columns: 76px minmax(0, 1fr); align-items: baseline; gap: 12px; padding: 8px 0; border-top: 1px solid var(--ap-border); font-size: var(--fork-fs-body); }
.ap-cat-fact dt { color: var(--fork-ink-2); }
.ap-cat-fact dd { min-width: 0; margin: 0; color: var(--fork-ink); line-height: 1.6; overflow-wrap: anywhere; }
.ap-ui code.ap-cat-url { display: block; color: var(--fork-ink); font: 11.5px/1.6 var(--ap-mono); overflow-wrap: anywhere; word-break: break-all; user-select: all; }
/* 「详情」 of 导入卡片 — a pack's words and program files; a 模组's pack, files and values. */
.ap-cat-risk-facts { display: grid; gap: 4px; }
.ap-cat-risk-facts > .ap-cat-risk-from { color: var(--fork-ink-2); }
.ap-cat-risk-line { display: block; }
.ap-ui .ap-cat-risk-line code { display: inline; padding: 0; background: none; color: var(--fork-ink); font: inherit; overflow-wrap: anywhere; }


/* A styled single choice (menu of radios) instead of a native select. */
.ap-cat-select-anchor { max-width: 100%; }
/* the catalogue's choices read as their value with a chevron (like InlineField menus). */
.ap-ui button.ap-cat-select { justify-content: flex-start; gap: 6px; max-width: 100%; min-height: 0; height: 32px; padding: 0 2px; border: 0; border-bottom: 1px solid transparent; border-radius: 0; background: none; box-shadow: none; text-align: left; }
.ap-ui button.ap-cat-select:hover:not(:disabled), .ap-ui button.ap-cat-select[aria-expanded=true] { border-bottom-color: color-mix(in srgb, var(--fork-ink) 22%, transparent); background: none; }
.ap-cat-select > .ap-glyph { width: 13px; height: 13px; color: var(--fork-ink-2); }
.ap-cat-select-text { display: inline-flex; flex: 0 1 auto; align-items: baseline; gap: 8px; min-width: 0; overflow: hidden; }
.ap-cat-select-text > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-cat-select-text > small { flex: none; color: var(--fork-ink-2); font: 11.5px/1 var(--ap-mono); }
.ap-cat-select-anchor > .ap-popover:not(.is-floating) { left: 0; right: auto; min-width: 100%; }
.ap-ui .ap-cat-segment button:disabled { filter: none; color: var(--ap-ink-3); }

.ap-ui button.ap-cat-add { display: grid; place-items: center; flex: none; min-height: 0; padding: 0; border: 1.5px dashed var(--ap-border-strong); border-radius: 10px; background: none; color: var(--fork-ink-2); }
.ap-ui button.ap-cat-add:hover:not(:disabled) { border-color: var(--fork-accent); background: none; color: var(--fork-accent); }
.ap-cat-add .ap-glyph { width: 18px; height: 18px; }

/* 「获取素材包」 — one compact dialog sized to its
   content (≈560 px; a full-width bottom sheet on phones). The link row on top (the field reads as text on a faint underline),
   the catalogue rows below on hairlines; no tabs, no foot, nothing boxed. A link's 确认下载, every download and every error
   sit right under what started them; a dragged ZIP lights the whole dialog quietly. */
.ap-modal.ap-cat-sheet.ap-get-sheet { position: relative; width: min(560px, 100%); max-height: min(760px, calc(100dvh - 32px)); }
.ap-modal.ap-get-sheet > header.ap-cat-head { padding: 14px 12px 4px 24px; }
.ap-get-sheet > .ap-modal-body { padding: 6px 24px 18px; }
.ap-get-bar { display: flex; align-items: center; gap: 8px; }
.ap-ui input.ap-get-url { flex: 1 1 auto; min-width: 0; height: 36px; font-size: var(--fork-fs-body); }
.ap-ui input.ap-get-url::placeholder { color: var(--fork-ink-3, var(--fork-ink-2)); opacity: 1; }
.ap-ui button.ap-get-go { flex: none; min-width: 64px; height: 32px; padding: 0 16px; border-radius: 16px; font-weight: 600; }
.ap-ui button.ap-get-go:disabled { background: color-mix(in srgb, var(--fork-ink) 9%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink-3, var(--fork-ink-2)); opacity: 1; }
.ap-ui button.ap-icon-button.ap-get-zip { flex: none; width: 32px; height: 32px; border-radius: 16px; color: var(--fork-ink-2); }
.ap-ui button.ap-icon-button.ap-get-zip:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui button.ap-get-pick { gap: 6px; height: 34px; padding: 0 16px; border-radius: 17px; }
.ap-ui p.ap-get-status { display: flex; align-items: center; gap: 7px; margin: 10px 0 0; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-get-status > .fork-spinner { --fork-spinner-size: 14px; }
.ap-get-status > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-ui p.ap-get-problem { margin: 8px 0 0; }
.ap-get-confirm { margin: 12px 0 0; }
.ap-ui p.ap-get-confirm-line { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; margin: 0 0 8px; color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.ap-get-confirm-name { min-width: 0; max-width: 100%; overflow: hidden; color: var(--fork-ink); font-size: var(--fork-fs-body); font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.ap-get-confirm .ap-cat-band[data-compact] { margin: 0 0 4px; }
.ap-get-confirm-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; }
.ap-get-confirm-actions > .ap-cat-more { margin: 0 auto 0 0; }
.ap-get-confirm-actions > .ap-cat-more[data-open] { flex: 1 0 100%; order: 3; }
.ap-ui .ap-get-confirm-actions > button { min-width: 0; height: 30px; padding: 0 14px; border-radius: 15px; font-size: var(--fork-fs-body); }
.ap-ui .ap-get-confirm-actions > button.ap-get-quiet { border: 0; background: none; color: var(--fork-ink-2); }
.ap-ui .ap-get-confirm-actions > button.ap-get-quiet:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui .ap-get-confirm-actions > button.ap-primary { font-weight: 600; }
.ap-get-confirm-actions .fork-spinner { --fork-spinner-size: 13px; margin-right: 4px; }
.ap-get-link-job { margin: 12px 0 0; }
.ap-ui p.ap-get-link-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin: 0; }
.ap-get-link-head > .ap-get-confirm-name { flex: 1 1 auto; }
/* A download in place: a thin bar, 「已下 / 总量 · 速度 · 状态」, or one plain failure with 重试 / 放弃. */
.ap-get-job { display: grid; gap: 3px; }
.ap-get-job > .ap-cat-progress { height: 3px; margin: 3px 0 0; }
.ap-ui p.ap-get-job-meta { display: flex; flex-wrap: wrap; gap: 2px 10px; margin: 0; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-get-job-meta > .ap-cat-job-state { margin-left: auto; font-weight: 500; }
.ap-get-job-actions { display: flex; gap: 2px; margin-left: -8px; }
.ap-ui .ap-get-job-actions button.ap-link { min-height: 0; height: 26px; padding: 0 8px; color: var(--fork-accent); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-ui .ap-get-job-actions button.ap-link.is-quiet { color: var(--fork-ink-2); }
.ap-get-job-controls { display: inline-flex; align-items: center; }
.ap-ui .ap-get-job-controls button.ap-icon-button { width: 28px; height: 28px; color: var(--fork-ink-2); }
.ap-ui .ap-get-job-controls button.ap-icon-button:hover:not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
/* The catalogue: a quiet heading only with more than one source (or an unofficial one), rows on hairlines. */
.ap-get-catalogue { margin: 14px 0 0; }
.ap-get-group + .ap-get-group { margin-top: 16px; }
.ap-get-group-head { display: flex; align-items: center; gap: 8px; margin: 0 0 4px; }
.ap-ui .ap-get-group-head h3 { min-width: 0; margin: 0; overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-weight: 600; letter-spacing: .04em; text-overflow: ellipsis; white-space: nowrap; }
.ap-get-group > .ap-cat-band[data-compact] { margin: 0 0 4px; }
.ap-get-group > .ap-loading, .ap-get-group > .ap-alert { margin: 8px 0; }
.ap-ui p.ap-get-quiet-line { margin: 8px 0; color: var(--fork-ink-2); font-size: var(--fork-fs-body); }
.ap-get-rows { margin: 0; padding: 0; list-style: none; }
.ap-get-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 10px; padding: 1px 0; border-top: 1px solid var(--ap-border); }
.ap-get-row:first-child { border-top: 0; }
.ap-ui button.ap-get-row-main { display: flex; align-items: center; justify-content: flex-start; gap: 12px; min-width: 0; min-height: 0; height: auto; margin-left: -8px; padding: 7px 8px; border: 0; border-radius: 10px; background: none; color: var(--fork-ink); text-align: left; white-space: normal; }
.ap-ui button.ap-get-row-main:hover:not(:disabled) { background: var(--fork-hover); }
.ap-get-row-text { display: grid; gap: 1px; min-width: 0; }
.ap-get-row-name { overflow: hidden; font-size: var(--fork-fs-body); font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.ap-get-row-line { overflow: hidden; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ap-get-row-line .ap-cat-versions { display: inline-flex; align-items: center; gap: 3px; color: var(--fork-ink); vertical-align: bottom; }
.ap-get-row-line .ap-cat-versions .ap-glyph { width: 11px; height: 11px; color: var(--ap-state-global); }
.ap-get-row-action { display: inline-flex; align-items: center; justify-content: flex-end; }
.ap-ui button.ap-get-act { min-width: 56px; min-height: 0; height: 28px; padding: 0 12px; border: 0; border-radius: 14px; background: var(--fork-accent-soft); color: var(--fork-accent); font-size: var(--fork-fs-body); font-weight: 600; }
.ap-ui button.ap-get-act:hover:not(:disabled) { background: color-mix(in srgb, var(--fork-accent) 24%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-accent); }
.ap-get-act .fork-spinner { --fork-spinner-size: 12px; margin-right: 4px; }
.ap-get-installed { display: inline-flex; align-items: center; gap: 4px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-get-installed .ap-glyph { width: 13px; height: 13px; }
.ap-get-row-under { grid-column: 1 / -1; min-width: 0; padding: 0 0 8px 44px; }
.ap-get-row-under + .ap-get-row-under { margin-top: -4px; }
.ap-get-row-more .ap-cat-choices { margin: 0 0 4px; }
.ap-get-row-more .ap-cat-band[data-compact] { margin: 0 0 6px; }
.ap-get-row-more .ap-cat-fact:first-child { border-top: 0; }
.ap-get-row-more .ap-cat-fact { padding: 5px 0; }
.ap-cat-art[data-size=mini] { width: 32px; height: 32px; }
.ap-cat-art[data-size=mini]::before { content: none; }
.ap-cat-art[data-size=mini]::after { border-radius: 10px; box-shadow: none; }
.ap-cat-art[data-size=mini] > svg { width: 17px; height: 17px; }
.ap-cat-art[data-size=mini] > svg path { stroke-width: 1.3; }
/* A ZIP dragged over the dialog: one accent outline around all of it (no veil: surfaces stay opaque) and a small 「松开以导入 ZIP」. */
.ap-modal.ap-get-sheet[data-drop]::after { content: ""; position: absolute; inset: 6px; z-index: 5; border: 1.5px solid var(--fork-accent); border-radius: 12px; box-shadow: inset 0 0 0 4px var(--fork-accent-soft); pointer-events: none; }
.ap-get-drop { position: absolute; inset: 0; z-index: 6; display: grid; place-items: center; pointer-events: none; }
.ap-get-drop > span { display: inline-flex; align-items: center; gap: 8px; padding: 8px 16px; border-radius: 18px; background: var(--fk-current-bgSolid, Canvas); color: var(--fork-accent); font-size: var(--fork-fs-body); font-weight: 600; box-shadow: 0 6px 22px -8px rgba(0, 0, 0, .45); }
@media (max-width: 720px) {
  .ap-modal-scrim:has(> .ap-get-sheet) { place-items: end stretch; }
  .ap-modal.ap-cat-sheet.ap-get-sheet { width: 100%; height: auto; max-height: 88dvh; border: 0; border-top: 1px solid var(--ap-border); border-radius: 16px 16px 0 0; }
  .ap-modal.ap-get-sheet > header.ap-cat-head { padding: 12px 8px 4px 20px; }
  .ap-get-sheet > .ap-modal-body { padding: 4px 20px calc(18px + env(safe-area-inset-bottom, 0px)); }
  .ap-ui button.ap-get-go { height: 36px; border-radius: 18px; }
  .ap-ui button.ap-icon-button.ap-get-zip { width: 36px; height: 36px; border-radius: 18px; }
  .ap-ui button.ap-get-act { height: 32px; border-radius: 16px; }
}

/* Detail: hero row with one line of facts, the choice rows only when there is a choice, the action, then 「详情」. */
.ap-cat-detail { max-width: 640px; }
.ap-cat-choices { margin: 0 0 6px; }
.ap-actions.ap-cat-detail-actions { justify-content: flex-start; margin: 10px 0 12px; }
.ap-ui .ap-cat-detail-actions button { min-width: 140px; height: 38px; border-radius: 19px; font-weight: 600; }
.ap-actions.ap-cat-detail-actions[data-foot] { position: sticky; bottom: -22px; z-index: 2; justify-content: flex-end; margin: 18px -28px -22px; padding: 14px 28px 20px; border-top: 1px solid var(--ap-border); background: var(--fk-current-bgSolid, Canvas); }
/* The update sheet / phone detail: the action sits at the bottom even when the content is short. */
.ap-cat-update-sheet > .ap-modal-body { display: flex; flex-direction: column; }
.ap-cat-detail[data-sheet] { display: flex; flex: 1 0 auto; flex-direction: column; }
.ap-cat-detail[data-sheet] > .ap-cat-detail-actions[data-foot] { margin-top: auto; }
.ap-cat-detail[data-sheet] > .ap-cat-more { margin-bottom: 18px; }

/* Download progress. */
.ap-cat-progress { position: relative; height: 6px; margin: 2px 0 0; overflow: hidden; border-radius: 3px; background: color-mix(in srgb, var(--fork-ink) 11%, var(--fk-current-bgSolid, Canvas)); }
.ap-cat-progress > span { position: absolute; inset: 0 auto 0 0; border-radius: 3px; background: var(--fork-accent); transition: width .3s linear; }
.ap-cat-progress[data-state=paused] > span { background: color-mix(in srgb, var(--fork-accent) 45%, var(--fk-current-bgSolid, Canvas)); }
.ap-cat-progress[data-state=failed] > span { background: var(--ap-error); }
.ap-cat-progress[data-indeterminate] > span { width: 30%; animation: ap-cat-sweep 1.4s ease-in-out infinite; }
@keyframes ap-cat-sweep { from { transform: translateX(-100%); } to { transform: translateX(340%); } }
.ap-cat-job-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; margin: 10px 0 16px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-cat-job-state { margin-left: auto; color: var(--fork-ink); font-weight: 600; }
.ap-cat-job-state[data-state=failed] { color: var(--ap-error); }
@media (prefers-reduced-motion: reduce) {
  .ap-cat-progress > span, .ap-cat-more-toggle .ap-glyph { transition: none; }
  .ap-cat-progress[data-indeterminate] > span { width: 100%; animation: none; background: color-mix(in srgb, var(--fork-accent) 40%, var(--fk-current-bgSolid, Canvas)); }
}

/* Library: download tray, the 「可更新」 chip on a pack row. */
.ap-cat-tray { display: grid; gap: 6px; margin: 0 0 8px; }
.ap-cat-jobs { margin: 0; padding: 0; list-style: none; }
.ap-cat-job-row { display: flex; align-items: center; gap: 10px; min-height: 40px; padding: 2px 0; border-bottom: 1px solid var(--ap-border); font-size: var(--fork-fs-body); }
.ap-cat-job-icon { display: grid; place-items: center; flex: none; width: 20px; height: 20px; color: var(--fork-accent); }
.ap-cat-job-icon > .fork-spinner { --fork-spinner-size: 15px; }
.ap-cat-job-row[data-state=failed] .ap-cat-job-icon { color: var(--fork-warn); }
.ap-cat-job-name { flex: 1 1 auto; min-width: 0; overflow: hidden; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.ap-cat-job-status { flex: none; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-cat-tray > .ap-notice > .ap-glyph { color: var(--ap-state-card); }
.ap-ui button.ap-cat-update-chip { flex: none; gap: 3px; min-height: 0; height: 22px; padding: 0 9px 0 7px; border: 0; border-radius: 11px; background: color-mix(in srgb, var(--ap-state-global) 14%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--ap-state-global) 82%, var(--fork-ink)); font-size: var(--fork-fs-meta); font-weight: 600; }
.ap-ui button.ap-cat-update-chip:hover:not(:disabled) { background: color-mix(in srgb, var(--ap-state-global) 24%, var(--fk-current-bgSolid, Canvas)); }
.ap-cat-update-chip .ap-glyph { width: 12px; height: 12px; }

/* 目录来源: plain section titles (no accent bar), hairline rows. */
.ap-cat-sheet .ap-cat-section:first-child { padding-top: 10px; border-top: 0; }
.ap-cat-sheet .ap-section-head h3 { letter-spacing: .02em; }
.ap-cat-section .ap-section-head .fork-spinner { --fork-spinner-size: 14px; }
.ap-cat-source-list { margin: 0; padding: 0; list-style: none; }
.ap-cat-source-row { display: flex; align-items: center; gap: 10px; min-height: 54px; padding: 6px 0; border-bottom: 1px solid var(--ap-border); }
.ap-cat-source-text { display: grid; flex: 1; min-width: 0; }
.ap-cat-source-text strong { overflow: hidden; font-size: var(--fork-fs-body); font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.ap-ui .ap-cat-source-text code { color: var(--fork-ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-cat-source-row[data-off] strong { color: var(--fork-ink-2); }
.ap-ui button.ap-cat-toggle { justify-content: flex-start; gap: 5px; flex: none; width: 70px; min-height: 0; height: 26px; padding: 0 9px 0 7px; border: 0; border-radius: 13px; background: color-mix(in srgb, var(--fork-ink) 9%, var(--fk-current-bgSolid, Canvas)); color: var(--fork-ink); font-size: var(--fork-fs-meta); font-weight: 500; }
.ap-ui button.ap-cat-toggle[aria-pressed=true] { background: color-mix(in srgb, var(--ap-state-card) 16%, var(--fk-current-bgSolid, Canvas)); color: color-mix(in srgb, var(--ap-state-card) 82%, var(--fork-ink)); }
.ap-ui button.ap-cat-toggle:hover:not(:disabled) { background: var(--fork-hover); }
.ap-cat-toggle .ap-glyph { width: 13px; height: 13px; }
.ap-cat-remove-gap { flex: none; width: 30px; }
.ap-ui button.ap-cat-add-row { width: 100%; height: 44px; margin-top: 10px; }
.ap-cat-new-source { margin-top: 6px; }
.ap-cat-section > .ap-cat-problem { margin-top: 8px; }
.ap-cat-mirror-example { display: grid; gap: 2px; margin: 0 0 6px 104px; color: var(--fork-ink-2); font-size: var(--fork-fs-meta); }
.ap-ui .ap-cat-mirror-example code.ap-cat-url { color: var(--fork-ink-2); }

/* 导入卡片 — the install sheet's language. The focal point is the
   card: its picture (a 3:4 card; its own PNG when there is one, else a card glyph on a tint picked from its name, a
   second card peeking out behind), its name and what comes with it in words. A pack that differs from an installed one
   is one hairline row (name · 另存一份 / 替换原来的 · one consequence line). The 模组 question sits in the foot, right
   above its two answers, so on a phone the sentence and the buttons stay together. */
.ap-card-cover { --ap-cat-tint: var(--fork-accent); position: relative; display: grid; place-items: center; flex: none; width: 84px; height: 112px; color: color-mix(in srgb, var(--ap-cat-tint) 80%, var(--fork-ink)); }
.ap-card-cover::before, .ap-card-cover::after { content: ""; position: absolute; inset: 0; border-radius: 12px; }
.ap-card-cover::before { background: color-mix(in srgb, var(--ap-cat-tint) 16%, var(--fk-current-bgSolid, Canvas)); transform: translate(11px, -5px) rotate(8deg); }
.ap-card-cover::after { background: linear-gradient(160deg, color-mix(in srgb, var(--ap-cat-tint) 30%, var(--fk-current-bgSolid, Canvas)), color-mix(in srgb, var(--ap-cat-tint) 15%, var(--fk-current-bgSolid, Canvas))); box-shadow: 0 0 0 1px color-mix(in srgb, var(--ap-cat-tint) 24%, var(--fk-current-bgSolid, Canvas)), 0 10px 22px -12px var(--ap-cat-tint); }
.ap-card-cover > svg { position: relative; z-index: 1; width: 46px; height: 46px; margin: 0; color: inherit; }
.ap-card-cover > svg path { stroke-width: .9; }
.ap-card-cover > img { position: absolute; inset: 0; z-index: 2; width: 100%; height: 100%; border-radius: 12px; object-fit: cover; object-position: center top; box-shadow: 0 0 0 1px var(--ap-border), 0 10px 22px -12px var(--fork-ink); }
.ap-ui p.ap-card-import-status { display: inline-flex; align-items: center; gap: 7px; min-height: 22px; }
.ap-card-import-status > .fork-spinner { --fork-spinner-size: 14px; }
/* MB sent while a big card ZIP uploads. */
.ap-card-import-status > .ap-card-import-progress { color: var(--fork-ink-3); font-size: var(--fork-fs-meta); font-variant-numeric: tabular-nums; }
.ap-card-packs { margin: 0 0 14px; border-bottom: 1px solid var(--ap-border); }
.ap-card-pack { padding: 12px 0 14px; border-top: 1px solid var(--ap-border); }
.ap-card-pack-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; }
.ap-card-pack-head > strong { flex: 1 1 auto; min-width: 0; font-size: 14px; font-weight: 600; overflow-wrap: anywhere; }
.ap-ui .ap-card-pack .ap-cat-segment button { height: 28px; padding: 0 12px; font-size: var(--fork-fs-body); }
.ap-ui p.ap-card-pack-line { margin: 6px 0 0; color: var(--fork-ink); font-size: var(--fork-fs-body); line-height: 1.7; }
.ap-card-pack .ap-cat-band { margin: 10px 0 0; }
.ap-ui p.ap-card-import-ask { display: flex; flex: 1 0 100%; align-items: flex-start; gap: 8px; margin: 0 0 4px; color: var(--fork-ink); font-size: var(--fork-fs-body); line-height: 1.7; }
/* the import facts sit open under the lead line (no 「详情」 disclosure). */
.ap-card-import-facts { margin: 8px 0 0; }
.ap-card-import-facts:empty { display: none; }
.ap-card-import-ask > .ap-glyph { flex: none; width: 15px; height: 15px; margin-top: 4px; color: var(--fork-warn); }

@media (max-width: 720px) {
  .ap-modal-scrim:has(> .ap-cat-sheet) { padding: 0; }
  .ap-modal.ap-cat-sheet, .ap-modal.ap-cat-sheet.ap-cat-sources-sheet { width: 100%; height: 100%; max-height: 100dvh; border: 0; border-radius: 0; }
  .ap-modal > header.ap-cat-head { padding: 12px 8px 4px 20px; }
  .ap-cat-sheet > .ap-modal-body { padding: 0 20px 20px; }
  .ap-cat-hero { padding: 36px 0 26px; }
  .ap-cat-hero[data-row] { gap: 22px; padding: 4px 0 16px; }
  .ap-ui h3.ap-cat-hero-name { font-size: 22px; }
  .ap-cat-foot { padding: 12px 20px calc(14px + env(safe-area-inset-bottom, 0px)); }
  .ap-ui .ap-cat-foot > button { flex: 1 1 0; height: 44px; border-radius: 22px; font-size: 15px; }
  .ap-cat-sheet .ap-form-row { grid-template-columns: minmax(0, 1fr); gap: 6px; }
  .ap-cat-mirror-example { margin-left: 0; }
  .ap-ui .ap-cat-detail-actions button { flex: 1; height: 44px; border-radius: 22px; font-size: 15px; }
  .ap-actions.ap-cat-detail-actions[data-foot] { bottom: -20px; margin: 18px -20px -20px; padding: 12px 20px calc(14px + env(safe-area-inset-bottom, 0px)); }
}

/* ------------------------------------------------------------------------
   One tile language for 服装 and 差分 (and the open emotion's 立绘 strip): a 12px corner, a 1.5px inset ring drawn over the
   art (an outfit's in a tint of the figure colour, an emotion's in its own colour), a 3px inset ring when selected, and
   one badge — a small frosted pill on the tile's top-left corner inside the art (「开场」, 「默认」). */
.ap-outfit-art, .ap-face-art { border-radius: 12px; }
.ap-map-state-art { border-radius: 10px; }
.ap-outfit-art { --tile-ring: color-mix(in srgb, var(--figure-color, var(--fork-accent)) 40%, transparent); }
.ap-outfit-art::after, .ap-map-state-art::after { content: ""; position: absolute; z-index: 1; inset: 0; border-radius: inherit; box-shadow: inset 0 0 0 1.5px var(--tile-ring, color-mix(in srgb, var(--fork-ink) 14%, transparent)); pointer-events: none; transition: box-shadow .15s; }
.ap-outfit-face[aria-checked=true] .ap-outfit-art::after { box-shadow: inset 0 0 0 3px var(--fork-accent); }
.ap-map-state[aria-checked=true] .ap-map-state-art::after { box-shadow: inset 0 0 0 3px var(--fork-accent); }
.ap-emotion-detail .ap-map-state[aria-checked=true] .ap-map-state-art::after { box-shadow: inset 0 0 0 3px var(--detail-color, var(--fork-accent)); }
.ap-outfit-add .ap-outfit-art::after, .ap-map-state-add .ap-map-state-art::after { content: none; }
/* 「默认」 — a CG's default variant — is one element badge (it carries a tooltip). The figure editor no longer shows one
   (figure select). */
.ap-tile-badge { position: absolute; z-index: 2; left: 4px; top: 4px; padding: 0 5px; border-radius: 6px; pointer-events: none;
  background: var(--fk-current-bgSolid, Canvas); color: var(--fork-ink); box-shadow: 0 1px 3px #00000024;
  font-size: 10px; font-weight: 600; line-height: 15px; letter-spacing: .02em; white-space: nowrap; }
.ap-tile-badge.is-inline { position: static; pointer-events: auto; background: var(--fork-hover); box-shadow: none; }
.ap-emotion-rest { display: none; }
/* A picture that could not be loaded (after one retry) is an empty dashed slot, never an endless spinner. */
.ap-art-missing { position: absolute; z-index: 1; inset: 0; box-sizing: border-box; border: 1.5px dashed var(--ap-border-strong); border-radius: inherit; background: var(--fk-current-bgSolid, Canvas); }
.ap-stand.ap-stand-missing { display: grid; place-items: center; color: var(--fork-ink-3, var(--fork-ink-2)); }
.ap-stand.ap-stand-missing > svg { width: 40%; height: 40%; }
/* 基础设定: the basic fields' heading, the 服装 / 差分 heading's style; the tabs' hairline above already separates it. */
.ap-fe-section.is-basic { margin-top: 4px; padding-top: 0; border-top: 0; }
/* The name row: name · lamp · ⋯ — its right edge is the 服装 / 差分 rows' (lamp or switch, then ⋯). */
.ap-title-tools { display: inline-flex; flex: none; align-items: center; gap: 4px; margin-left: auto; }
.ap-figure-menu .ap-popover { min-width: 168px; }
/* 形象色: the swatch only (the code is inside the picker). */
.ap-ui button.ap-swatch-button.ap-swatch-only { padding: 0 8px 0 7px; }
/* The asset actions on the preview card: the zoom cluster's own discs (button.ap-view-tool), on its top-right edge; a
   file action's input sits hidden beside its disc. An unavailable action keeps its disc (and its tooltip), its glyph faded. */
.ap-preview-actions { position: absolute; z-index: 2; right: 10px; top: 10px; display: flex; gap: 6px; }
.ap-preview-actions > input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); pointer-events: none; }
.ap-ui .ap-preview-actions button.ap-view-tool[aria-disabled=true] { color: var(--fork-ink-3, var(--fork-ink-2)); cursor: not-allowed; }
.ap-kind-menu-anchor .ap-menu-item .ap-glyph { flex: none; width: 14px; height: 14px; }
@media (prefers-reduced-motion: reduce) { .ap-outfit-art::after, .ap-map-state-art::after { transition: none; } }
@media (min-width: 721px) {
  /* 头像 (r7): the card takes the avatar's own square shape and the avatar fills it; the controls float on it. */
  .ap-stand-wrap[data-form=avatar] { height: var(--ap-card-w); }
}
@media (max-width: 720px) {
  .ap-ui .ap-fe-topbar { grid-template-columns: 36px minmax(0, 1fr) auto auto auto; gap: 0 2px; }
  .ap-ui .ap-fe-topbar > .ap-figure-menu > .ap-icon-button, .ap-ui .ap-fe-topbar > .ap-icon-button:last-child { width: 32px; }
  .ap-fe-section.is-basic { margin-top: 0; }
}
/* InlineField (inline-field.js),
