.fork-item-showcase.is-skin { z-index: 35; }
.fork-skin-item { position: absolute; animation: fork-skin-item-in var(--fork-skin-item-ms) cubic-bezier(.2, .7, .3, 1) both, fork-skin-item-out var(--fork-skin-item-ms) cubic-bezier(.7, 0, .8, .3) calc(2.8s - var(--fork-skin-item-ms)) forwards; }
@keyframes fork-skin-item-in { from { opacity: 0; transform: translateY(calc(var(--fork-skin-item-rise) * var(--fork-skin-item-travel, 1))); } }
@keyframes fork-skin-item-out { to { opacity: 0; transform: translateY(calc(var(--fork-skin-item-rise) * var(--fork-skin-item-travel, 1))); } }
.fork-skin-item-frame { position: absolute; inset: 0; width: 100%; height: 100%; }
