.fork-skin-item-media img { display: block; width: 100%; height: 100%; object-fit: contain; }
.fork-skin-item-toast { position: absolute; display: flex; align-items: center; justify-content: center; box-sizing: border-box; background: 0 0 / 100% 100% no-repeat; line-height: 1; white-space: nowrap;
  color: var(--fork-skin-item-ink, var(--gal-ui-hud-ink-on)); font-family: var(--gal-skin-font-ui, var(--gal-ui-font, inherit)); animation: fork-skin-item-toast var(--fork-skin-item-fade) linear both, fork-skin-item-toast-out var(--fork-skin-item-fade) linear calc(2.8s - var(--fork-skin-item-fade)) forwards; }
