@media (prefers-reduced-motion: reduce) and (update: none) { .fork-skin-item { --fork-skin-item-travel: 0; } }
.fork-item-history{position:absolute;top:65px;right:16px;z-index:35;padding:12px;background:var(--gal-ui-surface);color:var(--gal-ui-ink);font-size: var(--fork-fs-meta);max-width:260px}

/* one colour for every 差分 in the figure editor — tiles (filled,
   selected, missing), the preview chip, the open 差分, the 生图 slot and the voice page all use the theme accent; no
   per-差分 rainbow. */
.ap-figure-editor, .ap-gen-sheet { --emotion-color: var(--fork-accent); --chip-color: var(--fork-accent); --detail-color: var(--fork-accent); }
/* The prompt ✦ would send, verbatim and read-only: plain wrapped text, no box. */
.ap-gen-prompt { display: grid; gap: 4px; justify-items: start; min-width: 0; }
.ap-gen-prompt-text { box-sizing: border-box; width: 100%; max-height: 240px; margin: 0; overflow: auto; color: var(--fork-ink-2); font: inherit; font-size: var(--fork-fs-meta); line-height: 1.55; white-space: pre-wrap; overflow-wrap: anywhere; }
