.ap-ui .ap-fe-section > .ap-sub .ap-kind-menu-anchor > button.ap-icon-button { width: 28px; height: 28px; margin-right: -5px; border: 0; background: none; color: var(--fork-ink-2); }
.ap-ui .ap-fe-section > .ap-sub .ap-kind-menu-anchor > button.ap-icon-button:is(:hover, [aria-expanded=true]):not(:disabled) { background: var(--fork-hover); color: var(--fork-ink); }
.ap-ui .ap-fe-section > .ap-sub .ap-kind-menu-anchor > button.ap-icon-button:focus-visible { outline: 2px solid var(--fork-accent); outline-offset: 0; }
.ap-fe-section > .ap-sub .ap-kind-menu-anchor > button.ap-icon-button .ap-glyph { width: 16px; height: 16px; }
.ap-asset-kind-row { display: flex; margin: 0 0 12px; }
