.ap-tile-check { position: absolute; z-index: 2; left: 5px; top: 5px; background: var(--fk-current-bgSolid, Canvas);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--fork-ink) 45%, transparent); }
