.ap-fe-section.is-picking .ap-outfit-face[aria-checked=false] .ap-outfit-name, .ap-fe-section.is-picking .ap-face[aria-checked=false] .ap-face-name { color: var(--fork-ink-3, var(--fork-ink-2)); }
