.ap-section[data-level="2"] > .ap-section-head > h4 { display: flex; flex: 1; align-items: center; gap: 8px; min-width: 0; margin: 0; font-size: var(--fork-fs-body); font-weight: 500; color: var(--fork-ink-2); }
.ap-section[data-level="2"] > .ap-section-head > h4 .ap-section-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ap-mod-pack > .ap-section { margin-block: 4px; padding-block: 8px; border-top: 1px dashed var(--fork-hairline); }
