.ap-mod-strip-art img, .ap-mod-chip-art img, .ap-mod-hero-art img, .ap-mod-pick-thumb img, .ap-mod-art > .ap-outfit-face-art img { display: block; width: 100%; height: 100%; object-fit: contain; }
.ap-mod-pack-fields { margin-block: 4px 8px; }
