.ap-ui button.ap-mod-chip[aria-pressed="true"], .ap-ui button.ap-mod-chip[aria-checked="true"], .ap-ui button.ap-mod-chip[aria-pressed="true"]:hover, .ap-ui button.ap-mod-chip[aria-checked="true"]:hover { border-color: var(--fork-accent-fill); background: var(--fork-accent-fill); color: var(--fork-on-accent); font-weight: 500; }
.ap-mod-chip-art { display: block; flex: none; width: 22px; height: 22px; overflow: hidden; border-radius: 6px; }
