.ap-ui .ap-wizard-foot { position: sticky; bottom: 0; z-index: 3; display: flex; align-items: center; gap: 8px; margin-top: 8px; padding: 10px 0; border-top: 1px solid var(--ap-border); background: var(--fork-surface); }
