.fork-dm-stage { position: absolute; inset: 0; overflow: hidden; opacity: var(--fork-dm-opacity, .9); }
.fork-dm-item { position: absolute; left: 0; top: 0; white-space: nowrap; will-change: transform; color: var(--gal-dm-c, var(--gal-dm-ink));
  font-size: calc(var(--gal-dm-size-standard) * var(--fork-dm-scale, 1)); font-weight: 600; line-height: 1.3; letter-spacing: .01em;
  text-shadow: 1px 0 1px var(--gal-dm-halo), -1px 0 1px var(--gal-dm-halo), 0 1px 1px var(--gal-dm-halo), 0 -1px 1px var(--gal-dm-halo), 0 0 4px var(--gal-dm-halo-soft); }
.fork-dm-item[data-size="small"] { font-size: calc(var(--gal-dm-size-small) * var(--fork-dm-scale, 1)); }
