:is(.fork-dm-sc, .fork-dm-sc-pill)[data-tier="3"] { --sc-head: var(--gal-dm-sc-3-head); --sc-body: var(--gal-dm-sc-3-body); --sc-ink: var(--gal-dm-sc-3-ink); --sc-price: var(--gal-dm-sc-3-price); }
