:is(.fork-dm-sc, .fork-dm-sc-pill)[data-tier="5"] { --sc-head: var(--gal-dm-sc-5-head); --sc-body: var(--gal-dm-sc-5-body); --sc-ink: var(--gal-dm-sc-5-ink); --sc-price: var(--gal-dm-sc-5-price); }
