.fork-dm-sc-gem { flex: none; width: 7px; height: 7px; margin-left: auto; transform: rotate(45deg); border-radius: 1px; background: var(--sc-price); box-shadow: inset 0 0 0 1.5px var(--sc-head), 0 0 0 1px var(--sc-price); }
