.fork-dm-sc-time { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--sc-head); transform-origin: left; animation: fork-dm-drain linear both; }
.fork-dm-sc-head::after { content: ""; position: absolute; inset: 0; pointer-events: none; transform: translateX(-110%); background: linear-gradient(105deg, transparent 30%, var(--gal-dm-sc-sheen) 50%, transparent 70%); }
