.fork-lr-initial { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; background: var(--gal-dm-chip); color: var(--gal-dm-text-2); font-size: var(--gal-dm-badge-size); font-weight: 700; }
.fork-lr-user { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fork-lr-bar { position: absolute; left: 62px; right: 0; bottom: -4px; height: 2px; border-radius: 1px; background: var(--gal-dm-lr-bar); transform-origin: left; transition: transform .8s ease-out; }
.fork-lr-score { color: var(--gal-dm-text-2); font-size: var(--gal-dm-meta-size); }
/* A narrow band (a small window): the facts and the events give way first. */
@container (max-width: 1100px) { .fork-lr-facts { display: none; } }
@container (max-width: 760px) { .fork-lr-lane { display: none; } .fork-lr-tiles { grid-template-columns: 1fr 1fr 1fr; } .fork-lr-tile.is-top { display: none; } }

/* ---- float (phones, stages without a dock): glass over the picture, top-left under the top bar. */
.fork-lr[data-layout="float"] { --fork-lr-face: var(--gal-dm-lr-float-face); flex: none; order: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 8px; width: min(100% - 20px, 420px); margin: 0 10px;
  color: var(--gal-dm-on-glass); pointer-events: none; }
.fork-lr[data-layout="float"] .fork-lr-label { color: var(--gal-dm-on-glass-2); }
.fork-lr-cap { display: inline-flex; align-items: center; gap: 8px; max-width: min(100%, 300px); padding: 3px 12px 3px 3px; border-radius: 22px; background: var(--gal-dm-lr-plate); color: var(--gal-dm-lr-plate-ink); }
.fork-lr[data-layout="float"] .fork-lr-face { box-shadow: 0 0 0 1.5px var(--gal-dm-live); animation: none; }
.fork-lr[data-layout="float"][data-live="replay"] .fork-lr-face { box-shadow: 0 0 0 1.5px var(--gal-dm-on-glass-2); }
.fork-lr-who { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.fork-lr-who .fork-lr-name { font-size: var(--gal-dm-meta-size); }
.fork-lr-who .fork-lr-live { height: 18px; padding: 0 7px 0 6px; font-size: var(--gal-dm-badge-size); }
.fork-lr-mini { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; width: 100%; }
.fork-lr-mini-tile { position: relative; display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 6px 9px 8px; border-radius: 12px; background: var(--gal-dm-lr-plate); color: var(--gal-dm-lr-plate-ink); overflow: hidden; }
.fork-lr-mini-tile .fork-lr-roll { font-size: var(--gal-dm-lr-mini); }
.fork-lr-mini-tile .fork-lr-spark { width: 100%; height: 18px; }
.fork-lr-mini-tile .fork-lr-spark-dot { display: none; }
.fork-lr-mini-tile .fork-lr-bars { height: 18px; gap: 2px; }
.fork-lr-mini-tile .fork-lr-bars > i { background: var(--gal-dm-on-glass-2); }
.fork-lr-mini-tile .fork-lr-bars > i[data-now="true"] { background: var(--gal-dm-live); }
.fork-lr-mini-rank { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--gal-dm-sc-gold); font-size: var(--gal-dm-badge-size); font-weight: 600; }
.fork-lr-meter { position: absolute; left: 9px; right: 9px; bottom: 5px; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--gal-dm-sc-gold), var(--gal-dm-live)); transform-origin: left; transform: scaleX(0); transition: transform .8s ease; }
.fork-lr-toast:empty { display: none; }
.fork-lr-toast .fork-lr-ev { height: 28px; max-width: 100%; padding: 0 12px 0 4px; border-radius: 14px; background: linear-gradient(90deg, var(--gal-dm-welcome), transparent); color: var(--gal-dm-on-glass-2); }
.fork-lr-toast .fork-lr-ev-body b { color: var(--gal-dm-on-glass); }
.fork-lr[data-layout="float"] .fork-dm-warn { pointer-events: auto; }
/* The floating console's own capsule gives way to the bar. */
.fork-dm-console[data-bar="float"] > .fork-dm-head { display: none; }

/* The one quick entry (danmaku-ui.js): the danmaku switch icon in the top bar, the same HUD button as 电影模式 /
   特效; accent while a view is on, plain with a ⊘ cut while 关闭. Its menu is an opaque stage sheet (R15). */
.fork-gal-danmaku-anchor { position: relative; }
.fork-gal-stage .fork-gal-danmaku { position: relative; display: grid; place-items: center; box-sizing: border-box; width: 30px; height: 30px; margin: 0; padding: 0; border: 0; border-radius: 50%; background: none; box-shadow: none; color: var(--gal-ui-hud-ink); cursor: pointer; filter: var(--gal-ui-hud-glow); transition: color .25s, background .15s; }
.fork-gal-stage .fork-gal-danmaku:is(:hover, :focus-visible, [aria-expanded="true"]) { background: var(--gal-ui-hud-hover); color: var(--gal-ui-hud-ink-on); filter: var(--gal-ui-hud-glow-on); }
.fork-gal-stage .fork-gal-danmaku:focus-visible { outline: 2px solid var(--gal-ui-hud-ink-on); outline-offset: 1px; }
.fork-gal-stage .fork-gal-danmaku:not([data-view="off"]) { color: var(--gal-ui-hud-active); }
.fork-gal-stage .fork-gal-danmaku[data-warn] { color: var(--gal-ui-hud-warning); }
.fork-gal-danmaku-icon { display: block; }
.fork-gal-danmaku-cut { stroke-width: 1.6; }
.fork-gal-danmaku-menu { position: absolute; top: calc(100% + 10px); right: -4px; z-index: 3; box-sizing: border-box; min-width: 156px; padding: 4px; border-radius: min(var(--gal-ui-radius), 14px);
  background: var(--gal-ui-surface-2); color: var(--gal-ui-ink); box-shadow: var(--gal-ui-shadow), inset 0 0 0 1px var(--gal-ui-line); font-family: var(--gal-ui-font); cursor: default; animation: fork-dm-in .16s ease-out; }
.fork-gal-danmaku-item { display: flex; align-items: center; gap: 8px; box-sizing: border-box; width: 100%; min-height: 32px; padding: 0 10px 0 28px; border: 0; border-radius: calc(min(var(--gal-ui-radius), 14px) - 4px); background: none; color: inherit; font: inherit; font-size: var(--fork-fs-body); text-align: left; cursor: pointer; position: relative; }
.fork-gal-danmaku-item:is(:hover, :focus-visible) { background: var(--gal-ui-hover); outline: none; }
.fork-gal-danmaku-item[aria-checked="true"] { color: var(--gal-ui-accent); }
